CREATE OR REPLACE FUNCTION public.assert_admin_catalog_authority(actor uuid, session_id uuid, event_time timestamp with time zone, causal_bound timestamp with time zone, permission text, locales supported_locale[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE session public.admin_sessions%ROWTYPE; active_status text; granted integer;
BEGIN
 SELECT * INTO session FROM public.admin_sessions WHERE id=session_id FOR SHARE;
 SELECT status INTO active_status FROM public.admin_identities WHERE id=actor FOR SHARE;
 IF session.id IS NULL OR session.admin_identity_id IS DISTINCT FROM actor OR active_status IS DISTINCT FROM 'ACTIVE' OR NOT session.authenticated_with_mfa OR session.revoked_at IS NOT NULL
 OR session.expires_at<=clock_timestamp() OR session.created_at>clock_timestamp() OR event_time<session.created_at OR event_time>=session.expires_at
 OR event_time>GREATEST(clock_timestamp(),transaction_timestamp(),session.created_at,causal_bound) THEN RAISE EXCEPTION 'management operation requires current active MFA session and causal time' USING ERRCODE='23514'; END IF;
 PERFORM ar.role_id FROM public.admin_identity_roles ar JOIN public.roles r ON r.id=ar.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
 WHERE ar.admin_identity_id=actor AND p.permission_key=permission AND ar.granted_at<=clock_timestamp() AND rp.granted_at<=clock_timestamp() AND ar.granted_at<=event_time AND rp.granted_at<=event_time FOR SHARE OF ar,r,rp,p;
 IF NOT FOUND THEN RAISE EXCEPTION 'management operation requires its current permission' USING ERRCODE='23514'; END IF;
 PERFORM locale FROM public.admin_content_locale_grants WHERE admin_identity_id=actor AND revoked_at IS NULL AND locale=ANY(locales) AND granted_at<=clock_timestamp() AND granted_at<=event_time FOR SHARE;
 GET DIAGNOSTICS granted=ROW_COUNT;
 IF granted<>cardinality(locales) THEN RAISE EXCEPTION 'management operation requires its current locale scopes' USING ERRCODE='23514'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_content_locale_grant_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE audit public.audit_logs%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at THEN RETURN NULL; END IF;
    SELECT * INTO audit FROM public.audit_logs WHERE id = NEW.revoked_audit_log_id;
    IF audit.id IS NULL OR audit.action <> 'CONTENT_LOCALE_REVOKE' OR audit.created_at <> NEW.revoked_at THEN
      RAISE EXCEPTION 'locale revocation requires exact audit' USING ERRCODE = '23514';
    END IF;
  ELSE
  SELECT * INTO audit FROM public.audit_logs WHERE id = NEW.audit_log_id;
    IF audit.id IS NULL OR audit.action <> 'CONTENT_LOCALE_GRANT' OR audit.created_at <> NEW.granted_at THEN
      RAISE EXCEPTION 'locale grant requires exact audit' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF audit.id IS NULL OR audit.actor_type <> 'ADMIN'
    OR (TG_OP = 'INSERT' AND audit.actor_id IS DISTINCT FROM NEW.granted_by)
    OR audit.subject_type <> 'ADMIN_CONTENT_LOCALE_GRANT'
    OR audit.subject_id <> NEW.admin_identity_id OR audit.outcome <> 'SUCCEEDED'
    OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS NULL
    OR audit.field_category IS DISTINCT FROM 'CONTENT_TRANSLATION'
    OR NOT EXISTS (SELECT 1 FROM public.admin_identities WHERE id = audit.actor_id AND status = 'ACTIVE')
    OR (TG_OP = 'INSERT' AND NOT EXISTS (SELECT 1 FROM public.admin_identities WHERE id = NEW.admin_identity_id AND status = 'ACTIVE')) THEN
    RAISE EXCEPTION 'content locale grant requires exact active actor audit' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_finance_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE a audit_logs%ROWTYPE; op admin_finance_operations%ROWTYPE;
BEGIN
 SELECT * INTO a FROM audit_logs WHERE id=NEW.audit_log_id;SELECT * INTO op FROM admin_finance_operations WHERE id=NEW.operation_id;
 IF NOT public.admin_order_authorized(NEW.session_id,NEW.actor_id,'orders.read',NEW.created_at) OR NOT public.admin_order_authorized(NEW.session_id,NEW.actor_id,'finance.manage',NEW.created_at) OR a.actor_type IS DISTINCT FROM 'ADMIN' OR a.actor_id IS DISTINCT FROM NEW.actor_id OR a.outcome IS DISTINCT FROM 'SUCCEEDED' OR a.reason_code IS DISTINCT FROM NEW.reason_code OR a.request_id IS DISTINCT FROM NEW.request_id OR a.correlation_id IS DISTINCT FROM NEW.correlation_id OR a.created_at IS DISTINCT FROM NEW.created_at OR op.order_id IS DISTINCT FROM NEW.order_id OR op.refund_id IS DISTINCT FROM NEW.refund_id THEN RAISE EXCEPTION 'financial operation requires exact live authority and audit' USING ERRCODE='23514';END IF;
 IF (NEW.action IN('CANCEL','RECONCILE') AND (a.action IS DISTINCT FROM 'FINANCE_'||NEW.action||'_REQUESTED' OR a.subject_type IS DISTINCT FROM 'ORDER' OR a.subject_id IS DISTINCT FROM NEW.order_id)) OR (NEW.action IN('REFUND','CANCEL') AND op.action IS DISTINCT FROM NEW.action) OR (NEW.action='RECONCILE' AND NOT ((op.action='REFUND' AND op.refund_id IS NOT NULL) OR (op.action='RECONCILE' AND op.refund_id IS NULL))) THEN RAISE EXCEPTION 'financial receipt must retain exact operation and requested audit action' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM orders o WHERE o.id=NEW.order_id AND o.version=NEW.expected_order_version+CASE WHEN NEW.action='CANCEL' AND op.phase='COMPLETE' AND o.order_status='CANCELED' THEN 1 ELSE 0 END) THEN RAISE EXCEPTION 'financial receipt requires exact expected order version' USING ERRCODE='23514';END IF;
 IF NEW.action='REFUND' AND (a.action IS DISTINCT FROM 'REFUND_REQUESTED' OR a.subject_type IS DISTINCT FROM 'REFUND' OR a.subject_id IS DISTINCT FROM NEW.refund_id OR NOT EXISTS(SELECT 1 FROM refunds r WHERE r.id=NEW.refund_id AND r.order_id=NEW.order_id AND r.requested_audit_log_id=NEW.audit_log_id)) THEN RAISE EXCEPTION 'refund receipt must bind exact request audit' USING ERRCODE='23514';END IF;
 RETURN NULL;
END;$function$

CREATE OR REPLACE FUNCTION public.assert_admin_idol_prior()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE prior public.idols%ROWTYPE;
BEGIN
 SELECT * INTO prior FROM public.idols WHERE id=NEW.idol_id FOR UPDATE;
 IF NEW.action='CREATE_IDOL' THEN
  IF prior.id IS NOT NULL THEN RAISE EXCEPTION 'identity creation receipt requires an absent identity' USING ERRCODE='23514'; END IF;
 ELSE
  IF prior.id IS NULL OR prior.version IS DISTINCT FROM NEW.expected_base_version
   OR prior.handle IS DISTINCT FROM NEW.old_handle OR prior.status IS DISTINCT FROM NEW.old_status OR prior.accepting_gifts IS DISTINCT FROM NEW.old_accepting_gifts
   OR prior.updated_at IS DISTINCT FROM NEW.previous_updated_at OR prior.draft_revision_id IS DISTINCT FROM NEW.draft_revision_id OR prior.published_revision_id IS DISTINCT FROM NEW.published_revision_id
   THEN RAISE EXCEPTION 'identity receipt requires the exact locked prior identity before mutation' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_idol_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE idol public.idols%ROWTYPE; audit public.audit_logs%ROWTYPE; redirect public.slug_redirects%ROWTYPE; actual_authoring bigint; actual_head bigint; proof jsonb; dependency jsonb;
BEGIN
 SELECT * INTO idol FROM public.idols WHERE id=NEW.idol_id FOR UPDATE;
 SELECT * INTO audit FROM public.audit_logs WHERE id=NEW.audit_log_id;
 SELECT coalesce(max(revision),0) INTO actual_authoring FROM public.idol_revisions WHERE idol_id=NEW.idol_id;
 SELECT coalesce(max(version),0) INTO actual_head FROM public.idol_publication_heads WHERE idol_id=NEW.idol_id;
 IF idol.id IS NULL OR idol.version IS DISTINCT FROM NEW.result_base_version OR idol.handle IS DISTINCT FROM NEW.new_handle OR idol.status IS DISTINCT FROM NEW.new_status OR idol.accepting_gifts IS DISTINCT FROM NEW.new_accepting_gifts
 OR idol.draft_revision_id IS DISTINCT FROM NEW.draft_revision_id OR idol.published_revision_id IS DISTINCT FROM NEW.published_revision_id OR idol.updated_at IS DISTINCT FROM NEW.created_at
 OR actual_authoring IS DISTINCT FROM NEW.authoring_version OR actual_head IS DISTINCT FROM NEW.publication_head_version THEN RAISE EXCEPTION 'idol receipt must match the complete canonical identity and versions' USING ERRCODE='23514'; END IF;
 IF audit.id IS NULL OR audit.actor_type IS DISTINCT FROM 'ADMIN' OR audit.actor_id IS DISTINCT FROM NEW.actor_id OR audit.action IS DISTINCT FROM NEW.action OR audit.subject_type IS DISTINCT FROM 'IDOL_IDENTITY' OR audit.subject_id IS DISTINCT FROM NEW.idol_id OR audit.created_at IS DISTINCT FROM NEW.created_at OR audit.outcome IS DISTINCT FROM 'SUCCEEDED' OR audit.field_category IS DISTINCT FROM 'CONTENT_IDENTITY' OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS DISTINCT FROM audit.request_id THEN RAISE EXCEPTION 'idol operation requires exact safe audit evidence' USING ERRCODE='23514'; END IF;
 IF (NEW.action='CREATE_IDOL') IS DISTINCT FROM (NEW.previous_updated_at IS NULL) OR NEW.created_at<NEW.previous_updated_at THEN RAISE EXCEPTION 'identity receipt requires exact prior causal time' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_admin_catalog_authority(NEW.actor_id,NEW.session_id,NEW.created_at,NEW.previous_updated_at,'content.edit',ARRAY['en','zh-CN','th','vi','ja','es','pt']::public.supported_locale[]);
 IF NEW.action='RENAME_IDOL' THEN
  SELECT * INTO redirect FROM public.slug_redirects WHERE id=NEW.redirect_id;
  IF redirect.id IS NULL OR redirect.entity_type IS DISTINCT FROM 'IDOL' OR redirect.idol_id IS DISTINCT FROM NEW.idol_id OR redirect.old_handle IS DISTINCT FROM NEW.old_handle OR redirect.new_handle IS DISTINCT FROM NEW.new_handle OR redirect.created_at IS DISTINCT FROM NEW.created_at THEN RAISE EXCEPTION 'rename requires its immutable same-owner redirect' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.action='SET_IDOL_STATUS' AND NEW.new_status='active' THEN
  SELECT m.manifest INTO proof FROM public.idol_publication_heads h JOIN public.content_publications p ON p.id=h.publication_id AND p.idol_id=h.idol_id AND p.idol_revision_id=h.idol_revision_id JOIN public.content_publication_manifests m ON m.publication_id=p.id JOIN public.content_publication_receipts r ON r.manifest_id=m.id AND r.publication_id=p.id AND r.result_head_version=h.version
   WHERE h.idol_id=NEW.idol_id AND h.idol_revision_id=NEW.published_revision_id AND p.proof_version=2;
  IF proof IS NULL THEN RAISE EXCEPTION 'activation requires a current verified publication' USING ERRCODE='23514'; END IF;
  PERFORM public.assert_publication_manifest_revision(proof->'revision');
  FOR dependency IN SELECT * FROM jsonb_array_elements(proof->'mediaRevisions') LOOP PERFORM public.assert_publication_manifest_revision(dependency); END LOOP;
  PERFORM public.assert_publication_manifest_approvals(proof);
  PERFORM public.assert_publication_manifest_media(proof);
 END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_login_challenge_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE a public.audit_logs%ROWTYPE; s public.admin_sessions%ROWTYPE;
BEGIN
  IF NEW.state<>'CONSUMED' THEN RETURN NEW; END IF;
  SELECT * INTO a FROM public.audit_logs WHERE id=NEW.audit_log_id;
  IF a.id IS NULL OR a.actor_type<>'SYSTEM' OR a.task_name<>'admin-access' OR a.subject_type<>'ADMIN_LOGIN_CHALLENGE'
    OR a.subject_id<>NEW.id OR a.created_at<>NEW.completed_at OR a.request_id IS NULL OR a.correlation_id IS DISTINCT FROM NEW.id THEN
    RAISE EXCEPTION 'login completion requires exact immutable audit' USING ERRCODE='23514';
  END IF;
  IF NEW.session_id IS NULL THEN
    IF a.action<>'ADMIN_LOGIN_REJECTED' OR a.outcome<>'REJECTED' OR a.reason_code IS NULL OR a.reason_code NOT IN ('ACCESS_DENIED','LOGIN_EXPIRED','IDENTITY_REJECTED','MFA_REQUIRED','AUTHENTICATION_EXPIRED') THEN
      RAISE EXCEPTION 'login rejection audit is required' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO s FROM public.admin_sessions WHERE id=NEW.session_id;
    IF a.action<>'ADMIN_LOGIN_SUCCEEDED' OR a.outcome<>'SUCCEEDED' OR a.reason_code IS DISTINCT FROM 'AUTHENTICATED'
      OR NEW.completed_at>=NEW.expires_at OR s.id IS NULL OR NOT s.authenticated_with_mfa OR s.created_at<>NEW.completed_at OR s.revoked_at IS NOT NULL
      OR s.expires_at<s.created_at+interval '60 seconds' OR s.expires_at>s.created_at+interval '28800 seconds'
      OR octet_length(s.session_token_digest)<>32 OR octet_length(s.csrf_token_digest)<>32
      OR NOT EXISTS(SELECT 1 FROM public.admin_identities WHERE id=s.admin_identity_id AND status='ACTIVE') THEN
      RAISE EXCEPTION 'login success requires canonical active MFA session' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.assert_admin_notification_resend()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE target uuid; dispatch public.admin_notification_resends%ROWTYPE; attempts bigint; last_outcome text;
BEGIN
 target:=coalesce((to_jsonb(NEW)->>'resend_id')::uuid,(to_jsonb(NEW)->>'id')::uuid);
 SELECT * INTO dispatch FROM public.admin_notification_resends WHERE id=target;
 SELECT count(*) INTO attempts FROM public.admin_notification_resend_attempts WHERE resend_id=target;
 SELECT outcome INTO last_outcome FROM public.admin_notification_resend_attempts WHERE resend_id=target ORDER BY sequence DESC LIMIT 1;
 IF dispatch.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.admin_notification_resend_outbox q WHERE q.resend_id=target AND q.created_at=dispatch.created_at)
 OR attempts<>dispatch.attempt_count
 OR (attempts>0 AND (SELECT max(sequence) FROM public.admin_notification_resend_attempts WHERE resend_id=target)<>attempts)
 OR (dispatch.status='SENT' AND last_outcome IS DISTINCT FROM 'SUCCEEDED')
 OR (dispatch.status IN('FAILED','RETRY_SCHEDULED') AND last_outcome IS DISTINCT FROM 'FAILED' AND last_outcome IS DISTINCT FROM 'UNKNOWN')
 OR (dispatch.link_token_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.order_access_tokens t WHERE t.id=dispatch.link_token_id AND t.order_id=dispatch.order_id AND t.purpose='LINK' AND t.token_pepper_version=dispatch.link_pepper_version))
 THEN RAISE EXCEPTION 'resend queue, link and attempts must agree' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.assert_admin_order_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE a public.audit_logs%ROWTYPE; s public.admin_sessions%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.audit_logs WHERE id=NEW.audit_log_id;
 SELECT * INTO s FROM public.admin_sessions WHERE id=NEW.session_id;
 IF a.actor_type IS DISTINCT FROM 'ADMIN' OR a.actor_id IS DISTINCT FROM NEW.actor_id OR a.subject_type IS DISTINCT FROM 'ORDER' OR a.subject_id IS DISTINCT FROM NEW.order_id OR a.action IS DISTINCT FROM 'ORDER_PRIVATE_READ' OR a.field_category IS DISTINCT FROM 'ORDER_PRIVATE' OR a.outcome IS DISTINCT FROM 'SUCCEEDED' OR a.created_at IS DISTINCT FROM NEW.created_at OR a.request_id IS DISTINCT FROM NEW.request_id OR a.correlation_id IS DISTINCT FROM NEW.correlation_id OR s.admin_identity_id IS DISTINCT FROM NEW.actor_id THEN RAISE EXCEPTION 'private order read requires exact session and audit' USING ERRCODE='23514'; END IF;
 IF NEW.kind='MESSAGE' AND NOT EXISTS(SELECT 1 FROM public.order_items i JOIN public.support_intents intent ON intent.id=i.support_intent_id WHERE i.id=NEW.item_id AND i.order_id=NEW.order_id AND intent.id=NEW.support_intent_id AND intent.version=NEW.intent_version AND intent.privacy_state='ACTIVE' AND public.cart_private_material_hash(intent.fan_message_ciphertext,intent.display_mode,intent.display_name_ciphertext,intent.encrypted_data_key,intent.encryption_key_version,intent.fan_message_locale)=NEW.material_hash) THEN RAISE EXCEPTION 'private access must bind exact active content' USING ERRCODE='23514'; END IF;
 IF NEW.kind='NOTES' AND EXISTS(SELECT 1 FROM unnest(NEW.note_ids) id WHERE NOT EXISTS(SELECT 1 FROM public.admin_order_notes n WHERE n.id=id AND n.order_id=NEW.order_id)) THEN RAISE EXCEPTION 'note access must bind exact order membership' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_order_fulfillment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE e public.fulfillment_events%ROWTYPE; target text;
BEGIN
 SELECT * INTO e FROM public.fulfillment_events WHERE id=NEW.fulfillment_event_id;
 target:=CASE NEW.action WHEN 'PREPARE' THEN 'PREPARING' WHEN 'DELIVER' THEN 'DELIVERED' WHEN 'HOLD' THEN 'ON_HOLD' ELSE e.to_status END;
 IF e.order_id IS DISTINCT FROM NEW.order_id OR e.fulfillment_id IS DISTINCT FROM NEW.fulfillment_id OR e.sequence IS DISTINCT FROM NEW.expected_fulfillment_version+1 OR e.authority_kind IS DISTINCT FROM 'ADMIN' OR e.admin_identity_id IS DISTINCT FROM NEW.actor_id OR e.audit_log_id IS DISTINCT FROM NEW.audit_log_id OR e.reason_code IS DISTINCT FROM NEW.reason_code OR e.occurred_at IS DISTINCT FROM NEW.created_at OR e.to_status IS DISTINCT FROM target THEN RAISE EXCEPTION 'order fulfillment receipt must bind exact event' USING ERRCODE='23514'; END IF;
 IF NEW.action='RESUME' AND NOT EXISTS(SELECT 1 FROM public.fulfillment_events previous JOIN public.admin_order_fulfillment_receipts receipt ON receipt.fulfillment_event_id=previous.id WHERE previous.fulfillment_id=e.fulfillment_id AND previous.sequence=e.sequence-1 AND previous.to_status='ON_HOLD' AND previous.from_status=e.to_status AND receipt.action='HOLD') THEN RAISE EXCEPTION 'only an owned manager hold may resume' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.outbox_events x WHERE x.id=NEW.outbox_event_id AND x.event_type='FULFILLMENT_STATUS_CHANGED' AND x.aggregate_id=e.fulfillment_id AND x.aggregate_version=e.sequence AND x.secondary_subject_id=e.order_id AND x.primary_subject_id=e.fulfillment_id AND x.payload_status=e.to_status AND x.request_id=e.request_id AND x.correlation_id=e.correlation_id AND x.occurred_at=e.occurred_at) THEN RAISE EXCEPTION 'fulfillment requires exact transactional outbox' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_order_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE a public.audit_logs%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.audit_logs WHERE id=NEW.audit_log_id;
 IF a.actor_type IS DISTINCT FROM 'ADMIN' OR a.actor_id IS DISTINCT FROM NEW.actor_id OR a.outcome IS DISTINCT FROM 'SUCCEEDED' OR a.created_at IS DISTINCT FROM NEW.created_at OR a.request_id IS DISTINCT FROM NEW.request_id OR a.correlation_id IS DISTINCT FROM NEW.correlation_id OR NOT EXISTS(SELECT 1 FROM public.admin_sessions WHERE id=NEW.session_id AND admin_identity_id=NEW.actor_id) THEN RAISE EXCEPTION 'order operation receipt requires exact authority' USING ERRCODE='23514'; END IF;
 IF NOT(CASE NEW.action WHEN 'ADD_NOTE' THEN EXISTS(SELECT 1 FROM public.admin_order_notes r WHERE r.id=NEW.result_id AND r.order_id=NEW.order_id AND r.actor_id=NEW.actor_id AND r.session_id=NEW.session_id AND r.audit_log_id=NEW.audit_log_id AND r.created_at=NEW.created_at)
 WHEN 'REVIEW_MESSAGE' THEN EXISTS(SELECT 1 FROM public.admin_order_message_reviews r WHERE r.id=NEW.result_id AND r.order_id=NEW.order_id AND r.actor_id=NEW.actor_id AND r.session_id=NEW.session_id AND r.audit_log_id=NEW.audit_log_id AND r.created_at=NEW.created_at)
 ELSE EXISTS(SELECT 1 FROM public.admin_order_fulfillment_receipts r WHERE r.id=NEW.result_id AND r.order_id=NEW.order_id AND r.actor_id=NEW.actor_id AND r.session_id=NEW.session_id AND r.action=NEW.action AND r.audit_log_id=NEW.audit_log_id AND r.created_at=NEW.created_at) END) THEN RAISE EXCEPTION 'order operation receipt result must be exact' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_order_receipt_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE required_permission text; intent public.support_intents%ROWTYPE; a public.admin_order_private_accesses%ROWTYPE;
BEGIN
 required_permission:=CASE TG_TABLE_NAME WHEN 'admin_order_notes' THEN 'orders.note'
 WHEN 'admin_order_private_accesses' THEN CASE to_jsonb(NEW)->>'kind' WHEN 'MESSAGE' THEN 'orders.message.read' ELSE 'orders.note' END
 WHEN 'admin_order_message_reviews' THEN 'orders.message.review'
 WHEN 'admin_order_fulfillment_receipts' THEN CASE WHEN to_jsonb(NEW)->>'action' IN('HOLD','RESUME') THEN 'orders.manage' ELSE 'orders.fulfillment' END END;
 IF NOT public.admin_order_authorized(NEW.session_id,NEW.actor_id,'orders.read',NEW.created_at)
 OR NOT public.admin_order_authorized(NEW.session_id,NEW.actor_id,required_permission,NEW.created_at) THEN
 RAISE EXCEPTION 'order receipt requires current canonical session permission' USING ERRCODE='23514'; END IF;
 IF (TG_TABLE_NAME='admin_order_private_accesses' AND to_jsonb(NEW)->>'kind'='MESSAGE') OR TG_TABLE_NAME='admin_order_message_reviews' THEN
  SELECT * INTO intent FROM public.support_intents WHERE id=NEW.support_intent_id;
  IF NOT EXISTS(SELECT 1 FROM public.admin_order_message_locale_grants WHERE admin_identity_id=NEW.actor_id AND locale=NEW.review_locale AND revoked_at IS NULL AND granted_at<=NEW.created_at)
   OR (intent.fan_message_locale<>NEW.review_locale AND NOT public.admin_order_authorized(NEW.session_id,NEW.actor_id,'orders.message.triage',NEW.created_at)) THEN
   RAISE EXCEPTION 'order message requires explicit language and triage authority' USING ERRCODE='23514'; END IF;
 END IF;
 IF TG_TABLE_NAME='admin_order_private_accesses' THEN
  IF NEW.expires_at>(SELECT expires_at FROM public.admin_sessions WHERE id=NEW.session_id) THEN
   RAISE EXCEPTION 'private read may not outlive its session' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_admin_order_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE intent public.support_intents%ROWTYPE; access public.admin_order_private_accesses%ROWTYPE; a public.audit_logs%ROWTYPE;
BEGIN
 SELECT * INTO intent FROM public.support_intents WHERE id=NEW.support_intent_id;
 SELECT * INTO access FROM public.admin_order_private_accesses WHERE id=NEW.access_id;
 SELECT * INTO a FROM public.audit_logs WHERE id=NEW.audit_log_id;
 IF intent.version IS DISTINCT FROM NEW.result_intent_version OR intent.moderation_status IS DISTINCT FROM NEW.decision OR intent.moderation_decision_kind IS DISTINCT FROM 'HUMAN' OR intent.moderation_reviewer_id IS DISTINCT FROM NEW.actor_id OR intent.reviewed_at IS DISTINCT FROM NEW.created_at OR intent.privacy_state IS DISTINCT FROM 'ACTIVE'
 OR access.kind IS DISTINCT FROM 'MESSAGE' OR access.actor_id IS DISTINCT FROM NEW.actor_id OR access.session_id IS DISTINCT FROM NEW.session_id OR access.order_id IS DISTINCT FROM NEW.order_id OR access.item_id IS DISTINCT FROM NEW.item_id OR access.support_intent_id IS DISTINCT FROM NEW.support_intent_id OR access.intent_version IS DISTINCT FROM NEW.expected_intent_version OR access.review_locale IS DISTINCT FROM NEW.review_locale OR access.expires_at<=clock_timestamp() OR NOT EXISTS(SELECT 1 FROM public.admin_order_private_confirmations WHERE access_id=access.id)
 OR NOT EXISTS(SELECT 1 FROM public.admin_order_message_locale_grants WHERE admin_identity_id=NEW.actor_id AND locale=NEW.review_locale AND revoked_at IS NULL AND granted_at<=clock_timestamp())
 OR a.actor_type IS DISTINCT FROM 'ADMIN' OR a.actor_id IS DISTINCT FROM NEW.actor_id OR a.action IS DISTINCT FROM 'ORDER_MESSAGE_REVIEWED' OR a.subject_type IS DISTINCT FROM 'SUPPORT_INTENT' OR a.subject_id IS DISTINCT FROM NEW.support_intent_id OR a.reason_code IS DISTINCT FROM NEW.reason_code OR a.outcome IS DISTINCT FROM 'SUCCEEDED' OR a.created_at IS DISTINCT FROM NEW.created_at THEN RAISE EXCEPTION 'review requires exact private access, language, mutation and audit' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_base_content_preview_grant_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE audit public.audit_logs%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO audit FROM public.audit_logs WHERE id = NEW.audit_log_id;
    IF audit.id IS NULL OR audit.action <> 'BASE_CONTENT_PREVIEW_ISSUE' OR audit.created_at <> NEW.created_at THEN
      RAISE EXCEPTION 'preview issuance requires exact audit' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at THEN RETURN NULL; END IF;
    SELECT * INTO audit FROM public.audit_logs WHERE id = NEW.revoked_audit_log_id;
    IF audit.id IS NULL OR audit.action <> 'BASE_CONTENT_PREVIEW_REVOKE' OR audit.created_at <> NEW.revoked_at THEN
      RAISE EXCEPTION 'preview revocation requires exact audit' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF audit.id IS NULL OR audit.actor_type <> 'ADMIN' OR audit.actor_id IS DISTINCT FROM NEW.actor_id
    OR audit.subject_type <> 'BASE_CONTENT_PREVIEW_GRANT' OR audit.subject_id <> NEW.id OR audit.outcome <> 'SUCCEEDED'
    OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS NULL THEN
    RAISE EXCEPTION 'preview grant requires exact actor and subject audit' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_base_content_review_boundary()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE translation_id uuid; parent_id uuid; authored boolean; copied boolean; receipted boolean;
BEGIN
  IF NEW.sequence=1 THEN RETURN NULL; END IF;
  translation_id := (to_jsonb(NEW)->>TG_ARGV[1])::uuid;
  EXECUTE format('SELECT %I FROM %s WHERE id=$1',TG_ARGV[3],TG_ARGV[0]::regclass) INTO parent_id USING translation_id;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.content_authoring_receipts WHERE %I=$1)',TG_ARGV[3]) INTO authored USING parent_id;
  IF NOT authored THEN RETURN NULL; END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s WHERE target_translation_id=$1)',TG_ARGV[4]::regclass) INTO copied USING translation_id;
  -- 0015 independently proves all three original review events and their exact source FK.
  IF copied THEN RETURN NULL; END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.base_content_review_receipts WHERE %I=$1)',TG_ARGV[5]) INTO receipted USING NEW.id;
  IF NOT receipted THEN RAISE EXCEPTION 'authored translation review requires exact audit receipt' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_base_content_review_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE kind text; parent_column text; translation_column text; review_id uuid; event jsonb; translation jsonb; parent jsonb; previous jsonb; audit public.audit_logs%ROWTYPE; english_hash public.sha256_hex; authored boolean; action text;
BEGIN
  IF NEW.idol_review_id IS NOT NULL THEN kind:='idol'; parent_column:='idol_revision_id'; translation_column:='idol_translation_id'; review_id:=NEW.idol_review_id;
  ELSIF NEW.gift_review_id IS NOT NULL THEN kind:='gift'; parent_column:='gift_revision_id'; translation_column:='gift_translation_id'; review_id:=NEW.gift_review_id;
  ELSIF NEW.homepage_review_id IS NOT NULL THEN kind:='homepage'; parent_column:='homepage_revision_id'; translation_column:='homepage_translation_id'; review_id:=NEW.homepage_review_id;
  ELSIF NEW.policy_review_id IS NOT NULL THEN kind:='policy'; parent_column:='policy_revision_id'; translation_column:='policy_translation_id'; review_id:=NEW.policy_review_id;
  ELSIF NEW.media_metadata_review_id IS NOT NULL THEN kind:='media_metadata'; parent_column:='media_metadata_revision_id'; translation_column:='media_metadata_translation_id'; review_id:=NEW.media_metadata_review_id;
  END IF;
  EXECUTE format('SELECT to_jsonb(r.*),to_jsonb(t.*),to_jsonb(p.*) FROM public.%I r JOIN public.%I t ON t.id=r.%I JOIN public.%I p ON p.id=t.%I WHERE r.id=$1',kind||'_translation_reviews',kind||'_revision_translations',translation_column,kind||'_revisions',parent_column) INTO event,translation,parent USING review_id;
  IF event IS NULL THEN RAISE EXCEPTION 'base review receipt requires its exact event' USING ERRCODE='23503'; END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.content_authoring_receipts WHERE %I=$1)',parent_column) INTO authored USING (parent->>'id')::uuid;
  IF NOT authored OR parent->>'lifecycle'<>'DRAFT' OR event->>'status' NOT IN ('IN_REVIEW','APPROVED') THEN
    RAISE EXCEPTION 'new base review requires an authored draft' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT source_hash FROM public.%I WHERE %I=$1 AND locale=''en''',kind||'_revision_translations',parent_column) INTO english_hash USING (parent->>'id')::uuid;
  IF english_hash IS NULL OR translation->>'translated_from_source_hash'<>english_hash THEN
    RAISE EXCEPTION 'base review requires actual current English source' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT to_jsonb(r.*) FROM public.%I r WHERE %I=$1 AND sequence<$2 ORDER BY sequence DESC LIMIT 1',kind||'_translation_reviews',translation_column) INTO previous USING (translation->>'id')::uuid,(event->>'sequence')::bigint;
  IF NEW.created_at<>(event->>'created_at')::timestamptz OR NEW.created_at<GREATEST((parent->>'created_at')::timestamptz,(translation->>'edited_at')::timestamptz,(previous->>'created_at')::timestamptz,(previous->>'submitted_at')::timestamptz,(previous->>'reviewed_at')::timestamptz)
    OR NEW.field_paths IS DISTINCT FROM ARRAY['translations.'||(translation->>'locale')||'.review'] THEN
    RAISE EXCEPTION 'base review receipt requires exact causal time and field path' USING ERRCODE='23514';
  END IF;
  action:=CASE WHEN event->>'status'='IN_REVIEW' THEN 'BASE_CONTENT_REVIEW_SUBMIT' ELSE 'BASE_CONTENT_REVIEW_APPROVE' END;
  SELECT * INTO audit FROM public.audit_logs WHERE id=NEW.audit_log_id;
  IF audit.id IS NULL OR audit.actor_type<>'ADMIN' OR audit.action<>action OR audit.subject_type<>'BASE_CONTENT_TRANSLATION_REVIEW' OR audit.subject_id<>review_id
    OR audit.outcome<>'SUCCEEDED' OR audit.created_at<>NEW.created_at OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS NULL OR audit.field_category IS DISTINCT FROM 'CONTENT_TRANSLATION'
    OR NOT EXISTS(SELECT 1 FROM public.admin_identities WHERE id=audit.actor_id AND status='ACTIVE') THEN
    RAISE EXCEPTION 'base review receipt requires exact active actor audit' USING ERRCODE='23514';
  END IF;
  IF event->>'status'='IN_REVIEW' THEN
    IF audit.actor_id IS DISTINCT FROM (translation->>'editor_id')::uuid OR (event->>'submitted_at')::timestamptz IS DISTINCT FROM NEW.created_at THEN
      RAISE EXCEPTION 'only original translation editor may submit its draft' USING ERRCODE='23514';
    END IF;
  ELSIF audit.actor_id IS DISTINCT FROM (event->>'reviewer_id')::uuid OR audit.actor_id=(translation->>'editor_id')::uuid OR audit.actor_id=(parent->>'created_by')::uuid
    OR (event->>'reviewed_at')::timestamptz IS DISTINCT FROM NEW.created_at OR event->>'reviewed_source_hash'<>english_hash OR event->>'reviewed_content_hash'<>translation->>'source_hash' THEN
    RAISE EXCEPTION 'base approval must be independent of structure and translation authors' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_cart_mutation_prior()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE c public.carts%ROWTYPE; i public.cart_items%ROWTYPE; s public.support_intents%ROWTYPE;
BEGIN
  SELECT * INTO c FROM public.carts WHERE id=NEW.cart_id FOR UPDATE;
  SELECT * INTO i FROM public.cart_items WHERE id=NEW.cart_item_id FOR UPDATE;
  SELECT * INTO s FROM public.support_intents WHERE id=NEW.support_intent_id FOR UPDATE;
  IF c.id IS NULL OR i.id IS NULL OR s.id IS NULL OR i.cart_id<>c.id OR s.cart_item_id<>i.id
    OR c.status<>'ACTIVE' OR s.status<>'ACTIVE' OR s.privacy_state<>'ACTIVE'
    OR c.expires_at<=clock_timestamp() OR s.expires_at<=clock_timestamp()
    OR c.version<>NEW.expected_cart_version OR i.version<>NEW.expected_item_version OR s.version<>NEW.expected_intent_version
    OR c.market<>NEW.market OR c.currency<>NEW.currency
    OR NEW.occurred_at<GREATEST(c.updated_at,i.updated_at,s.updated_at) THEN
    RAISE EXCEPTION 'cart mutation must bind the current editable head' USING ERRCODE='23514';
  END IF;
  IF NEW.mutation_kind<>'QUANTITY' AND (NEW.quantity<>i.quantity OR NEW.observed_price_id<>i.observed_price_id) THEN
    RAISE EXCEPTION 'private or removal mutation cannot change the item price or quantity' USING ERRCODE='23514';
  END IF;
  IF NEW.mutation_kind<>'PERSONALIZATION' AND (
    NEW.display_mode<>i.display_mode OR NEW.has_fan_message<>i.has_fan_message OR NEW.fan_message_locale<>s.fan_message_locale
    OR NEW.private_material_hash<>public.cart_private_material_hash(s.fan_message_ciphertext,s.display_mode,s.display_name_ciphertext,s.encrypted_data_key,s.encryption_key_version,s.fan_message_locale)) THEN
    RAISE EXCEPTION 'quantity or removal mutation cannot replace private material' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.prices price JOIN public.price_books book ON book.id=price.price_book_id AND book.revision=price.price_book_revision
    WHERE price.id=NEW.observed_price_id AND price.gift_variant_id=i.gift_variant_id AND book.market=c.market AND book.currency=c.currency) THEN
    RAISE EXCEPTION 'cart mutation price must belong to its variant and scope' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_cart_support_intent_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  item_id uuid := COALESCE(
    (to_jsonb(NEW) ->> 'cart_item_id')::uuid,
    (to_jsonb(OLD) ->> 'cart_item_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  item_mode text;
  item_has_message boolean;
  intent_mode text;
  intent_has_message boolean;
  is_eligible boolean;
  intent_privacy_state text;
BEGIN
  SELECT display_mode, has_fan_message INTO item_mode, item_has_message
    FROM cart_items WHERE id = item_id;
  SELECT display_mode, fan_message_ciphertext IS NOT NULL, privacy_state
    INTO intent_mode, intent_has_message, intent_privacy_state
    FROM support_intents WHERE cart_item_id = item_id;
  SELECT EXISTS (
    SELECT 1
    FROM cart_items ci
    JOIN support_intents si ON si.cart_item_id = ci.id
    WHERE ci.id = item_id
      AND (EXISTS (
        SELECT 1 FROM gift_variant_idol_eligibility eligibility
        WHERE eligibility.gift_variant_id = ci.gift_variant_id
          AND eligibility.idol_id = si.idol_id
      ) OR EXISTS (
        SELECT 1 FROM gift_variant_recipient_rules eligibility
        WHERE eligibility.gift_variant_id = ci.gift_variant_id
          AND eligibility.rule = 'ALL_ACTIVE_ARTISTS'
      ))
  ) INTO is_eligible;

  IF item_mode IS NULL OR intent_mode IS NULL
     OR item_mode <> intent_mode
     OR (intent_privacy_state <> 'PURGED' AND item_has_message <> intent_has_message)
     OR NOT is_eligible THEN
    RAISE EXCEPTION 'cart item and support intent privacy projection diverge'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_checkout_quote_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  session_id uuid := COALESCE(
    (to_jsonb(NEW) ->> 'checkout_session_id')::uuid,
    (to_jsonb(OLD) ->> 'checkout_session_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  session_row checkout_sessions%ROWTYPE;
  line_count bigint;
  invalid_count bigint;
  line_subtotal numeric;
  line_tax numeric;
  line_discount numeric;
  line_total numeric;
BEGIN
  SELECT * INTO session_row FROM checkout_sessions WHERE id = session_id;
  IF session_row.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE
           q.checkout_quote_id <> session_row.quote_id
           OR ci.cart_id <> session_row.cart_id
           OR ci.gift_variant_id <> q.gift_variant_id
           OR ci.quantity <> q.quantity
           OR p.market <> session_row.market
           OR p.currency <> session_row.currency
           OR p.amount_minor <> q.unit_amount_minor
         ),
         COALESCE(sum(q.line_subtotal_minor), 0),
         COALESCE(sum(q.tax_amount_minor), 0),
         COALESCE(sum(q.discount_amount_minor), 0),
         COALESCE(sum(q.line_total_minor), 0)
    INTO line_count, invalid_count, line_subtotal, line_tax, line_discount, line_total
    FROM checkout_quote_lines q
    JOIN cart_items ci ON ci.id = q.cart_item_id
    JOIN prices p ON p.id = q.price_id
    WHERE q.checkout_session_id = session_id;

  IF line_count = 0 OR invalid_count <> 0
     OR line_subtotal <> session_row.subtotal_minor
     OR line_tax <> session_row.tax_amount_minor
     OR line_discount <> session_row.discount_amount_minor
     OR line_total + session_row.shipping_amount_minor + session_row.fee_amount_minor
        <> session_row.total_amount_minor THEN
    RAISE EXCEPTION 'checkout quote lines do not match the immutable session snapshot'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_checkout_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE observation public.checkout_preflight_observations%ROWTYPE; c public.carts%ROWTYPE; o public.orders%ROWTYPE; line jsonb; item public.order_items%ROWTYPE; inventory_count bigint; policy jsonb;
BEGIN
  SELECT * INTO observation FROM public.checkout_preflight_observations WHERE id=NEW.preflight_id;
  SELECT * INTO c FROM public.carts WHERE id=NEW.cart_id FOR UPDATE;
  SELECT * INTO o FROM public.orders WHERE id=NEW.order_id;
  IF (c.status='LOCKED' AND c.locked_order_id=o.id AND c.version=NEW.cart_version
    AND NEW.cart_version=observation.cart_version+1 AND c.expires_at>NEW.occurred_at
    AND observation.expires_at>NEW.occurred_at AND observation.cart_id=c.id
    AND o.cart_id=c.id AND o.checkout_session_id=NEW.checkout_session_id AND o.public_order_id=NEW.public_order_id
    AND o.order_status='PENDING_PAYMENT' AND o.payment_status='UNPAID' AND o.version=2 AND o.current_payment_attempt_id IS NULL
    AND o.tax_amount_minor=0 AND o.shipping_amount_minor=0 AND o.fee_amount_minor=0 AND o.discount_amount_minor=0
    AND o.presentation_locale=observation.observation#>>'{consent,presentationLocale}'
    AND o.created_at=NEW.occurred_at AND c.updated_at=NEW.occurred_at
    AND o.checkout_quote_id=(observation.observation#>>'{quote,id}')::uuid
    AND (SELECT count(*) FROM public.order_items WHERE order_id=o.id)=jsonb_array_length(observation.observation#>'{consent,lines}')
    AND (SELECT count(*) FROM public.cart_items i JOIN public.support_intents s ON s.cart_item_id=i.id WHERE i.cart_id=c.id AND s.status<>'CANCELED')=jsonb_array_length(observation.observation#>'{consent,lines}')
    AND (SELECT count(*) FROM public.policy_acceptances WHERE order_id=o.id)=jsonb_array_length(observation.observation#>'{consent,policies}')
    AND EXISTS(SELECT 1 FROM public.checkout_outbox_events e WHERE e.preflight_id=NEW.preflight_id AND e.event_id=NEW.event_id AND e.order_id=o.id AND e.checkout_session_id=NEW.checkout_session_id AND e.request_id=NEW.request_id AND e.correlation_id=NEW.correlation_id AND e.occurred_at=NEW.occurred_at)
  ) IS NOT TRUE THEN RAISE EXCEPTION 'checkout receipt must bind the complete locked order' USING ERRCODE='23514'; END IF;
  FOR line IN SELECT value FROM jsonb_array_elements(observation.observation#>'{consent,lines}') LOOP
    SELECT * INTO item FROM public.order_items WHERE order_id=o.id AND cart_item_id=(line->>'cartItemId')::uuid;
    IF item.checkout_preflight_id IS DISTINCT FROM NEW.preflight_id OR NOT EXISTS(
      SELECT 1 FROM public.cart_items i JOIN public.support_intents s ON s.cart_item_id=i.id
      JOIN public.fulfillments f ON f.order_item_id=item.id AND f.order_id=o.id
      WHERE i.id=item.cart_item_id AND i.cart_id=c.id AND i.version=(line->>'itemVersion')::bigint
        AND s.id=item.support_intent_id AND s.version=(line->>'intentVersion')::bigint+1 AND s.status='CHECKOUT_LOCKED' AND s.privacy_state='ACTIVE'
        AND s.expires_at>NEW.occurred_at AND s.updated_at=NEW.occurred_at
        AND f.fulfillment_profile_id=(line->>'fulfillmentProfileId')::uuid AND f.status='PENDING'
    ) THEN RAISE EXCEPTION 'checkout must lock each exact cart item and intent' USING ERRCODE='23514'; END IF;
    SELECT count(*) INTO inventory_count FROM public.inventory_reservations r WHERE r.checkout_session_id=NEW.checkout_session_id AND r.cart_item_id=item.cart_item_id;
    IF line->>'inventoryPolicy'='TRACKED' THEN
      IF inventory_count<>1 OR NOT EXISTS(SELECT 1 FROM public.inventory_reservations r WHERE r.checkout_session_id=NEW.checkout_session_id AND r.checkout_quote_id=o.checkout_quote_id AND r.cart_item_id=item.cart_item_id AND r.gift_variant_id=item.gift_variant_id AND r.inventory_item_id=(line->>'inventoryItemId')::uuid AND r.locked_order_id=o.id AND r.quantity=item.quantity AND r.status='ACTIVE' AND r.expires_at=observation.expires_at) THEN
        RAISE EXCEPTION 'checkout requires each exact tracked reservation' USING ERRCODE='23514'; END IF;
    ELSIF inventory_count<>0 THEN RAISE EXCEPTION 'nontracked checkout cannot invent inventory reservations' USING ERRCODE='23514'; END IF;
  END LOOP;
  FOR policy IN SELECT value FROM jsonb_array_elements(observation.observation#>'{consent,policies}') LOOP
    IF NOT EXISTS(SELECT 1 FROM public.policy_acceptances a WHERE a.order_id=o.id AND a.policy_key=policy->>'policyKey' AND a.policy_revision_id=(policy->>'policyRevisionId')::uuid AND a.policy_translation_revision_id=(policy->>'policyTranslationRevisionId')::uuid AND a.locale::text=policy->>'locale' AND a.accepted_at=NEW.occurred_at AND a.recorded_at=NEW.occurred_at) THEN
      RAISE EXCEPTION 'checkout requires every exact observed policy acceptance' USING ERRCODE='23514'; END IF;
  END LOOP;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_content_authoring_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE parent_column text; parent_table regclass; translation_table regclass; review_table regclass; translation_column text; proof_table regclass; owner_column text; revision_row jsonb; source_row jsonb; latest bigint; row_data record; target_id uuid; audit public.audit_logs%ROWTYPE; english_hash public.sha256_hex;
BEGIN
  IF NEW.idol_revision_id IS NOT NULL THEN parent_column:='idol_revision_id'; parent_table:='public.idol_revisions'::regclass; translation_table:='public.idol_revision_translations'::regclass; review_table:='public.idol_translation_reviews'::regclass; translation_column:='idol_translation_id'; proof_table:='public.idol_translation_copy_evidence'::regclass; owner_column:='idol_id'; target_id:=NEW.idol_revision_id;
  ELSIF NEW.gift_revision_id IS NOT NULL THEN parent_column:='gift_revision_id'; parent_table:='public.gift_revisions'::regclass; translation_table:='public.gift_revision_translations'::regclass; review_table:='public.gift_translation_reviews'::regclass; translation_column:='gift_translation_id'; proof_table:='public.gift_translation_copy_evidence'::regclass; owner_column:='gift_id'; target_id:=NEW.gift_revision_id;
  ELSIF NEW.homepage_revision_id IS NOT NULL THEN parent_column:='homepage_revision_id'; parent_table:='public.homepage_revisions'::regclass; translation_table:='public.homepage_revision_translations'::regclass; review_table:='public.homepage_translation_reviews'::regclass; translation_column:='homepage_translation_id'; proof_table:='public.homepage_translation_copy_evidence'::regclass; owner_column:=''; target_id:=NEW.homepage_revision_id;
  ELSIF NEW.policy_revision_id IS NOT NULL THEN parent_column:='policy_revision_id'; parent_table:='public.policy_revisions'::regclass; translation_table:='public.policy_revision_translations'::regclass; review_table:='public.policy_translation_reviews'::regclass; translation_column:='policy_translation_id'; proof_table:='public.policy_translation_copy_evidence'::regclass; owner_column:='policy_key'; target_id:=NEW.policy_revision_id;
  ELSIF NEW.media_metadata_revision_id IS NOT NULL THEN parent_column:='media_metadata_revision_id'; parent_table:='public.media_metadata_revisions'::regclass; translation_table:='public.media_metadata_revision_translations'::regclass; review_table:='public.media_metadata_translation_reviews'::regclass; translation_column:='media_metadata_translation_id'; proof_table:='public.media_metadata_translation_copy_evidence'::regclass; owner_column:='media_asset_id'; target_id:=NEW.media_metadata_revision_id;
  END IF;
  EXECUTE format('SELECT to_jsonb(r.*) FROM %s r WHERE id=$1',parent_table) INTO revision_row USING target_id;
  IF revision_row IS NULL OR revision_row->>'lifecycle'<>'DRAFT' OR (revision_row->>'created_by')::uuid<>NEW.actor_id OR (revision_row->>'created_at')::timestamptz<>NEW.created_at OR (revision_row->>'revision')::bigint<>NEW.expected_version+1 THEN
    RAISE EXCEPTION 'authoring receipt must bind the newly created draft revision' USING ERRCODE='23514';
  END IF;
  IF owner_column='' THEN EXECUTE format('SELECT max(revision) FROM %s',parent_table) INTO latest;
  ELSE EXECUTE format('SELECT max(revision) FROM %s WHERE %I::text=$1',parent_table,owner_column) INTO latest USING revision_row->>owner_column; END IF;
  IF latest<>NEW.expected_version+1 THEN RAISE EXCEPTION 'authoring receipt must advance current owner revision' USING ERRCODE='23514'; END IF;
  IF NEW.action='COPY' THEN
    EXECUTE format('SELECT to_jsonb(r.*) FROM %s r WHERE id=$1',parent_table) INTO source_row USING (to_jsonb(NEW)->>('source_'||parent_column))::uuid;
    IF source_row IS NULL OR (source_row->>'revision')::bigint >= (revision_row->>'revision')::bigint OR (owner_column<>'' AND source_row->>owner_column IS DISTINCT FROM revision_row->>owner_column) THEN RAISE EXCEPTION 'copy receipt source must belong to the same owner' USING ERRCODE='23514'; END IF;
  END IF;
  IF cardinality(NEW.changed_paths) <> (SELECT count(DISTINCT path) FROM unnest(NEW.changed_paths) AS path) THEN RAISE EXCEPTION 'changed field paths must be distinct' USING ERRCODE='23514'; END IF;
  SELECT * INTO audit FROM public.audit_logs WHERE id=NEW.audit_log_id;
  IF audit.id IS NULL OR audit.actor_type<>'ADMIN' OR audit.actor_id IS DISTINCT FROM NEW.actor_id OR audit.action<>('CONTENT_REVISION_'||NEW.action) OR audit.subject_type<>'CONTENT_REVISION' OR audit.subject_id<>target_id OR audit.created_at<>NEW.created_at OR audit.outcome<>'SUCCEEDED' OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.admin_identities WHERE id=NEW.actor_id AND status='ACTIVE') THEN
    RAISE EXCEPTION 'authoring requires exact successful active-admin audit evidence' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT source_hash FROM %s WHERE %I=$1 AND locale=''en''',translation_table,parent_column) INTO english_hash USING target_id;
  IF english_hash IS NULL THEN RAISE EXCEPTION 'authored revision requires actual English source' USING ERRCODE='23514'; END IF;
  FOR row_data IN EXECUTE format('SELECT t.id,t.editor_id,t.edited_at, e.target_translation_id AS copied, r.status,r.sequence FROM %s t LEFT JOIN %s e ON e.target_translation_id=t.id LEFT JOIN LATERAL(SELECT status,sequence FROM %s WHERE %I=t.id ORDER BY sequence DESC LIMIT 1) r ON true WHERE t.%I=$1',translation_table,proof_table,review_table,translation_column,parent_column) USING target_id LOOP
    IF row_data.copied IS NULL AND (row_data.editor_id<>NEW.actor_id OR row_data.edited_at<>NEW.created_at OR row_data.status IS DISTINCT FROM 'DRAFT' OR row_data.sequence IS DISTINCT FROM 1::bigint) THEN RAISE EXCEPTION 'new translation must bind current author and initial draft review' USING ERRCODE='23514'; END IF;
  END LOOP;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_content_extension_review_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE expected_actor uuid; creation_audit uuid; action_prefix text; subject_kind text; audit public.audit_logs%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME = 'idol_revision_alias_reviews' THEN
    SELECT editor_id,audit_log_id INTO expected_actor,creation_audit FROM public.idol_revision_alias_sets WHERE id = NEW.alias_set_id;
    action_prefix := 'IDOL_ALIAS'; subject_kind := 'IDOL_ALIAS_REVIEW';
  ELSE
    SELECT t.editor_id,d.audit_log_id INTO expected_actor,creation_audit FROM public.gift_detail_translations t JOIN public.gift_detail_documents d ON d.id = t.document_id WHERE t.id = NEW.gift_detail_translation_id;
    action_prefix := 'GIFT_DETAIL'; subject_kind := 'GIFT_DETAIL_TRANSLATION_REVIEW';
  END IF;
  IF NEW.status = 'DRAFT' THEN
    IF NEW.audit_log_id <> creation_audit THEN RAISE EXCEPTION 'draft review must bind creation audit' USING ERRCODE = '23514'; END IF;
  ELSE
    IF NEW.status = 'APPROVED' THEN expected_actor := NEW.reviewer_id; END IF;
    SELECT * INTO audit FROM public.audit_logs WHERE id = NEW.audit_log_id;
    IF audit.id IS NULL OR audit.actor_type <> 'ADMIN' OR audit.actor_id IS DISTINCT FROM expected_actor OR audit.subject_type <> subject_kind OR audit.subject_id <> NEW.id
      OR audit.action <> (action_prefix || CASE NEW.status WHEN 'APPROVED' THEN '_APPROVE' ELSE '_SUBMIT' END)
      OR audit.outcome <> 'SUCCEEDED' OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS NULL
      OR NOT EXISTS (SELECT 1 FROM public.admin_identities WHERE id = expected_actor AND status = 'ACTIVE') THEN
      RAISE EXCEPTION 'extension review requires exact audit and active actor evidence' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_content_preview_grant_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE audit public.audit_logs%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO audit FROM public.audit_logs WHERE id = NEW.audit_log_id;
    IF audit.id IS NULL OR audit.action <> 'CONTENT_PREVIEW_ISSUE' OR audit.created_at <> NEW.created_at THEN
      RAISE EXCEPTION 'preview issuance requires exact audit' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at THEN RETURN NULL; END IF;
    SELECT * INTO audit FROM public.audit_logs WHERE id = NEW.revoked_audit_log_id;
    IF audit.id IS NULL OR audit.action <> 'CONTENT_PREVIEW_REVOKE' OR audit.created_at <> NEW.revoked_at THEN
      RAISE EXCEPTION 'preview revocation requires exact audit' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF audit.id IS NULL OR audit.actor_type <> 'ADMIN' OR audit.actor_id IS DISTINCT FROM NEW.actor_id
    OR audit.subject_type <> 'CONTENT_PREVIEW_GRANT' OR audit.subject_id <> NEW.id OR audit.outcome <> 'SUCCEEDED'
    OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS NULL THEN
    RAISE EXCEPTION 'preview grant requires exact actor and subject audit' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_content_publication_manifest()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE value jsonb:=NEW.manifest; target_id uuid; expected_kind text; media_revision jsonb;
BEGIN
  target_id:=coalesce(NEW.idol_revision_id,NEW.gift_revision_id,NEW.homepage_revision_id,NEW.policy_revision_id,NEW.media_metadata_revision_id);
  expected_kind:=CASE WHEN NEW.idol_revision_id IS NOT NULL THEN 'IDOL' WHEN NEW.gift_revision_id IS NOT NULL THEN 'GIFT' WHEN NEW.homepage_revision_id IS NOT NULL THEN 'HOMEPAGE' WHEN NEW.policy_revision_id IS NOT NULL THEN 'POLICY' ELSE 'MEDIA_METADATA' END;
  IF jsonb_typeof(value) IS DISTINCT FROM 'object' OR jsonb_typeof(value->'revision') IS DISTINCT FROM 'object' OR jsonb_typeof(value->'target') IS DISTINCT FROM 'object'
    OR jsonb_typeof(value->'mediaRevisions') IS DISTINCT FROM 'array' OR jsonb_typeof(value->'approvals') IS DISTINCT FROM 'array'
    OR jsonb_typeof(value->'copies') IS DISTINCT FROM 'array' OR jsonb_typeof(value->'extensionApprovals') IS DISTINCT FROM 'array'
    OR jsonb_typeof(value->'media') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'manifest proof sections must have their exact shape' USING ERRCODE='23514'; END IF;
  IF value->>'schemaVersion' IS DISTINCT FROM '1' OR (value#>>'{target,revisionId}')::uuid IS DISTINCT FROM target_id OR value#>>'{target,owner,kind}' IS DISTINCT FROM expected_kind
    OR value->'target' IS DISTINCT FROM jsonb_build_object('owner',value#>'{revision,target}','revisionId',value#>'{revision,revisionId}')
    OR NEW.manifest_text<>public.canonical_publication_json(value)
    OR NEW.manifest_hash<>encode(sha256(convert_to('fan-support.publication-manifest.v1'||chr(10)||NEW.manifest_text,'UTF8')),'hex')
    OR NEW.translation_manifest_hash<>encode(sha256(convert_to('fan-support.publication-manifest.v1/translations'||chr(10)||public.canonical_publication_json(jsonb_build_object('revision',value->'revision')),'UTF8')),'hex')
    OR NEW.approval_manifest_hash<>encode(sha256(convert_to('fan-support.publication-manifest.v1/approvals'||chr(10)||public.canonical_publication_json(jsonb_build_object('approvals',value->'approvals','copies',value->'copies','extensionApprovals',value->'extensionApprovals')),'UTF8')),'hex')
    OR (expected_kind='POLICY' AND NEW.media_manifest_hash IS NOT NULL)
    OR (expected_kind<>'POLICY' AND NEW.media_manifest_hash IS DISTINCT FROM encode(sha256(convert_to('fan-support.publication-manifest.v1/media'||chr(10)||public.canonical_publication_json(jsonb_build_object('mediaRevisions',value->'mediaRevisions','media',value->'media')),'UTF8')),'hex')) THEN
    RAISE EXCEPTION 'manifest requires exact canonical target bytes and section hashes' USING ERRCODE='23514';
  END IF;
  PERFORM public.assert_publication_manifest_revision(value->'revision');
  FOR media_revision IN SELECT * FROM jsonb_array_elements(value->'mediaRevisions') LOOP
    IF media_revision#>>'{target,kind}' IS DISTINCT FROM 'MEDIA_METADATA' THEN RAISE EXCEPTION 'manifest media dependency must be typed' USING ERRCODE='23514'; END IF;
    PERFORM public.assert_publication_manifest_revision(media_revision);
  END LOOP;
  PERFORM public.assert_publication_manifest_approvals(value);
  PERFORM public.assert_publication_manifest_media(value);
  IF NOT EXISTS(SELECT 1 FROM public.content_publication_receipts WHERE manifest_id=NEW.id AND created_at=NEW.created_at) THEN
    RAISE EXCEPTION 'manifest requires an exact administrative operation receipt' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_content_publication_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE proof public.content_publication_manifests%ROWTYPE; publication public.content_publications%ROWTYPE; job public.content_purge_jobs%ROWTYPE; prior_job public.content_purge_jobs%ROWTYPE;
  kind text; parent jsonb; expected_action text; expected_subject text; subject uuid; causal_bound timestamptz; revision jsonb; audit jsonb; chain_count bigint;
BEGIN
  IF NEW.action='RETRY_PURGE' THEN
    SELECT * INTO job FROM public.content_purge_jobs WHERE id=NEW.purge_job_id FOR UPDATE;
    SELECT * INTO prior_job FROM public.content_purge_jobs WHERE id=job.retry_of FOR UPDATE;
    IF job.id IS NULL OR prior_job.id IS NULL OR prior_job.status<>'FAILED' OR prior_job.version<>NEW.expected_version OR job.publication_id<>NEW.publication_id
      OR job.generation<>NEW.result_generation OR job.created_at<>NEW.created_at THEN RAISE EXCEPTION 'purge retry requires its exact failed predecessor and generation' USING ERRCODE='23514'; END IF;
    expected_action:='CONTENT_PURGE_RETRY'; expected_subject:='CONTENT_PURGE_JOB'; subject:=job.id; causal_bound:=prior_job.updated_at;
  ELSE
    SELECT * INTO proof FROM public.content_publication_manifests WHERE id=NEW.manifest_id;
    IF proof.id IS NULL OR proof.created_at<>NEW.created_at OR proof.publication_id IS DISTINCT FROM NEW.publication_id THEN RAISE EXCEPTION 'publication receipt requires its exact typed manifest' USING ERRCODE='23514'; END IF;
    kind:=proof.manifest#>>'{target,owner,kind}';
    EXECUTE format('SELECT to_jsonb(r.*) FROM public.%I r WHERE id=$1',lower(kind)||'_revisions') INTO parent USING coalesce(proof.idol_revision_id,proof.gift_revision_id,proof.homepage_revision_id,proof.policy_revision_id,proof.media_metadata_revision_id);
    causal_bound:=(proof.manifest#>>'{revision,createdAt}')::timestamptz;
    FOR revision IN SELECT proof.manifest->'revision' UNION ALL SELECT * FROM jsonb_array_elements(proof.manifest->'mediaRevisions') LOOP
      causal_bound:=GREATEST(causal_bound,(revision->>'createdAt')::timestamptz);
      FOR audit IN SELECT * FROM jsonb_array_elements(revision->'translationAudits') LOOP
        causal_bound:=GREATEST(causal_bound,(audit->>'editedAt')::timestamptz,(audit#>>'{review,reviewedAt}')::timestamptz);
      END LOOP;
    END LOOP;
    FOR audit IN SELECT * FROM jsonb_array_elements(proof.manifest->'extensionApprovals') LOOP causal_bound:=GREATEST(causal_bound,(audit->>'editedAt')::timestamptz,(audit->>'reviewedAt')::timestamptz); END LOOP;
    IF NEW.created_at<causal_bound THEN RAISE EXCEPTION 'publication event cannot precede its immutable evidence' USING ERRCODE='23514'; END IF;
    IF NEW.action='VALIDATE' THEN
      IF kind='HOMEPAGE' THEN SELECT coalesce(max(version),0) INTO chain_count FROM public.homepage_publication_heads;
      ELSIF kind='POLICY' THEN SELECT coalesce(max(version),0) INTO chain_count FROM public.policy_publication_heads WHERE policy_key=parent->>'policy_key';
      ELSE EXECUTE format('SELECT coalesce(max(version),0) FROM public.%I WHERE %I=$1',lower(kind)||'_publication_heads',CASE kind WHEN 'MEDIA_METADATA' THEN 'media_asset_id' ELSE lower(kind)||'_id' END) INTO chain_count USING (parent->>CASE kind WHEN 'MEDIA_METADATA' THEN 'media_asset_id' ELSE lower(kind)||'_id' END)::uuid;
      END IF;
      IF chain_count<>NEW.expected_version THEN RAISE EXCEPTION 'validation receipt must bind the actual publication head version' USING ERRCODE='23514'; END IF;
      IF NOT EXISTS(SELECT 1 FROM public.content_authoring_receipts a WHERE coalesce(a.idol_revision_id,a.gift_revision_id,a.homepage_revision_id,a.policy_revision_id,a.media_metadata_revision_id)=(parent->>'id')::uuid) THEN RAISE EXCEPTION 'legacy drafts require authoring copy before runtime validation' USING ERRCODE='23514'; END IF;
      IF parent->>'lifecycle'<>'VALIDATED' OR (parent->>'validated_at')::timestamptz IS DISTINCT FROM NEW.created_at OR NEW.result_head_version<>NEW.expected_version THEN
        RAISE EXCEPTION 'validation receipt requires its exact validated transition' USING ERRCODE='23514';
      END IF;
      expected_action:='CONTENT_VALIDATE'; expected_subject:='CONTENT_VALIDATION'; subject:=NEW.id;
    ELSE
      SELECT * INTO publication FROM public.content_publications WHERE id=NEW.publication_id;
      IF publication.id IS NULL OR publication.action<>NEW.action OR publication.published_at<>NEW.created_at OR publication.published_by<>NEW.actor_id
        OR publication.audit_log_id<>NEW.audit_log_id OR NEW.result_head_version<>NEW.expected_version+1 THEN
        RAISE EXCEPTION 'publication receipt requires its exact event and head version' USING ERRCODE='23514';
      END IF;
      WITH RECURSIVE chain AS (SELECT id,replaces_publication_id FROM public.content_publications WHERE id=NEW.publication_id UNION ALL SELECT p.id,p.replaces_publication_id FROM public.content_publications p JOIN chain c ON p.id=c.replaces_publication_id)
        SELECT count(*) INTO chain_count FROM chain;
      IF chain_count<>NEW.result_head_version THEN RAISE EXCEPTION 'publication receipt head version must match actual chain length' USING ERRCODE='23514'; END IF;
      -- The typed head transition and the immutable predecessor chain independently bind optimistic concurrency.
      IF NEW.action='PUBLISH' AND (parent->>'lifecycle'<>'PUBLISHED' OR (parent->>'published_at')::timestamptz IS DISTINCT FROM NEW.created_at)
        OR NEW.action='ROLLBACK' AND parent->>'lifecycle'<>'SUPERSEDED' THEN RAISE EXCEPTION 'publication lifecycle must match its immutable action' USING ERRCODE='23514'; END IF;
      causal_bound:=GREATEST(causal_bound,(SELECT published_at+interval '1 microsecond' FROM public.content_publications WHERE id=publication.replaces_publication_id));
      causal_bound:=GREATEST(causal_bound,(parent->>'validated_at')::timestamptz);
      expected_action:=CASE NEW.action WHEN 'PUBLISH' THEN 'CONTENT_PUBLISH' ELSE 'CONTENT_ROLLBACK' END; expected_subject:='CONTENT_PUBLICATION'; subject:=NEW.publication_id;
    END IF;
  END IF;
  PERFORM public.assert_publication_admin_audit(NEW.audit_log_id,NEW.actor_id,NEW.session_id,expected_action,expected_subject,subject,NEW.created_at,causal_bound);
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_content_purge_attempt_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE job public.content_purge_jobs%ROWTYPE;
BEGIN
  SELECT * INTO job FROM public.content_purge_jobs WHERE id=NEW.job_id;
  IF job.id IS NULL OR NEW.job_version<>job.version OR NEW.created_at<>job.updated_at
    OR (NEW.kind='CLAIM' AND NEW.lease_token IS DISTINCT FROM job.lease_token)
    OR (NEW.kind<>'CLAIM' AND job.lease_token IS NOT NULL) THEN
    RAISE EXCEPTION 'purge attempt requires its committed job transition' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_content_purge_transition_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE attempt public.content_purge_attempts%ROWTYPE; expected_kind text; expected_token uuid;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.generation>1 AND NOT EXISTS(SELECT 1 FROM public.content_publication_receipts r
      JOIN public.content_purge_jobs parent ON parent.id=NEW.retry_of
      WHERE r.action='RETRY_PURGE' AND r.purge_job_id=NEW.id AND r.publication_id=NEW.publication_id
        AND r.expected_version=parent.version AND r.result_generation=NEW.generation AND r.result_version=1 AND r.created_at=NEW.created_at) THEN
      RAISE EXCEPTION 'purge retry requires exact authorized publication receipt' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
  END IF;
  SELECT * INTO attempt FROM public.content_purge_attempts WHERE job_id=NEW.id AND job_version=NEW.version;
  expected_kind:=CASE WHEN NEW.lease_token IS NOT NULL THEN 'CLAIM'
    WHEN NEW.error_code='PURGE_TIMEOUT' THEN 'TIMEOUT' WHEN NEW.error_code IS NOT NULL THEN 'FAILURE'
    WHEN NEW.status='COMPLETED' THEN 'COMPLETED' WHEN OLD.status='PENDING' THEN 'SUBMITTED' ELSE 'PENDING' END;
  expected_token:=CASE WHEN NEW.lease_token IS NOT NULL THEN NEW.lease_token ELSE OLD.lease_token END;
  IF attempt.id IS NULL OR attempt.kind<>expected_kind OR attempt.created_at<>NEW.updated_at
    OR (expected_token IS NOT NULL AND attempt.lease_token<>expected_token)
    OR attempt.error_code IS DISTINCT FROM (CASE WHEN expected_kind='CLAIM' THEN NULL ELSE NEW.error_code END) THEN
    RAISE EXCEPTION 'purge transition requires its exact immutable lease receipt' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_content_translation_copy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE source_row jsonb; target_row jsonb; source_revision jsonb; target_revision jsonb; source_chain jsonb; target_chain jsonb; receipt public.content_authoring_receipts%ROWTYPE; labels_equal boolean; english_hash public.sha256_hex;
BEGIN
  EXECUTE format('SELECT to_jsonb(t.*) FROM %s t WHERE id=$1',TG_ARGV[0]::regclass) INTO source_row USING NEW.source_translation_id;
  EXECUTE format('SELECT to_jsonb(t.*) FROM %s t WHERE id=$1',TG_ARGV[0]::regclass) INTO target_row USING NEW.target_translation_id;
  IF source_row IS NULL OR target_row IS NULL OR (source_row - 'id' - TG_ARGV[1]) IS DISTINCT FROM (target_row - 'id' - TG_ARGV[1]) THEN
    RAISE EXCEPTION 'copied translation must retain exact text and original audit fields' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT to_jsonb(r.*) FROM %s r WHERE id=$1',TG_ARGV[2]::regclass) INTO source_revision USING (source_row ->> TG_ARGV[1])::uuid;
  EXECUTE format('SELECT to_jsonb(r.*) FROM %s r WHERE id=$1',TG_ARGV[2]::regclass) INTO target_revision USING (target_row ->> TG_ARGV[1])::uuid;
  IF (source_revision ->> 'revision')::bigint >= (target_revision ->> 'revision')::bigint OR (TG_ARGV[5] <> '' AND source_revision ->> TG_ARGV[5] IS DISTINCT FROM target_revision ->> TG_ARGV[5]) THEN
    RAISE EXCEPTION 'copy source must precede target revision with same owner' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT * FROM public.content_authoring_receipts WHERE %I=$1',TG_ARGV[1]) INTO receipt USING (target_row ->> TG_ARGV[1])::uuid;
  IF receipt.id IS NULL OR receipt.action <> 'COPY' OR receipt.audit_log_id <> NEW.audit_log_id OR receipt.created_at <> NEW.copied_at OR (to_jsonb(receipt) ->> ('source_'||TG_ARGV[1]))::uuid IS DISTINCT FROM (source_row ->> TG_ARGV[1])::uuid THEN
    RAISE EXCEPTION 'copy evidence requires its exact authoring receipt' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT source_hash FROM %s WHERE %I=$1 AND locale=''en''',TG_ARGV[0]::regclass,TG_ARGV[1]) INTO english_hash USING (target_row ->> TG_ARGV[1])::uuid;
  IF english_hash IS NULL OR target_row ->> 'translated_from_source_hash' <> english_hash THEN
    RAISE EXCEPTION 'copied approval must bind actual target English source' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT jsonb_agg(to_jsonb(r.*)-''id''-%L ORDER BY sequence) FROM %s r WHERE %I=$1',TG_ARGV[4],TG_ARGV[3]::regclass,TG_ARGV[4]) INTO source_chain USING NEW.source_translation_id;
  EXECUTE format('SELECT jsonb_agg(to_jsonb(r.*)-''id''-%L ORDER BY sequence) FROM %s r WHERE %I=$1',TG_ARGV[4],TG_ARGV[3]::regclass,TG_ARGV[4]) INTO target_chain USING NEW.target_translation_id;
  IF source_chain IS DISTINCT FROM target_chain OR jsonb_array_length(source_chain) <> 3 OR source_chain -> 2 ->> 'status' <> 'APPROVED' THEN
    RAISE EXCEPTION 'copied approval requires exact original three-event review chain' USING ERRCODE='23514';
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s WHERE id=$1 AND %I=$2 AND sequence=3 AND status=''APPROVED'')',TG_ARGV[3]::regclass,TG_ARGV[4]) INTO labels_equal USING NEW.source_approval_review_id,NEW.source_translation_id;
  IF NOT labels_equal THEN RAISE EXCEPTION 'copy approval reference must bind source translation' USING ERRCODE='23514'; END IF;
  IF TG_ARGV[1]='gift_revision_id' THEN
    SELECT NOT EXISTS((SELECT gift_variant_id,label FROM public.gift_variant_labels WHERE gift_translation_id=NEW.source_translation_id EXCEPT SELECT gift_variant_id,label FROM public.gift_variant_labels WHERE gift_translation_id=NEW.target_translation_id) UNION ALL (SELECT gift_variant_id,label FROM public.gift_variant_labels WHERE gift_translation_id=NEW.target_translation_id EXCEPT SELECT gift_variant_id,label FROM public.gift_variant_labels WHERE gift_translation_id=NEW.source_translation_id)) INTO labels_equal;
  ELSIF TG_ARGV[1]='homepage_revision_id' THEN
    SELECT NOT EXISTS((SELECT slot_key,label FROM public.homepage_slot_translations WHERE homepage_translation_id=NEW.source_translation_id EXCEPT SELECT slot_key,label FROM public.homepage_slot_translations WHERE homepage_translation_id=NEW.target_translation_id) UNION ALL (SELECT slot_key,label FROM public.homepage_slot_translations WHERE homepage_translation_id=NEW.target_translation_id EXCEPT SELECT slot_key,label FROM public.homepage_slot_translations WHERE homepage_translation_id=NEW.source_translation_id)) INTO labels_equal;
  END IF;
  IF NOT labels_equal THEN RAISE EXCEPTION 'copied localized child labels must be identical' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_current_content_publication_proof()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE proof public.content_publication_manifests%ROWTYPE;
BEGIN
  -- Explicit ADR-012 dispatch; all following strict behavior is retained.
  IF NEW.proof_version=3 THEN PERFORM public.assert_daily_publication(NEW.id); RETURN NULL; END IF;
  IF NEW.proof_version=1 THEN RETURN NULL; END IF;
  SELECT * INTO proof FROM public.content_publication_manifests WHERE publication_id=NEW.id;
  IF proof.id IS NULL OR proof.idol_revision_id IS DISTINCT FROM NEW.idol_revision_id OR proof.gift_revision_id IS DISTINCT FROM NEW.gift_revision_id
    OR proof.homepage_revision_id IS DISTINCT FROM NEW.homepage_revision_id OR proof.policy_revision_id IS DISTINCT FROM NEW.policy_revision_id
    OR proof.media_metadata_revision_id IS DISTINCT FROM NEW.media_metadata_revision_id OR proof.created_at<>NEW.published_at
    OR proof.translation_manifest_hash<>NEW.translation_manifest_hash OR proof.approval_manifest_hash<>NEW.approval_manifest_hash
    OR proof.media_manifest_hash IS DISTINCT FROM NEW.media_manifest_hash
    OR NOT EXISTS(SELECT 1 FROM public.content_publication_receipts WHERE publication_id=NEW.id AND manifest_id=proof.id AND action=NEW.action AND actor_id=NEW.published_by AND audit_log_id=NEW.audit_log_id AND created_at=NEW.published_at)
    OR (SELECT count(*) FROM public.content_purge_jobs WHERE publication_id=NEW.id AND generation=1)<>7 THEN
    RAISE EXCEPTION 'current publication requires exact manifest receipt and seven purge jobs' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_daily_publication(publication uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE m public.daily_publication_manifests%ROWTYPE; p public.content_publications%ROWTYPE; d public.daily_publication_revisions%ROWTYPE; o public.management_operations%ROWTYPE; item jsonb; metadata public.daily_publication_revisions%ROWTYPE; head jsonb; identity_row jsonb; assets jsonb; variants jsonb; lineage jsonb;
BEGIN
 SELECT * INTO m FROM public.daily_publication_manifests WHERE publication_id=publication;
 SELECT * INTO p FROM public.content_publications WHERE id=publication;
 SELECT * INTO d FROM public.daily_publication_revisions WHERE revision_id=m.revision_id;
 SELECT * INTO o FROM public.management_operations WHERE id=m.operation_id;
 IF m.publication_id IS NULL OR p.id IS NULL OR p.proof_version<>3 OR p.content_type<>d.object_kind OR coalesce(p.idol_revision_id,p.gift_revision_id,p.homepage_revision_id,p.media_metadata_revision_id)<>m.revision_id
 OR m.actor_id<>o.actor_id OR m.actor_id<>p.published_by OR m.session_id<>o.session_id OR m.audit_log_id<>p.audit_log_id OR m.published_at<>p.published_at
 OR m.manifest#>>'{publicationMode}'<>'DIRECT_OPERATOR_V1' OR m.manifest->>'schemaVersion'<>'3' OR m.manifest->'document' IS DISTINCT FROM d.document
 OR (m.manifest->>'actorId')::uuid<>m.actor_id OR (m.manifest->>'operationId')::uuid<>m.operation_id
 OR m.manifest_text<>public.canonical_publication_json(m.manifest)
 OR m.manifest_hash<>encode(sha256(convert_to('fan-support.daily-publication.v1'||chr(10)||m.manifest_text,'UTF8')),'hex')
 OR p.media_manifest_hash IS DISTINCT FROM m.manifest_hash OR p.translation_manifest_hash<>d.document#>>'{source,sourceHash}' OR p.approval_manifest_hash<>encode(sha256(convert_to('DIRECT_OPERATOR_V1:'||m.operation_id::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'daily publication requires exact immutable authorized manifest' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_management_authority(m.operation_id);
 -- Restored history is not rewritten or attributed to the restoring operator.
 IF p.action='PUBLISH' THEN PERFORM public.assert_daily_revision(m.revision_id); END IF;
 EXECUTE format('SELECT to_jsonb(h.*) FROM public.%I h WHERE publication_id=$1',lower(d.object_kind)||'_publication_heads') INTO head USING p.id;
 IF head IS NULL OR (head->>'version')::bigint<>m.head_version THEN
  -- Multiple real role jobs can deduplicate to one master. Earlier metadata events
  -- may therefore be superseded by another exact event in this same operation.
  IF d.object_kind<>'MEDIA_METADATA' OR NOT EXISTS(
   WITH RECURSIVE exact_chain AS (
    SELECT publication.id,publication.replaces_publication_id,proof.head_version
    FROM public.media_metadata_publication_heads h
    JOIN public.content_publications publication ON publication.id=h.publication_id AND publication.media_asset_id=h.media_asset_id
    JOIN public.daily_publication_manifests proof ON proof.publication_id=publication.id AND proof.head_version=h.version
    WHERE h.media_asset_id=d.object_id AND proof.operation_id=m.operation_id
    UNION ALL
    SELECT previous.id,previous.replaces_publication_id,prior.head_version
    FROM exact_chain successor
    JOIN public.content_publications previous ON previous.id=successor.replaces_publication_id AND previous.content_type='MEDIA_METADATA' AND previous.media_asset_id=d.object_id
    JOIN public.daily_publication_manifests prior ON prior.publication_id=previous.id AND prior.operation_id=m.operation_id AND prior.head_version=successor.head_version-1
   ) SELECT 1 FROM exact_chain WHERE id=p.id AND head_version=m.head_version
  ) THEN RAISE EXCEPTION 'daily publication must be the exact new head or same-operation metadata predecessor' USING ERRCODE='23514'; END IF;
 END IF;
 IF d.object_kind IN('IDOL','GIFT') THEN
  EXECUTE format('SELECT to_jsonb(i.*) FROM public.%I i WHERE id=$1',CASE d.object_kind WHEN 'IDOL' THEN 'idols' ELSE 'gifts' END) INTO identity_row USING d.object_id;
  IF (identity_row->>'version')::bigint<>m.result_base_version OR m.expected_base_version<>(o.intent->>'expectedVersion')::bigint OR (identity_row->>'published_revision_id')::uuid<>m.revision_id OR identity_row->>'status'<>'active' THEN RAISE EXCEPTION 'daily identity and publication must switch atomically' USING ERRCODE='23514'; END IF;
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(m.manifest->'media') LOOP
  SELECT * INTO metadata FROM public.daily_publication_revisions WHERE revision_id=(item#>>'{metadata,revisionId}')::uuid AND object_kind='MEDIA_METADATA';
  IF metadata.document IS DISTINCT FROM item->'metadata' OR NOT EXISTS(SELECT 1 FROM public.media_metadata_revisions WHERE id=metadata.revision_id AND lifecycle IN('PUBLISHED','SUPERSEDED')) THEN RAISE EXCEPTION 'daily media requires actual immutable source metadata' USING ERRCODE='23514'; END IF;
  -- Reuse the exact existing binary/rights/worker proof validator one metadata target at a time.
  -- This explicit profile permits shared originals; no policy/review validator is changed.
  PERFORM public.assert_publication_manifest_media(jsonb_build_object('revision',jsonb_build_object('target',jsonb_build_object('kind','MEDIA_METADATA'),'revisionId',metadata.revision_id),'mediaRevisions','[]'::jsonb,'media',jsonb_build_object('assets',jsonb_build_array(item->'asset'),'variants',item->'variants','lineage',jsonb_build_array(item->'lineage'))));
 END LOOP;
 IF (SELECT count(*) FROM public.content_purge_jobs WHERE publication_id=p.id AND generation=1)<>7 THEN RAISE EXCEPTION 'daily publication retains seven real localized purge events' USING ERRCODE='23514'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_daily_revision(revision uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE d public.daily_publication_revisions%ROWTYPE; o public.management_operations%ROWTYPE; parent jsonb; owner_value uuid; fields jsonb; expected_hash text;
BEGIN
 SELECT * INTO d FROM public.daily_publication_revisions WHERE revision_id=revision;
 SELECT * INTO o FROM public.management_operations WHERE id=d.operation_id;
 IF d.revision_id IS NULL OR d.actor_id IS DISTINCT FROM o.actor_id OR d.source_locale::text IS DISTINCT FROM d.document#>>'{source,locale}'
 OR d.source_translation_id IS DISTINCT FROM (d.document#>>'{source,id}')::uuid OR d.document->>'schemaVersion'<>'3' OR d.object_kind IS DISTINCT FROM d.document->>'kind'
 OR d.object_id IS DISTINCT FROM (d.document->>'ownerId')::uuid OR d.revision_id IS DISTINCT FROM (d.document->>'revisionId')::uuid
 OR d.actor_id IS DISTINCT FROM (d.document->>'createdBy')::uuid OR d.actor_id IS DISTINCT FROM (d.document#>>'{source,editorId}')::uuid
 OR d.created_at IS DISTINCT FROM (d.document->>'createdAt')::timestamptz OR d.document#>'{source,review}' IS NOT NULL THEN RAISE EXCEPTION 'daily revision must bind one real authored original' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_management_authority(d.operation_id);
 EXECUTE format('SELECT to_jsonb(r.*) FROM public.%I r WHERE id=$1',lower(d.object_kind)||'_revisions') INTO parent USING revision;
 owner_value:=CASE d.object_kind WHEN 'IDOL' THEN (parent->>'idol_id')::uuid WHEN 'GIFT' THEN (parent->>'gift_id')::uuid WHEN 'MEDIA_METADATA' THEN (parent->>'media_asset_id')::uuid ELSE revision END;
 IF parent IS NULL OR owner_value<>d.object_id OR (parent->>'created_by')::uuid<>d.actor_id OR (parent->>'created_at')::timestamptz<>d.created_at
 OR (parent->>'revision')::bigint<>(d.document->>'revisionNumber')::bigint THEN RAISE EXCEPTION 'daily document requires exact typed revision ownership' USING ERRCODE='23514'; END IF;
 fields:=d.document#>'{source,fields}';
 expected_hash:=encode(sha256(convert_to('fan-support.daily-publication.v1/source'||chr(10)||public.canonical_publication_json(jsonb_build_object('kind',d.object_kind,'locale',d.source_locale,'fields',fields)),'UTF8')),'hex');
 IF d.document#>>'{source,sourceHash}' IS DISTINCT FROM expected_hash OR d.document_hash IS DISTINCT FROM encode(sha256(convert_to('fan-support.daily-publication.v1/document'||chr(10)||public.canonical_publication_json(d.document),'UTF8')),'hex') THEN RAISE EXCEPTION 'daily source and document hashes bind actual originals' USING ERRCODE='23514'; END IF;
 IF d.object_kind='IDOL' THEN
  IF o.intent->>'kind'<>'SAVE_ARTIST' OR o.target_id<>d.object_id OR fields->>'displayName' IS DISTINCT FROM o.intent->>'name' OR fields->>'fullBio' IS DISTINCT FROM o.intent->>'description'
   OR length(fields->>'displayName') NOT BETWEEN 1 AND 40 OR length(fields->>'fullBio') NOT BETWEEN 1 AND 600 THEN RAISE EXCEPTION 'daily artist fields must be exact authorized original' USING ERRCODE='23514'; END IF;
 ELSIF d.object_kind='GIFT' THEN
  IF o.intent->>'kind'<>'SAVE_GIFT' OR o.target_id<>d.object_id OR fields->>'title' IS DISTINCT FROM o.intent->>'name' OR fields->>'description' IS DISTINCT FROM o.intent->>'description' OR d.document->>'giftKind' IS DISTINCT FROM o.intent->>'giftKind'
   OR length(fields->>'title') NOT BETWEEN 1 AND 100 OR length(fields->>'description') NOT BETWEEN 1 AND 600 THEN RAISE EXCEPTION 'daily gift fields must be exact authorized original' USING ERRCODE='23514'; END IF;
 ELSIF d.object_kind='HOMEPAGE' THEN
  IF o.intent->>'kind' NOT IN('REPLACE_POSTER','RESTORE_POSTER') THEN RAISE EXCEPTION 'daily homepage requires poster intent' USING ERRCODE='23514'; END IF;
 ELSE
  IF length(fields->>'alt') NOT BETWEEN 1 AND 300 OR NOT EXISTS(SELECT 1 FROM public.media_assets WHERE id=d.object_id) THEN RAISE EXCEPTION 'daily metadata requires actual media and original alt' USING ERRCODE='23514'; END IF;
 END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_finance_order_projection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE total bigint; target text;
BEGIN
 IF NEW.event_type='PAYMENT_STATUS_CHANGED' AND NEW.authority_kind='REFUND_AGGREGATE' THEN
 SELECT coalesce(sum(processed_amount_minor),0) INTO total FROM refunds WHERE order_id=NEW.order_id AND status='SUCCEEDED';
 SELECT CASE WHEN total=o.total_amount_minor THEN 'REFUNDED' WHEN total>0 AND total<o.total_amount_minor THEN 'PARTIALLY_REFUNDED' ELSE 'PAID' END INTO target FROM orders o WHERE o.id=NEW.order_id;
 IF NEW.to_payment_status IS DISTINCT FROM target THEN RAISE EXCEPTION 'refund order projection requires exact successful total' USING ERRCODE='23514';END IF;
 ELSIF NEW.event_type='DISPUTE_STATUS_CHANGED' THEN
 SELECT CASE WHEN bool_or(status='LOST') THEN 'LOST' WHEN bool_or(status='OPEN') THEN 'OPEN' WHEN bool_and(status='WON') THEN 'WON' ELSE 'NONE' END INTO target FROM disputes WHERE order_id=NEW.order_id AND status<>'NONE';
 IF NEW.to_dispute_status IS DISTINCT FROM target OR NOT EXISTS(SELECT 1 FROM disputes WHERE order_id=NEW.order_id AND provider_event_id=NEW.provider_event_id) THEN RAISE EXCEPTION 'dispute projection requires exact trusted dispute collection' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END;$function$

CREATE OR REPLACE FUNCTION public.assert_finance_projection_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE target_order uuid := NEW.order_id; target text; current text; total bigint;
BEGIN
 IF TG_TABLE_NAME='disputes' THEN
 SELECT CASE WHEN bool_or(status='LOST') THEN 'LOST' WHEN bool_or(status='OPEN') THEN 'OPEN' WHEN bool_and(status='WON') THEN 'WON' ELSE 'NONE' END INTO target FROM disputes WHERE order_id=target_order AND status<>'NONE';
 SELECT dispute_status INTO current FROM orders WHERE id=target_order;
 ELSE
 SELECT coalesce(sum(processed_amount_minor),0) INTO total FROM refunds WHERE order_id=target_order AND status='SUCCEEDED';
 SELECT CASE WHEN total=o.total_amount_minor THEN 'REFUNDED' WHEN total>0 AND total<o.total_amount_minor THEN 'PARTIALLY_REFUNDED' ELSE 'PAID' END,payment_status INTO target,current FROM orders o WHERE o.id=target_order;
 END IF;
 IF target IS DISTINCT FROM current THEN RAISE EXCEPTION 'financial evidence must atomically project its complete order aggregate' USING ERRCODE='23514';END IF;RETURN NULL;
END;$function$

CREATE OR REPLACE FUNCTION public.assert_fulfillment_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  current_order orders%ROWTYPE;
  total_count bigint;
  delivered_count bigint;
  canceled_count bigint;
  hold_count bigint;
  progressing_count bigint;
  derived_status text;
  invalid_active_count bigint;
BEGIN
  target_order_id := COALESCE(
    (to_jsonb(NEW) ->> 'order_id')::uuid,
    (to_jsonb(OLD) ->> 'order_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  SELECT * INTO current_order FROM orders WHERE id = target_order_id;
  IF current_order.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT count(*),
         count(*) FILTER (WHERE status = 'DELIVERED'),
         count(*) FILTER (WHERE status = 'CANCELED'),
         count(*) FILTER (WHERE status = 'ON_HOLD'),
         count(*) FILTER (WHERE status IN ('PREPARING', 'DELIVERED')),
         count(*) FILTER (
           WHERE status IN ('PREPARING', 'DELIVERED', 'ON_HOLD')
             AND NOT (
               current_order.order_status IN ('OPEN', 'CLOSED')
               AND current_order.payment_status IN ('PAID', 'PARTIALLY_REFUNDED', 'REFUNDED')
             )
         )
  INTO total_count, delivered_count, canceled_count, hold_count,
       progressing_count, invalid_active_count
  FROM fulfillments
  WHERE order_id = target_order_id;

  IF total_count = 0 OR invalid_active_count <> 0 THEN
    RAISE EXCEPTION 'fulfillment aggregate requires paid active work and at least one row'
      USING ERRCODE = '23514';
  END IF;

  derived_status := CASE
    WHEN canceled_count = total_count THEN 'CANCELED'
    WHEN delivered_count = total_count THEN 'DELIVERED'
    WHEN hold_count > 0 THEN 'ON_HOLD'
    WHEN progressing_count > 0 THEN 'PREPARING'
    ELSE 'PENDING'
  END;

  IF current_order.fulfillment_status <> derived_status THEN
    RAISE EXCEPTION 'order fulfillment aggregate does not match fulfillment rows'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_fulfillment_event_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_fulfillment_id uuid;
  current_fulfillment fulfillments%ROWTYPE;
  head_event fulfillment_events%ROWTYPE;
BEGIN
  target_fulfillment_id := COALESCE(
    (to_jsonb(NEW) ->> 'fulfillment_id')::uuid,
    (to_jsonb(OLD) ->> 'fulfillment_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );

  SELECT * INTO current_fulfillment FROM fulfillments WHERE id = target_fulfillment_id;
  IF current_fulfillment.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO head_event
  FROM fulfillment_events
  WHERE fulfillment_id = target_fulfillment_id
  ORDER BY sequence DESC
  LIMIT 1;

  IF head_event.id IS NULL
     OR head_event.sequence <> current_fulfillment.version
     OR head_event.to_status <> current_fulfillment.status
     OR (current_fulfillment.status IN ('ON_HOLD', 'CANCELED')
       AND head_event.reason_code <> current_fulfillment.hold_reason_code) THEN
    RAISE EXCEPTION 'fulfillment event head must equal versioned fulfillment state'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_gift_commerce_audit(audit_id uuid, actor uuid, session_id uuid, expected_action text, expected_subject text, subject uuid, request_id uuid, reason text, event_time timestamp with time zone, required_permission text, causal_lower_bound timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE a public.audit_logs%ROWTYPE; s public.admin_sessions%ROWTYPE; identity_status text;
BEGIN
  SELECT * INTO a FROM public.audit_logs WHERE id=audit_id;
  SELECT * INTO s FROM public.admin_sessions WHERE id=session_id FOR SHARE;
  SELECT status INTO identity_status FROM public.admin_identities WHERE id=actor FOR SHARE;
  IF a.id IS NULL OR a.actor_type IS DISTINCT FROM 'ADMIN' OR a.actor_id IS DISTINCT FROM actor
    OR a.action IS DISTINCT FROM expected_action OR a.subject_type IS DISTINCT FROM expected_subject OR a.subject_id IS DISTINCT FROM subject
    OR a.outcome IS DISTINCT FROM 'SUCCEEDED' OR a.field_category IS DISTINCT FROM 'GIFT_COMMERCE'
    OR a.request_id IS DISTINCT FROM request_id OR a.correlation_id IS DISTINCT FROM request_id
    OR a.reason_code IS DISTINCT FROM reason OR a.created_at IS DISTINCT FROM event_time THEN
    RAISE EXCEPTION 'gift commerce requires its exact audit' USING ERRCODE='23514',CONSTRAINT='gift_commerce_audit';
  END IF;
  IF s.id IS NULL OR s.admin_identity_id IS DISTINCT FROM actor OR identity_status IS DISTINCT FROM 'ACTIVE'
    OR NOT s.authenticated_with_mfa OR s.revoked_at IS NOT NULL OR s.expires_at<=clock_timestamp()
    OR s.created_at>clock_timestamp() OR event_time<s.created_at OR event_time>=s.expires_at
    OR event_time>GREATEST(clock_timestamp(),transaction_timestamp(),s.created_at,causal_lower_bound) THEN
    RAISE EXCEPTION 'gift commerce requires current MFA authority' USING ERRCODE='23514',CONSTRAINT='gift_commerce_session';
  END IF;
  PERFORM ar.role_id FROM public.admin_identity_roles ar JOIN public.roles r ON r.id=ar.role_id
    JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
    WHERE ar.admin_identity_id=actor AND p.permission_key=required_permission
      AND ar.granted_at<=clock_timestamp() AND rp.granted_at<=clock_timestamp()
      AND ar.granted_at<=event_time AND rp.granted_at<=event_time FOR SHARE OF ar,r,rp,p;
  IF NOT FOUND THEN RAISE EXCEPTION 'gift commerce requires current permission' USING ERRCODE='23514',CONSTRAINT='gift_commerce_permission'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_gift_content_profile_prior()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE prior public.gifts%ROWTYPE;
BEGIN
 SELECT * INTO prior FROM public.gifts WHERE id=NEW.gift_id FOR UPDATE;
 IF prior.id IS NULL OR prior.status='archived' OR prior.version IS DISTINCT FROM NEW.expected_base_version OR prior.updated_at IS DISTINCT FROM NEW.previous_base_updated_at THEN
  RAISE EXCEPTION 'gift content receipt requires exact locked prior identity' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_gift_content_profile_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE gift public.gifts%ROWTYPE; parent public.gift_revisions%ROWTYPE; authoring public.content_authoring_receipts%ROWTYPE;
BEGIN
 SELECT * INTO gift FROM public.gifts WHERE id=NEW.gift_id;
 SELECT * INTO parent FROM public.gift_revisions WHERE id=NEW.gift_revision_id;
 SELECT * INTO authoring FROM public.content_authoring_receipts WHERE id=NEW.authoring_receipt_id;
 IF gift.version IS DISTINCT FROM NEW.expected_base_version+1 OR gift.draft_revision_id IS DISTINCT FROM NEW.gift_revision_id OR parent.gift_id IS DISTINCT FROM NEW.gift_id OR parent.revision IS DISTINCT FROM NEW.result_authoring_version OR parent.created_by IS DISTINCT FROM NEW.actor_id OR parent.created_at IS DISTINCT FROM NEW.created_at OR authoring.gift_revision_id IS DISTINCT FROM NEW.gift_revision_id OR authoring.expected_version IS DISTINCT FROM NEW.expected_authoring_version OR authoring.actor_id IS DISTINCT FROM NEW.actor_id OR authoring.created_at IS DISTINCT FROM NEW.created_at THEN RAISE EXCEPTION 'gift profile receipt requires exact content authoring lineage' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_gift_commerce_audit(NEW.audit_log_id,NEW.actor_id,NEW.session_id,'SAVE_GIFT_CONTENT','GIFT_REVISION_PROFILE',NEW.gift_revision_id,NEW.request_id,NEW.reason_code,NEW.created_at,'gift.manage',NEW.previous_base_updated_at);
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_gift_detail_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE draft public.gift_detail_documents%ROWTYPE; target uuid; n integer; last_position integer; english_hash public.sha256_hex; block record; translation record;
BEGIN
  IF TG_TABLE_NAME = 'gift_detail_documents' THEN target := NEW.id;
  ELSIF TG_TABLE_NAME = 'gift_detail_translation_reviews' THEN
    SELECT document_id INTO target FROM public.gift_detail_translations WHERE id = NEW.gift_detail_translation_id;
  ELSE target := NEW.document_id; END IF;
  SELECT * INTO draft FROM public.gift_detail_documents WHERE id = target;
  PERFORM public.assert_content_draft_audit(draft.audit_log_id,draft.editor_id,draft.id,'GIFT_DETAIL_DOCUMENT','GIFT_DETAIL_DRAFT_CREATE',draft.request_id,draft.edited_at);
  SELECT count(*),max(position) INTO n,last_position FROM public.gift_detail_blocks WHERE document_id = target;
  IF n <> draft.block_count OR last_position <> n - 1 THEN
    RAISE EXCEPTION 'detail document requires its complete ordered blocks' USING ERRCODE = '23514';
  END IF;
  SELECT source_hash INTO english_hash FROM public.gift_detail_translations WHERE document_id = target AND locale = 'en';
  IF english_hash IS NULL OR (SELECT count(*) FROM public.gift_detail_translations WHERE document_id = target) <> draft.translation_count THEN
    RAISE EXCEPTION 'detail document requires its exact translation set including English' USING ERRCODE = '23514';
  END IF;
  FOR block IN SELECT * FROM public.gift_detail_blocks WHERE document_id = target LOOP
    SELECT count(*),max(position) INTO n,last_position FROM public.gift_detail_block_items WHERE document_id = target AND block_id = block.block_id;
    IF n <> block.item_count OR (n > 0 AND last_position <> n - 1) THEN
      RAISE EXCEPTION 'detail block requires its complete ordered item keys' USING ERRCODE = '23514';
    END IF;
  END LOOP;
  FOR translation IN SELECT * FROM public.gift_detail_translations WHERE document_id = target LOOP
    IF translation.translated_from_source_hash <> english_hash OR translation.editor_id <> draft.editor_id OR translation.edited_at <> draft.edited_at THEN
      RAISE EXCEPTION 'detail translation must bind the canonical draft and English source' USING ERRCODE = '23514';
    END IF;
    IF (SELECT count(*) FROM public.gift_detail_translation_blocks WHERE translation_id = translation.id) <> draft.block_count
      OR NOT EXISTS (SELECT 1 FROM public.gift_detail_translation_reviews WHERE gift_detail_translation_id = translation.id AND sequence = 1 AND status = 'DRAFT' AND audit_log_id = draft.audit_log_id) THEN
      RAISE EXCEPTION 'detail translation requires complete blocks and initial draft review' USING ERRCODE = '23514';
    END IF;
    FOR block IN SELECT b.*,t.media_metadata_revision_id translated_media,t.caption
      FROM public.gift_detail_blocks b JOIN public.gift_detail_translation_blocks t ON t.document_id = b.document_id AND t.block_id = b.block_id
      WHERE b.document_id = target AND t.translation_id = translation.id LOOP
      IF (SELECT count(*) FROM public.gift_detail_translation_items WHERE translation_id = translation.id AND block_id = block.block_id) <> block.item_count
        OR (block.kind = 'MEDIA' AND (block.translated_media IS DISTINCT FROM block.media_metadata_revision_id OR (block.caption_enabled AND block.caption IS NULL) OR (NOT block.caption_enabled AND block.caption IS NOT NULL)))
        OR EXISTS (SELECT 1 FROM public.gift_detail_translation_items i WHERE i.translation_id = translation.id AND i.block_id = block.block_id
          AND ((block.kind = 'LIST' AND i.text IS NULL) OR (block.kind = 'SPECIFICATIONS' AND (i.label IS NULL OR i.value IS NULL)))) THEN
        RAISE EXCEPTION 'translated detail items and media must match document structure' USING ERRCODE = '23514';
      END IF;
    END LOOP;
  END LOOP;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_gift_identity_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  -- Explicit ADR-012 dispatch; all following strict behavior is retained.
  IF EXISTS(SELECT 1 FROM public.daily_publication_manifests m JOIN public.daily_publication_revisions d ON d.revision_id=m.revision_id JOIN public.management_operations o ON o.id=m.operation_id WHERE d.object_kind='GIFT' AND d.object_id=NEW.id AND o.target_id=NEW.id AND o.intent->>'kind'='SAVE_GIFT' AND (TG_OP='INSERT' AND m.expected_base_version=0 OR TG_OP='UPDATE' AND m.result_base_version=NEW.version AND m.expected_base_version=CASE WHEN OLD.version=1 AND (o.intent->>'expectedVersion')::bigint=0 THEN 0 ELSE OLD.version END)) THEN RETURN NULL; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NULL; END IF;
 IF TG_OP='UPDATE' AND NEW.status IN('active','paused') AND NEW.published_revision_id IS DISTINCT FROM OLD.published_revision_id AND EXISTS(
 SELECT 1 FROM public.content_publication_receipts r JOIN public.content_publications p ON p.id=r.publication_id WHERE p.gift_id=NEW.id AND p.gift_revision_id=NEW.published_revision_id AND r.created_at=NEW.updated_at AND r.action IN('PUBLISH','ROLLBACK')) THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.gift_identity_receipts r WHERE r.gift_id=NEW.id AND r.result_base_version=NEW.version AND r.new_status=NEW.status AND r.handle=NEW.handle AND r.created_at=NEW.updated_at
 AND ((TG_OP='INSERT' AND r.action='CREATE_GIFT' AND r.created_at=NEW.created_at) OR (TG_OP='UPDATE' AND r.expected_base_version=OLD.version AND r.old_status=OLD.status AND r.previous_updated_at=OLD.updated_at))) THEN
 RAISE EXCEPTION 'gift identity change requires its exact receipt' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_gift_identity_prior()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE prior public.gifts%ROWTYPE;
BEGIN
 SELECT * INTO prior FROM public.gifts WHERE id=NEW.gift_id FOR UPDATE;
 IF NEW.action='CREATE_GIFT' THEN
  IF prior.id IS NOT NULL THEN RAISE EXCEPTION 'gift identity creation requires an absent gift' USING ERRCODE='23514'; END IF;
 ELSE
  IF prior.id IS NULL OR prior.version IS DISTINCT FROM NEW.expected_base_version OR prior.status IS DISTINCT FROM NEW.old_status OR prior.handle IS DISTINCT FROM NEW.handle OR prior.updated_at IS DISTINCT FROM NEW.previous_updated_at THEN
   RAISE EXCEPTION 'gift identity receipt requires its exact locked prior state' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_gift_identity_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE gift public.gifts%ROWTYPE; proof jsonb; dependency jsonb;
BEGIN
 SELECT * INTO gift FROM public.gifts WHERE id=NEW.gift_id FOR UPDATE;
 IF gift.id IS NULL OR gift.version IS DISTINCT FROM NEW.result_base_version OR gift.handle IS DISTINCT FROM NEW.handle OR gift.status IS DISTINCT FROM NEW.new_status OR gift.updated_at IS DISTINCT FROM NEW.created_at THEN RAISE EXCEPTION 'gift receipt must match the actual identity' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_gift_commerce_audit(NEW.audit_log_id,NEW.actor_id,NEW.session_id,NEW.action,'GIFT_IDENTITY',NEW.gift_id,NEW.request_id,NEW.reason_code,NEW.created_at,'gift.manage',NEW.previous_updated_at);
 IF NEW.new_status IN('active','paused') AND gift.published_revision_id IS NULL THEN RAISE EXCEPTION 'available gift requires a publication' USING ERRCODE='23514'; END IF;
 IF NEW.new_status='active' THEN
  SELECT m.manifest INTO proof FROM public.gift_publication_heads h JOIN public.content_publications p ON p.id=h.publication_id AND p.gift_id=h.gift_id AND p.gift_revision_id=h.gift_revision_id JOIN public.content_publication_manifests m ON m.publication_id=p.id JOIN public.content_publication_receipts r ON r.manifest_id=m.id AND r.publication_id=p.id AND r.result_head_version=h.version WHERE h.gift_id=NEW.gift_id AND h.gift_revision_id=gift.published_revision_id AND p.proof_version=2;
  IF proof IS NULL THEN RAISE EXCEPTION 'gift activation requires a verified current publication' USING ERRCODE='23514'; END IF;
  PERFORM public.assert_publication_manifest_revision(proof->'revision');
  FOR dependency IN SELECT * FROM jsonb_array_elements(proof->'mediaRevisions') LOOP PERFORM public.assert_publication_manifest_revision(dependency); END LOOP;
  PERFORM public.assert_publication_manifest_approvals(proof); PERFORM public.assert_publication_manifest_media(proof);
 END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_gift_inventory_adjustment_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE l public.inventory_ledger%ROWTYPE; b public.inventory_balances%ROWTYPE; lower_bound timestamptz; variant_time timestamptz;
BEGIN
 SELECT * INTO l FROM public.inventory_ledger WHERE id=NEW.ledger_id;
 SELECT * INTO b FROM public.inventory_balances WHERE inventory_item_id=NEW.inventory_item_id AND location_id=NEW.inventory_location_id FOR UPDATE;
 SELECT updated_at INTO variant_time FROM public.gift_variants WHERE id=NEW.gift_variant_id FOR SHARE;
 SELECT max(occurred_at) INTO lower_bound FROM public.inventory_ledger WHERE inventory_item_id=NEW.inventory_item_id AND location_id=NEW.inventory_location_id AND balance_version_after=NEW.expected_balance_version;
 IF l.id IS NULL OR l.inventory_item_id IS DISTINCT FROM NEW.inventory_item_id OR l.location_id IS DISTINCT FROM NEW.inventory_location_id
   OR l.balance_version_before IS DISTINCT FROM NEW.expected_balance_version OR l.balance_version_after IS DISTINCT FROM NEW.result_balance_version
   OR l.delta_on_hand IS DISTINCT FROM NEW.delta_on_hand OR l.delta_reserved<>0 OR l.reservation_id IS NOT NULL
   OR l.source_type<>'ADJUSTMENT' OR l.source_id IS DISTINCT FROM NEW.id OR l.actor_kind<>'ADMIN' OR l.admin_identity_id IS DISTINCT FROM NEW.actor_id
   OR l.reason_code IS DISTINCT FROM NEW.reason_code OR l.occurred_at IS DISTINCT FROM NEW.created_at
   OR NEW.created_at<GREATEST(lower_bound,NEW.previous_balance_updated_at,variant_time)
   OR b.version IS DISTINCT FROM NEW.result_balance_version OR b.on_hand IS DISTINCT FROM NEW.previous_on_hand+NEW.delta_on_hand OR b.reserved IS DISTINCT FROM NEW.previous_reserved THEN
   RAISE EXCEPTION 'inventory receipt requires exact ledger and final balance' USING ERRCODE='23514',CONSTRAINT='gift_inventory_result';
 END IF;
 PERFORM public.assert_gift_commerce_audit(NEW.audit_log_id,NEW.actor_id,NEW.session_id,'ADJUST_INVENTORY','INVENTORY_ADJUSTMENT',NEW.id,NEW.request_id,NEW.reason_code,NEW.created_at,'inventory.manage',GREATEST(lower_bound,NEW.previous_balance_updated_at,variant_time));
 RETURN NULL;
END; $function$

