$function$

CREATE OR REPLACE FUNCTION public.assert_order_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  current_order orders%ROWTYPE;
  item_count bigint;
  fulfillment_count bigint;
  policy_count bigint;
  quote_line_count bigint;
  item_subtotal numeric;
  item_tax numeric;
  item_discount numeric;
  item_total numeric;
  foreign_currency_count bigint;
BEGIN
  target_order_id := COALESCE(
    (to_jsonb(NEW) ->> 'order_id')::uuid,
    (to_jsonb(OLD) ->> 'order_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );

  SELECT * INTO current_order FROM orders WHERE id = target_order_id FOR UPDATE;
  IF current_order.id IS NULL THEN
    RETURN NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM checkout_sessions session
    WHERE session.id = current_order.checkout_session_id
      AND session.quote_id = current_order.checkout_quote_id
      AND session.cart_id = current_order.cart_id
      AND session.market = current_order.market
      AND session.currency = current_order.currency
      AND session.quote_revision = current_order.quote_revision
      AND session.quote_expires_at = current_order.quote_expires_at
      AND session.subtotal_minor = current_order.subtotal_minor
      AND session.tax_amount_minor = current_order.tax_amount_minor
      AND session.shipping_amount_minor = current_order.shipping_amount_minor
      AND session.fee_amount_minor = current_order.fee_amount_minor
      AND session.discount_amount_minor = current_order.discount_amount_minor
      AND session.total_amount_minor = current_order.total_amount_minor
  ) THEN
    RAISE EXCEPTION 'order amount snapshot must reproduce its checkout session'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*), COALESCE(sum(line_subtotal_minor), 0), COALESCE(sum(tax_amount_minor), 0),
         COALESCE(sum(discount_amount_minor), 0), COALESCE(sum(line_total_minor), 0),
         count(*) FILTER (WHERE currency <> current_order.currency)
  INTO item_count, item_subtotal, item_tax, item_discount, item_total, foreign_currency_count
  FROM order_items
  WHERE order_id = target_order_id;

  SELECT count(*) INTO policy_count FROM policy_acceptances WHERE order_id = target_order_id;
  SELECT count(*) INTO fulfillment_count FROM fulfillments WHERE order_id = target_order_id;
  SELECT count(*) INTO quote_line_count
  FROM checkout_quote_lines
  WHERE checkout_session_id = current_order.checkout_session_id
    AND checkout_quote_id = current_order.checkout_quote_id;

  IF item_count = 0 OR item_count <> quote_line_count
     OR policy_count = 0 OR fulfillment_count <> item_count
     OR foreign_currency_count <> 0
     OR item_subtotal <> current_order.subtotal_minor
     OR item_tax <> current_order.tax_amount_minor
     OR item_discount <> current_order.discount_amount_minor
     OR item_total + current_order.shipping_amount_minor + current_order.fee_amount_minor
        <> current_order.total_amount_minor THEN
    RAISE EXCEPTION 'order lines, policies, fulfillments, and amount snapshot diverge'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_order_event_head()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  current_order orders%ROWTYPE;
  head_event order_events%ROWTYPE;
BEGIN
  target_order_id := COALESCE(
    (to_jsonb(NEW) ->> 'order_id')::uuid,
    (to_jsonb(OLD) ->> 'order_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );

  SELECT * INTO current_order FROM orders WHERE id = target_order_id;
  IF current_order.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO head_event
  FROM order_events
  WHERE order_id = target_order_id
  ORDER BY sequence DESC
  LIMIT 1;

  IF head_event.id IS NULL
     OR head_event.sequence <> current_order.version
     OR head_event.to_order_status <> current_order.order_status
     OR head_event.to_payment_status <> current_order.payment_status
     OR head_event.to_dispute_status <> current_order.dispute_status
     OR head_event.to_fulfillment_status <> current_order.fulfillment_status
     OR head_event.to_payment_attempt_id IS DISTINCT FROM current_order.current_payment_attempt_id THEN
    RAISE EXCEPTION 'order event head must equal the versioned order aggregate'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_order_payment_application_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM provider_events e WHERE e.id=NEW.provider_event_id AND coalesce(e.canonical_transaction_event_id,e.id)=NEW.canonical_provider_event_id)
    OR (NEW.attempt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM payment_attempts a WHERE a.id=NEW.attempt_id AND a.order_id=NEW.order_id)) THEN
    RAISE EXCEPTION 'order payment receipt must retain exact source and aggregate identity' USING ERRCODE='23514';
  END IF;
  IF NEW.decision<>'APPLIED' THEN RETURN NULL; END IF;
  -- A later source observes the already completed effect; later fulfillment/refund progression does not revoke that history.
  IF NEW.provider_event_id<>NEW.canonical_provider_event_id THEN
    IF NOT EXISTS(SELECT 1 FROM order_payment_application_receipts canonical
      WHERE canonical.provider_event_id=NEW.canonical_provider_event_id AND canonical.canonical_provider_event_id=canonical.provider_event_id
        AND canonical.decision='APPLIED' AND canonical.attempt_id=NEW.attempt_id AND canonical.order_id=NEW.order_id AND canonical.outcome=NEW.outcome) THEN
      RAISE EXCEPTION 'capture alias receipt requires the permanent canonical application' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM provider_events e JOIN provider_event_associations matched ON matched.provider_event_id=e.id AND matched.association_status='MATCHED' AND matched.payment_attempt_id=NEW.attempt_id JOIN payment_attempts a ON a.id=NEW.attempt_id JOIN orders o ON o.id=a.order_id
    WHERE e.id=NEW.canonical_provider_event_id AND e.event_type='PAYMENT_STATUS' AND e.normalized_status=a.status
      AND a.provider_event_id=e.id AND a.status_evidence_kind=e.evidence_kind AND a.evidence_audit_log_id IS NOT DISTINCT FROM e.reconcile_audit_log_id
      AND a.provider_account_id=e.provider_account_id AND a.environment=e.environment AND a.external_reference=e.external_payment_reference AND a.amount_minor=e.amount_minor AND a.currency=e.currency
      AND o.id=NEW.order_id AND o.current_payment_attempt_id=a.id
      AND ((NEW.outcome IN('PAID','PAID_REVIEW') AND a.status='SUCCEEDED' AND o.order_status='OPEN' AND o.payment_status='PAID'
        AND EXISTS(SELECT 1 FROM carts c WHERE c.id=o.cart_id AND c.status='CONVERTED' AND c.locked_order_id=o.id)
        AND NOT EXISTS(SELECT 1 FROM order_items i JOIN support_intents s ON s.id=i.support_intent_id WHERE i.order_id=o.id AND s.status<>'CONVERTED')
        AND NOT EXISTS(SELECT 1 FROM fulfillments f WHERE f.order_id=o.id AND f.status<>CASE WHEN NEW.outcome='PAID_REVIEW' THEN 'ON_HOLD' ELSE 'PENDING' END))
      OR (NEW.outcome='FAILED_RELEASED' AND a.status IN('FAILED','CANCELED','EXPIRED') AND o.payment_status='PENDING'))
      AND NOT EXISTS(SELECT 1 FROM inventory_reservations r WHERE r.locked_order_id=o.id AND r.status='ACTIVE')
  ) THEN RAISE EXCEPTION 'order payment receipt requires the complete canonical aggregate' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END;
$function$

