CREATE OR REPLACE FUNCTION public.assert_payment_provider_translation_package(target_provider_config_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  english_hash sha256_hex;
  translation_count integer;
  approved_count integer;
  lineage_count integer;
BEGIN
  SELECT source_hash INTO english_hash
    FROM payment_provider_config_translations
    WHERE provider_config_id = target_provider_config_id AND locale = 'en';

  IF english_hash IS NULL THEN
    RAISE EXCEPTION 'payment provider config publication requires an English translation'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*),
    count(*) FILTER (WHERE latest.status = 'APPROVED'),
    count(*) FILTER (WHERE translation.translated_from_source_hash = english_hash)
    INTO translation_count, approved_count, lineage_count
    FROM payment_provider_config_translations translation
    LEFT JOIN LATERAL (
      SELECT review.status
      FROM payment_provider_config_translation_reviews review
      WHERE review.provider_config_translation_id = translation.id
      ORDER BY review.sequence DESC
      LIMIT 1
    ) latest ON true
    WHERE translation.provider_config_id = target_provider_config_id;

  IF translation_count <> 7 OR approved_count <> 7 OR lineage_count <> 7 THEN
    RAISE EXCEPTION 'payment provider config publication requires seven approved current translations'
      USING ERRCODE = '23514';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_policy_registration_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE owner public.policies%ROWTYPE;
BEGIN
  SELECT * INTO owner FROM public.policies WHERE policy_key=NEW.policy_key FOR UPDATE;
  IF owner.policy_key IS NULL OR owner.kind<>NEW.kind OR owner.created_at<>NEW.created_at THEN
    RAISE EXCEPTION 'policy registration requires exact immutable owner' USING ERRCODE='23514';
  END IF;
  PERFORM public.assert_resource_management_audit(NEW.audit_log_id,NEW.actor_id,NEW.session_id,'POLICY_REGISTER','POLICY_REGISTRATION',NEW.id,NEW.created_at);
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_price_book_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  price_count integer;
  published_count integer;
BEGIN
  IF NEW.lifecycle = 'PUBLISHED' THEN
    SELECT count(*), count(*) FILTER (WHERE status = 'PUBLISHED')
      INTO price_count, published_count
      FROM prices WHERE price_book_id = NEW.id AND price_book_revision = NEW.revision;
    IF price_count = 0 OR price_count <> published_count THEN
      RAISE EXCEPTION 'published price-book revision requires a non-empty published price set'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_provider_event_association()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  association_count integer;
BEGIN
  SELECT count(*) INTO association_count
    FROM provider_event_associations WHERE provider_event_id = NEW.id;
  IF association_count NOT IN (1, 2) THEN
    RAISE EXCEPTION 'provider event requires one initial association and at most one later match'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_provider_transaction_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_event_id uuid;
  event_row public.provider_events%ROWTYPE;
  matched_count integer;
  ledger_count integer;
BEGIN
  IF TG_TABLE_NAME = 'provider_events' THEN
    target_event_id := NEW.id;
  ELSIF TG_TABLE_NAME = 'provider_event_associations' THEN
    target_event_id := NEW.provider_event_id;
  ELSE
    RAISE EXCEPTION 'unsupported provider transaction ledger source: %', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO event_row
  FROM public.provider_events
  WHERE id = target_event_id;

  SELECT count(*) INTO matched_count
  FROM public.provider_event_associations association
  WHERE association.provider_event_id = target_event_id
    AND association.association_status = 'MATCHED';

  IF event_row.canonical_transaction_event_id IS NOT NULL THEN
    IF EXISTS(SELECT 1 FROM payment_transactions WHERE provider_event_id=target_event_id)
      OR NOT EXISTS(SELECT 1 FROM provider_events canonical JOIN payment_transactions ledger ON ledger.provider_event_id=canonical.id
        WHERE canonical.id=event_row.canonical_transaction_event_id AND canonical.canonical_transaction_event_id IS NULL
          AND ledger.transaction_type=event_row.provider_transaction_type AND ledger.provider_transaction_reference=event_row.provider_transaction_reference
          AND ledger.amount_minor=event_row.amount_minor AND ledger.currency=event_row.currency
          AND (matched_count=0 OR EXISTS(SELECT 1 FROM provider_event_associations a WHERE a.provider_event_id=target_event_id AND a.association_status='MATCHED' AND a.payment_attempt_id=ledger.payment_attempt_id))) THEN
      RAISE EXCEPTION 'payment capture alias must reuse its exact canonical ledger' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
  END IF;

  SELECT count(*) INTO ledger_count
  FROM public.payment_transactions transaction_row
  JOIN public.provider_event_associations association
    ON association.provider_event_id = target_event_id
   AND association.association_status = 'MATCHED'
   AND association.payment_attempt_id = transaction_row.payment_attempt_id
  WHERE transaction_row.provider_event_id = target_event_id
    AND transaction_row.transaction_type = event_row.provider_transaction_type
    AND transaction_row.provider_transaction_reference = event_row.provider_transaction_reference
    AND transaction_row.amount_minor = event_row.amount_minor
    AND transaction_row.currency = event_row.currency
    AND transaction_row.evidence_kind = event_row.evidence_kind
    AND transaction_row.reconcile_audit_log_id IS NOT DISTINCT FROM event_row.reconcile_audit_log_id
    AND transaction_row.occurred_at = event_row.occurred_at;

  IF event_row.id IS NULL
     OR (matched_count = 0 AND ledger_count <> 0)
     OR (matched_count = 1 AND event_row.provider_transaction_type IS NULL
       AND ledger_count <> 0)
     OR (matched_count = 1 AND event_row.provider_transaction_type IS NOT NULL
       AND ledger_count <> 1) THEN
    RAISE EXCEPTION 'provider transaction evidence and exact ledger record must commit together'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_publication_admin_audit(audit_id uuid, actor uuid, session_id uuid, expected_action text, expected_subject text, subject uuid, event_time timestamp with time zone, causal_bound timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE evidence public.audit_logs%ROWTYPE; session public.admin_sessions%ROWTYPE; active_status text; locale_count integer;
BEGIN
  SELECT * INTO evidence FROM public.audit_logs WHERE id=audit_id;
  SELECT * INTO session FROM public.admin_sessions WHERE id=session_id FOR SHARE;
  SELECT status INTO active_status FROM public.admin_identities WHERE id=actor FOR SHARE;
  IF evidence.id IS NULL OR evidence.actor_type<>'ADMIN' OR evidence.actor_id IS DISTINCT FROM actor OR evidence.action<>expected_action
    OR evidence.subject_type<>expected_subject OR evidence.subject_id<>subject OR evidence.outcome<>'SUCCEEDED' OR evidence.created_at<>event_time
    OR evidence.reason_code IS NULL OR evidence.request_id IS NULL OR evidence.correlation_id IS NULL OR evidence.field_category IS DISTINCT FROM 'CONTENT_PUBLICATION' THEN
    RAISE EXCEPTION 'publication action requires its exact audit evidence' USING ERRCODE='23514';
  END IF;
  IF session.id IS NULL OR session.admin_identity_id<>actor OR active_status IS DISTINCT FROM 'ACTIVE' OR NOT session.authenticated_with_mfa
    OR session.revoked_at IS NOT NULL OR session.expires_at<=clock_timestamp() OR session.created_at>clock_timestamp()
    OR event_time<session.created_at OR event_time>=session.expires_at OR event_time>GREATEST(clock_timestamp(),transaction_timestamp(),session.created_at,causal_bound) THEN
    RAISE EXCEPTION 'publication action requires its current active MFA session' USING ERRCODE='23514';
  END IF;
  PERFORM ar.role_id FROM public.admin_identity_roles ar JOIN public.roles r ON r.id=ar.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
    WHERE ar.admin_identity_id=actor AND p.permission_key='content.publish' AND ar.granted_at<=clock_timestamp() AND rp.granted_at<=clock_timestamp()
      AND ar.granted_at<=event_time AND rp.granted_at<=event_time FOR SHARE OF ar,r,rp,p;
  IF NOT FOUND THEN RAISE EXCEPTION 'publication action requires current publish permission' USING ERRCODE='23514'; END IF;
  PERFORM locale FROM public.admin_content_locale_grants WHERE admin_identity_id=actor AND revoked_at IS NULL AND granted_at<=clock_timestamp() AND granted_at<=event_time FOR SHARE;
  GET DIAGNOSTICS locale_count=ROW_COUNT;
  IF locale_count<>7 THEN RAISE EXCEPTION 'publication action requires all seven current locale scopes' USING ERRCODE='23514'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_publication_manifest_approvals(value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE revision jsonb; audit jsonb; source_audit jsonb; source_translation jsonb; source_review jsonb; edge jsonb; prior_edge jsonb; text_row jsonb; expected jsonb;
 approvals jsonb:='[]'; copies jsonb:='[]'; extension_approvals jsonb:='[]'; kind text; prefix text; parent_column text; translation_column text; source_revision uuid; prior_revision uuid; receipt_id uuid;
 alias public.idol_revision_alias_sets%ROWTYPE; detail public.gift_detail_documents%ROWTYPE; tr public.gift_detail_translations%ROWTYPE; review_row jsonb;
BEGIN
 FOR revision IN SELECT value->'revision' UNION ALL SELECT * FROM jsonb_array_elements(value->'mediaRevisions') LOOP
  kind:=revision#>>'{target,kind}'; prefix:=lower(kind); parent_column:=prefix||'_revision_id'; translation_column:=prefix||'_translation_id';
  FOR audit IN SELECT * FROM jsonb_array_elements(revision->'translationAudits') LOOP
   approvals:=approvals||jsonb_build_array(public.publication_approval(kind,(revision->>'revisionId')::uuid,audit));
   IF audit ? 'inheritedFrom' THEN
    EXECUTE format('SELECT to_jsonb(e.*),to_jsonb(s.*),to_jsonb(r.*),to_jsonb(old.*),receipt.id FROM public.%I e JOIN public.%I s ON s.id=e.source_translation_id JOIN public.%I r ON r.id=e.source_approval_review_id LEFT JOIN public.%I old ON old.target_translation_id=s.id JOIN public.content_authoring_receipts receipt ON receipt.%I=$2 AND receipt.audit_log_id=e.audit_log_id WHERE e.target_translation_id=$1',prefix||'_translation_copy_evidence',prefix||'_revision_translations',prefix||'_translation_reviews',prefix||'_translation_copy_evidence',parent_column)
      INTO edge,source_translation,source_review,prior_edge,receipt_id USING (audit->>'id')::uuid,(revision->>'revisionId')::uuid;
    IF edge IS NULL OR source_review->>'status' IS DISTINCT FROM 'APPROVED' THEN RAISE EXCEPTION 'manifest copy requires its exact immutable source approval and receipt' USING ERRCODE='23514'; END IF;
    source_revision:=(source_translation->>parent_column)::uuid;
    source_audit:=public.publication_pick_fields(source_translation,ARRAY['id','locale','sourceHash','translatedFromSourceHash','origin','importBatchId','editorId'])
      ||jsonb_build_object('reviewId',source_review->'id','reviewSequence',source_review->'sequence','editedAt',public.publication_utc((source_translation->>'edited_at')::timestamptz),'review',public.publication_approved_review(source_review,true));
    IF prior_edge IS NOT NULL THEN
      EXECUTE format('SELECT %I FROM public.%I WHERE id=$1',parent_column,prefix||'_revision_translations') INTO prior_revision USING (prior_edge->>'source_translation_id')::uuid;
      source_audit:=source_audit||jsonb_build_object('inheritedFrom',jsonb_build_object('revisionId',prior_revision,'translationId',prior_edge->'source_translation_id','reviewId',prior_edge->'source_approval_review_id'));
    END IF;
    -- 0015's immutable typed edge binds original raw fields, editor, origin and hashes to these target fields.
    SELECT item INTO text_row FROM jsonb_array_elements(revision#>'{content,translations}') item WHERE item->>'locale'=audit->>'locale';
    expected:=jsonb_build_object('target',jsonb_build_object('owner',revision->'target','revisionId',revision->'revisionId','locale',audit->'locale'),
      'targetTranslationId',audit->'id','targetReviewId',audit->'reviewId','authoringReceiptId',receipt_id,
      'source',jsonb_build_object('target',jsonb_build_object('owner',revision->'target','revisionId',source_revision,'locale',source_translation->'locale'),'text',jsonb_build_object('kind',kind,'fields',text_row->'fields'),'audit',source_audit),
      'sourceApproval',public.publication_approval(kind,source_revision,source_audit));
    copies:=copies||jsonb_build_array(expected);
   END IF;
  END LOOP;
 END LOOP;
 revision:=value->'revision';
 IF revision#>>'{target,kind}'='IDOL' THEN
  SELECT * INTO alias FROM public.idol_revision_alias_sets WHERE idol_revision_id=(revision->>'revisionId')::uuid;
  IF alias.id IS NOT NULL THEN
   SELECT to_jsonb(r.*) INTO review_row FROM public.idol_revision_alias_reviews r WHERE alias_set_id=alias.id ORDER BY sequence DESC LIMIT 1;
   extension_approvals:=jsonb_build_array(jsonb_build_object('kind','IDOL_ALIASES','revisionId',revision->'revisionId','subjectId',alias.id,'reviewId',review_row->'id','sequence',review_row->'sequence',
     'auditLogId',review_row->'audit_log_id','editorId',alias.editor_id,'structureEditorId',alias.editor_id,'reviewerId',review_row->'reviewer_id','editedAt',public.publication_utc(alias.edited_at),
     'reviewedAt',public.publication_utc((review_row->>'reviewed_at')::timestamptz),'contentHash',review_row->'reviewed_content_hash','sourceHash',NULL));
  END IF;
 ELSIF revision#>>'{target,kind}'='GIFT' THEN
  SELECT * INTO detail FROM public.gift_detail_documents WHERE gift_revision_id=(revision->>'revisionId')::uuid;
  FOR tr IN SELECT * FROM public.gift_detail_translations WHERE document_id=detail.id LOOP
   SELECT to_jsonb(r.*) INTO review_row FROM public.gift_detail_translation_reviews r WHERE gift_detail_translation_id=tr.id ORDER BY sequence DESC LIMIT 1;
   extension_approvals:=extension_approvals||jsonb_build_array(jsonb_build_object('kind','GIFT_DETAILS','revisionId',revision->'revisionId','subjectId',tr.id,'locale',tr.locale,'reviewId',review_row->'id','sequence',review_row->'sequence',
     'auditLogId',review_row->'audit_log_id','editorId',tr.editor_id,'structureEditorId',detail.editor_id,'reviewerId',review_row->'reviewer_id','editedAt',public.publication_utc(tr.edited_at),
     'reviewedAt',public.publication_utc((review_row->>'reviewed_at')::timestamptz),'contentHash',review_row->'reviewed_content_hash','sourceHash',review_row->'reviewed_source_hash'));
  END LOOP;
 END IF;
 IF NOT public.publication_same_set(value->'approvals',approvals) OR NOT public.publication_same_set(value->'copies',copies) OR NOT public.publication_same_set(value->'extensionApprovals',extension_approvals) THEN
  RAISE EXCEPTION 'manifest approval sections must contain exactly the real current reviews and typed copy edges' USING ERRCODE='23514';
 END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_publication_manifest_extensions(value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE kind text:=value#>>'{target,kind}'; revision uuid:=(value->>'revisionId')::uuid;
 a public.idol_revision_alias_sets%ROWTYPE; d public.gift_detail_documents%ROWTYPE; t public.gift_detail_translations%ROWTYPE;
 r jsonb; expected jsonb; actual jsonb; blocks jsonb; translated_blocks jsonb; translations jsonb:='[]'; text_translations jsonb:='[]'; english_hash text;
BEGIN
 IF kind='IDOL' THEN SELECT * INTO a FROM public.idol_revision_alias_sets WHERE idol_revision_id=revision FOR SHARE; END IF;
 IF a.id IS NULL THEN
   IF value#>'{extensions,aliases}' IS NOT NULL OR value#>'{content,aliases}' IS NOT NULL THEN RAISE EXCEPTION 'manifest cannot invent alias content' USING ERRCODE='23514'; END IF;
 ELSE
   SELECT to_jsonb(review.*) INTO r FROM public.idol_revision_alias_reviews review WHERE alias_set_id=a.id ORDER BY sequence DESC LIMIT 1;
   IF r->>'status' IS DISTINCT FROM 'APPROVED' OR r->>'sequence' IS DISTINCT FROM '3' OR r->>'reviewed_content_hash' IS DISTINCT FROM a.content_hash
     OR (r->>'reviewer_id')::uuid=a.editor_id THEN RAISE EXCEPTION 'manifest aliases require independent terminal approval' USING ERRCODE='23514'; END IF;
   SELECT coalesce(jsonb_agg(jsonb_build_object('id',alias_id,'locale',locale,'text',text) ORDER BY position),'[]') INTO actual FROM public.idol_revision_aliases WHERE alias_set_id=a.id;
   expected:=jsonb_build_object('schemaVersion',1,'id',a.id,'idolRevisionId',revision,'aliases',actual,'contentHash',a.content_hash,'editorId',a.editor_id,'editedAt',public.publication_utc(a.edited_at),'review',public.publication_approved_review(r,false));
   IF (value#>'{extensions,aliases}')-'aliases' IS DISTINCT FROM expected-'aliases' OR NOT public.publication_same_set(value#>'{extensions,aliases,aliases}',actual)
      OR NOT public.publication_same_set(value#>'{content,aliases}',actual) THEN RAISE EXCEPTION 'manifest must retain the complete actual alias set' USING ERRCODE='23514'; END IF;
 END IF;
 IF kind='GIFT' THEN SELECT * INTO d FROM public.gift_detail_documents WHERE gift_revision_id=revision FOR SHARE; END IF;
 IF d.id IS NULL THEN
   IF value#>'{extensions,details}' IS NOT NULL OR value#>'{content,details}' IS NOT NULL THEN RAISE EXCEPTION 'manifest cannot invent detail content' USING ERRCODE='23514'; END IF;
   RETURN;
 END IF;
 SELECT source_hash INTO english_hash FROM public.gift_detail_translations WHERE document_id=d.id AND locale='en';
 IF (SELECT count(*) FROM public.gift_detail_translations WHERE document_id=d.id)<>7 THEN RAISE EXCEPTION 'published detail requires all seven languages' USING ERRCODE='23514'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',b.block_id,'kind',b.kind)||CASE b.kind
   WHEN 'HEADING' THEN jsonb_build_object('level',b.heading_level)
   WHEN 'LIST' THEN jsonb_build_object('style',b.list_style,'itemIds',(SELECT jsonb_agg(item_id ORDER BY position) FROM public.gift_detail_block_items WHERE document_id=d.id AND block_id=b.block_id))
   WHEN 'SPECIFICATIONS' THEN jsonb_build_object('itemIds',(SELECT jsonb_agg(item_id ORDER BY position) FROM public.gift_detail_block_items WHERE document_id=d.id AND block_id=b.block_id))
   WHEN 'MEDIA' THEN public.publication_pick_fields(to_jsonb(b.*),ARRAY['mediaAssetId','mediaMetadataRevisionId','captionEnabled']) ELSE '{}'::jsonb END ORDER BY b.position)
 INTO blocks FROM public.gift_detail_blocks b WHERE document_id=d.id;
 FOR t IN SELECT * FROM public.gift_detail_translations WHERE document_id=d.id ORDER BY locale FOR SHARE LOOP
   SELECT to_jsonb(review.*) INTO r FROM public.gift_detail_translation_reviews review WHERE gift_detail_translation_id=t.id ORDER BY sequence DESC LIMIT 1;
   IF r->>'status' IS DISTINCT FROM 'APPROVED' OR r->>'sequence' IS DISTINCT FROM '3' OR r->>'reviewed_content_hash' IS DISTINCT FROM t.source_hash
      OR r->>'reviewed_source_hash' IS DISTINCT FROM english_hash OR t.translated_from_source_hash IS DISTINCT FROM english_hash
      OR (r->>'reviewer_id')::uuid IN (t.editor_id,d.editor_id) THEN RAISE EXCEPTION 'manifest details require current independent terminal approval' USING ERRCODE='23514'; END IF;
   SELECT jsonb_agg(jsonb_build_object('blockId',b.block_id,'kind',b.kind)||CASE b.kind
     WHEN 'HEADING' THEN jsonb_build_object('text',b.text) WHEN 'PARAGRAPH' THEN jsonb_build_object('text',b.text)
     WHEN 'LIST' THEN jsonb_build_object('items',(SELECT jsonb_agg(public.publication_pick_fields(to_jsonb(i.*),ARRAY['itemId','text']) ORDER BY i.item_id) FROM public.gift_detail_translation_items i WHERE translation_id=t.id AND block_id=b.block_id))
     WHEN 'SPECIFICATIONS' THEN jsonb_build_object('items',(SELECT jsonb_agg(public.publication_pick_fields(to_jsonb(i.*),ARRAY['itemId','label','value']) ORDER BY i.item_id) FROM public.gift_detail_translation_items i WHERE translation_id=t.id AND block_id=b.block_id))
     ELSE public.publication_pick_fields(to_jsonb(b.*),ARRAY['mediaMetadataRevisionId','caption']) END ORDER BY b.block_id)
   INTO translated_blocks FROM public.gift_detail_translation_blocks b WHERE translation_id=t.id;
   expected:=public.publication_pick_fields(to_jsonb(t.*),ARRAY['schemaVersion','id','documentId','giftRevisionId','locale','sourceHash','translatedFromSourceHash','origin','importBatchId','editorId'])
     ||jsonb_build_object('editedAt',public.publication_utc(t.edited_at),'review',public.publication_approved_review(r,true),'blocks',translated_blocks);
   translations:=translations||jsonb_build_array(expected);
   text_translations:=text_translations||jsonb_build_array(public.publication_pick_fields(to_jsonb(t.*),ARRAY['locale','origin','importBatchId'])||jsonb_build_object('blocks',translated_blocks));
 END LOOP;
 expected:=jsonb_build_object('schemaVersion',1,'outcome','SUCCESS','document',jsonb_build_object('schemaVersion',1,'id',d.id,'giftRevisionId',revision,'blocks',blocks));
 IF (value#>'{extensions,details}')-'translations' IS DISTINCT FROM expected OR NOT public.publication_same_set(value#>'{extensions,details,translations}',translations)
   OR value#>'{content,details,blocks}' IS DISTINCT FROM blocks OR NOT public.publication_same_set(value#>'{content,details,translations}',text_translations) THEN
   RAISE EXCEPTION 'manifest must retain all actual detail structure and raw translations' USING ERRCODE='23514';
 END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_publication_manifest_media(value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE assets uuid[]; metadata uuid[]; declared uuid[]; row_value jsonb; asset public.media_assets%ROWTYPE; variant public.media_variants%ROWTYPE; lineage jsonb; proof jsonb; source public.media_assets%ROWTYPE;
 job public.media_processing_jobs%ROWTYPE; output public.media_processing_outputs%ROWTYPE; expected jsonb; expected_command jsonb; existing_ids uuid[]:='{}'; job_ids uuid[]; metadata_row public.media_metadata_revisions%ROWTYPE; hero_pair record;
BEGIN
 IF jsonb_typeof(value#>'{media,assets}') IS DISTINCT FROM 'array' OR jsonb_typeof(value#>'{media,variants}') IS DISTINCT FROM 'array' OR jsonb_typeof(value#>'{media,lineage}') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'manifest media proof must have typed collections' USING ERRCODE='23514'; END IF;
 SELECT coalesce(array_agg(DISTINCT asset_id ORDER BY asset_id),'{}'),coalesce(array_agg(DISTINCT metadata_id ORDER BY metadata_id) FILTER(WHERE metadata_id<>(value#>>'{revision,revisionId}')::uuid),'{}') INTO assets,metadata FROM public.publication_media_references(value->'revision');
 SELECT coalesce(array_agg((item->>'id')::uuid ORDER BY (item->>'id')::uuid),'{}') INTO declared FROM jsonb_array_elements(value#>'{media,assets}') item;
 IF declared IS DISTINCT FROM assets THEN RAISE EXCEPTION 'manifest must contain all and only referenced binary identities' USING ERRCODE='23514'; END IF;
 SELECT coalesce(array_agg((item->>'revisionId')::uuid ORDER BY (item->>'revisionId')::uuid),'{}') INTO declared FROM jsonb_array_elements(value->'mediaRevisions') item;
 IF declared IS DISTINCT FROM metadata THEN RAISE EXCEPTION 'manifest must contain all and only actual metadata dependencies' USING ERRCODE='23514'; END IF;
 SELECT coalesce(array_agg((item->>'assetId')::uuid ORDER BY (item->>'assetId')::uuid),'{}') INTO declared FROM jsonb_array_elements(value#>'{media,lineage}') item;
 IF declared IS DISTINCT FROM assets THEN RAISE EXCEPTION 'manifest lineage must cover each referenced asset exactly once' USING ERRCODE='23514'; END IF;
 FOR metadata_row IN SELECT * FROM public.media_metadata_revisions WHERE id=ANY(metadata) FOR SHARE LOOP
  IF metadata_row.lifecycle NOT IN ('PUBLISHED','SUPERSEDED') OR NOT EXISTS(SELECT 1 FROM public.content_publications WHERE media_metadata_revision_id=metadata_row.id AND media_asset_id=metadata_row.media_asset_id) THEN RAISE EXCEPTION 'referenced metadata requires a real publication ledger event' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR row_value IN SELECT * FROM jsonb_array_elements(value#>'{media,assets}') LOOP
  SELECT * INTO asset FROM public.media_assets WHERE id=(row_value->>'id')::uuid FOR SHARE;
  IF asset.id IS NULL OR asset.processing_status<>'READY' OR asset.rights_status<>'APPROVED' OR row_value IS DISTINCT FROM public.publication_asset(to_jsonb(asset)) THEN RAISE EXCEPTION 'manifest requires exact currently eligible immutable binary identity' USING ERRCODE='23514'; END IF;
  SELECT item INTO lineage FROM jsonb_array_elements(value#>'{media,lineage}') item WHERE (item->>'assetId')::uuid=asset.id;
  IF lineage->>'identityKind' IS DISTINCT FROM asset.identity_kind OR jsonb_typeof(lineage->'processing') IS DISTINCT FROM 'array'
    OR (asset.identity_kind='SOURCE' AND jsonb_array_length(lineage->'processing')<>0)
    OR (asset.identity_kind='PROCESSED_MASTER' AND jsonb_array_length(lineage->'processing')=0) THEN RAISE EXCEPTION 'manifest processing lineage must match actual binary purpose' USING ERRCODE='23514'; END IF;
  -- Every currently recorded original remains relevant even when reusing an older immutable proof subset.
  FOR job IN SELECT * FROM public.media_processing_jobs WHERE output_asset_id=asset.id ORDER BY id FOR SHARE LOOP
    SELECT * INTO source FROM public.media_assets WHERE id=job.source_asset_id FOR SHARE;
    IF job.status<>'SUCCEEDED' OR source.identity_kind<>'SOURCE' OR source.rights_status<>'APPROVED' OR source.processing_status='ARCHIVED' THEN RAISE EXCEPTION 'all current processing originals must remain eligible' USING ERRCODE='23514'; END IF;
  END LOOP;
  job_ids:='{}';
  FOR proof IN SELECT * FROM jsonb_array_elements(lineage->'processing') LOOP
   IF (proof->>'jobId')::uuid=ANY(job_ids) THEN RAISE EXCEPTION 'processing evidence identities cannot repeat' USING ERRCODE='23514'; END IF;
   job_ids:=array_append(job_ids,(proof->>'jobId')::uuid);
   SELECT * INTO job FROM public.media_processing_jobs WHERE id=(proof->>'jobId')::uuid AND output_asset_id=asset.id FOR SHARE;
   SELECT * INTO source FROM public.media_assets WHERE id=job.source_asset_id FOR SHARE;
   SELECT * INTO output FROM public.media_processing_outputs WHERE job_id=job.id AND kind='MASTER';
   expected_command:=jsonb_build_object('schemaVersion',1,'profileVersion',job.profile_version,'source',jsonb_build_object('assetId',source.id,'metadataRevisionId',job.source_metadata_revision_id,'checksumSha256',job.source_checksum_sha256,'objectKey',source.object_key,'mimeType',source.mime_type,'byteSize',source.byte_size,'width',source.width,'height',source.height),'role',job.role,'fit',job.fit,'focalPoint',jsonb_build_object('x',job.focal_x,'y',job.focal_y));
   expected:=jsonb_build_object('jobId',job.id,'command',expected_command,'commandHash',job.command_hash,'sourceAsset',public.publication_asset(to_jsonb(source)),'sourceIdentityKind',source.identity_kind,'outputAssetId',job.output_asset_id,'output',public.publication_pick_fields(to_jsonb(output),ARRAY['mediaAssetId','checksumSha256','objectKey','width','height','byteSize']));
   IF job.id IS NULL OR job.status<>'SUCCEEDED' OR output.job_id IS NULL OR proof IS DISTINCT FROM expected THEN RAISE EXCEPTION 'manifest processing proof requires exact immutable command and output rows' USING ERRCODE='23514'; END IF;
  END LOOP;
 END LOOP;
 FOR row_value IN SELECT * FROM jsonb_array_elements(value#>'{media,variants}') LOOP
  SELECT * INTO variant FROM public.media_variants WHERE id=(row_value->>'id')::uuid FOR SHARE;
  IF variant.id=ANY(existing_ids) THEN RAISE EXCEPTION 'manifest variants cannot repeat' USING ERRCODE='23514'; END IF;
  existing_ids:=array_append(existing_ids,variant.id);
  IF variant.id IS NULL OR NOT variant.media_asset_id=ANY(assets) OR variant.status<>'READY'
    OR row_value IS DISTINCT FROM public.publication_pick_fields(to_jsonb(variant),ARRAY['schemaVersion','id','mediaAssetId','format','width','height','byteSize','checksumSha256','objectKey']) THEN RAISE EXCEPTION 'manifest variants require exact eligible immutable rows' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR hero_pair IN
   SELECT d.media_asset_id AS desktop,m.media_asset_id AS mobile FROM public.idol_revision_media d JOIN public.idol_revision_media m ON m.idol_revision_id=d.idol_revision_id
     WHERE value#>>'{revision,target,kind}'='IDOL' AND d.idol_revision_id=(value#>>'{revision,revisionId}')::uuid AND d.role='HERO_DESKTOP' AND m.role='HERO_MOBILE'
   UNION ALL SELECT h.desktop_media_asset_id,h.mobile_media_asset_id FROM public.homepage_slots h
     WHERE value#>>'{revision,target,kind}'='HOMEPAGE' AND h.homepage_revision_id=(value#>>'{revision,revisionId}')::uuid AND h.kind='HERO_IDOL'
 LOOP PERFORM public.assert_publication_hero_originals(hero_pair.desktop,hero_pair.mobile); END LOOP;
 IF EXISTS(SELECT 1 FROM unnest(assets) id WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value#>'{media,variants}') item WHERE (item->>'mediaAssetId')::uuid=id)) THEN RAISE EXCEPTION 'each published asset requires a recorded ready variant' USING ERRCODE='23514'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_publication_manifest_revision(value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE kind text:=value#>>'{target,kind}'; revision_id uuid:=(value->>'revisionId')::uuid; prefix text; parent_column text; translation_column text;
  parent jsonb; translation jsonb; review jsonb; evidence jsonb; source_parent uuid; text_row jsonb; audit_row jsonb; expected jsonb; fields text[]; actual_count integer; locales text[]:='{}'; english_hash text;
BEGIN
  IF kind IS NULL OR kind NOT IN ('IDOL','GIFT','HOMEPAGE','POLICY','MEDIA_METADATA')
    OR jsonb_typeof(value) IS DISTINCT FROM 'object' OR jsonb_typeof(value->'content') IS DISTINCT FROM 'object'
    OR jsonb_typeof(value#>'{content,translations}') IS DISTINCT FROM 'array' OR jsonb_typeof(value->'translationAudits') IS DISTINCT FROM 'array'
    OR jsonb_typeof(value->'extensions') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'manifest revision kind and proof shape must be typed' USING ERRCODE='23514'; END IF;
  prefix:=lower(kind); parent_column:=prefix||'_revision_id'; translation_column:=prefix||'_translation_id';
  EXECUTE format('SELECT to_jsonb(p.*) FROM public.%I p WHERE p.id=$1 FOR UPDATE',prefix||'_revisions') INTO parent USING revision_id;
  IF parent IS NULL OR value->>'schemaVersion' IS DISTINCT FROM '1' OR value#>>'{content,kind}' IS DISTINCT FROM kind OR (value->>'revisionNumber')::bigint IS DISTINCT FROM (parent->>'revision')::bigint
    OR (value->>'createdBy')::uuid IS DISTINCT FROM (parent->>'created_by')::uuid OR (value->>'createdAt')::timestamptz IS DISTINCT FROM (parent->>'created_at')::timestamptz THEN
    RAISE EXCEPTION 'manifest revision requires its exact immutable parent' USING ERRCODE='23514';
  END IF;
  IF (kind='IDOL' AND (value#>>'{target,idolId}')::uuid IS DISTINCT FROM (parent->>'idol_id')::uuid)
    OR (kind='GIFT' AND (value#>>'{target,giftId}')::uuid IS DISTINCT FROM (parent->>'gift_id')::uuid)
    OR (kind='POLICY' AND value#>>'{target,policyKey}' IS DISTINCT FROM parent->>'policy_key')
    OR (kind='MEDIA_METADATA' AND (value#>>'{target,mediaAssetId}')::uuid IS DISTINCT FROM (parent->>'media_asset_id')::uuid) THEN
    RAISE EXCEPTION 'manifest revision requires its exact owner' USING ERRCODE='23514';
  END IF;
  fields:=CASE kind WHEN 'IDOL' THEN ARRAY['displayName','shortBio','fullBio','seoTitle','seoDescription']
    WHEN 'GIFT' THEN ARRAY['title','subtitle','shortDescription','description','fulfillmentDescription','safetyNotice','seoTitle','seoDescription']
    WHEN 'HOMEPAGE' THEN ARRAY['heroTitle','heroSubtitle','ctaLabel','announcement','seoTitle','seoDescription']
    WHEN 'POLICY' THEN ARRAY['title','summary','body'] ELSE ARRAY['alt','title','caption'] END;
  EXECUTE format('SELECT count(*),max(source_hash) FILTER(WHERE locale=''en'') FROM public.%I WHERE %I=$1',prefix||'_revision_translations',parent_column) INTO actual_count,english_hash USING revision_id;
  IF actual_count<>7 OR jsonb_array_length(value#>'{content,translations}') IS DISTINCT FROM 7 OR jsonb_array_length(value->'translationAudits') IS DISTINCT FROM 7 THEN
    RAISE EXCEPTION 'manifest revision requires seven real translations and approvals' USING ERRCODE='23514';
  END IF;
  FOR text_row IN SELECT * FROM jsonb_array_elements(value#>'{content,translations}') LOOP
    IF text_row->>'locale'=ANY(locales) THEN RAISE EXCEPTION 'manifest locale must occur once' USING ERRCODE='23514'; END IF;
    locales:=array_append(locales,text_row->>'locale');
    EXECUTE format('SELECT to_jsonb(t.*),to_jsonb(r.*),to_jsonb(e.*) FROM public.%I t JOIN LATERAL(SELECT * FROM public.%I WHERE %I=t.id ORDER BY sequence DESC LIMIT 1) r ON true LEFT JOIN public.%I e ON e.target_translation_id=t.id WHERE t.%I=$1 AND t.locale=$2 FOR UPDATE OF t',prefix||'_revision_translations',prefix||'_translation_reviews',translation_column,prefix||'_translation_copy_evidence',parent_column)
      INTO translation,review,evidence USING revision_id,text_row->>'locale';
    SELECT item INTO audit_row FROM jsonb_array_elements(value->'translationAudits') item WHERE item->>'locale'=text_row->>'locale';
    IF translation IS NULL OR audit_row IS NULL OR review->>'status' IS DISTINCT FROM 'APPROVED' OR review->>'sequence' IS DISTINCT FROM '3'
      OR text_row->>'origin' IS DISTINCT FROM translation->>'origin' OR text_row->>'importBatchId' IS DISTINCT FROM translation->>'import_batch_id'
      OR (audit_row->>'id')::uuid IS DISTINCT FROM (translation->>'id')::uuid OR (audit_row->>'reviewId')::uuid IS DISTINCT FROM (review->>'id')::uuid OR audit_row->>'reviewSequence' IS DISTINCT FROM '3'
      OR audit_row->>'sourceHash' IS DISTINCT FROM translation->>'source_hash' OR audit_row->>'translatedFromSourceHash' IS DISTINCT FROM english_hash
      OR translation->>'translated_from_source_hash' IS DISTINCT FROM english_hash OR audit_row->>'origin' IS DISTINCT FROM translation->>'origin'
      OR audit_row->>'importBatchId' IS DISTINCT FROM translation->>'import_batch_id' OR (audit_row->>'editorId')::uuid IS DISTINCT FROM (translation->>'editor_id')::uuid
      OR (audit_row->>'editedAt')::timestamptz IS DISTINCT FROM (translation->>'edited_at')::timestamptz
      OR audit_row#>>'{review,status}' IS DISTINCT FROM 'APPROVED' OR (audit_row#>>'{review,reviewerId}')::uuid IS DISTINCT FROM (review->>'reviewer_id')::uuid
      OR (audit_row#>>'{review,reviewedAt}')::timestamptz IS DISTINCT FROM (review->>'reviewed_at')::timestamptz
      OR audit_row#>>'{review,reviewedSourceHash}' IS DISTINCT FROM review->>'reviewed_source_hash'
      OR audit_row#>>'{review,reviewedContentHash}' IS DISTINCT FROM review->>'reviewed_content_hash'
      OR review->>'reviewed_source_hash' IS DISTINCT FROM english_hash OR review->>'reviewed_content_hash' IS DISTINCT FROM translation->>'source_hash'
      OR (review->>'reviewer_id')::uuid=(translation->>'editor_id')::uuid THEN
      RAISE EXCEPTION 'manifest must bind exact current independent approved translation evidence' USING ERRCODE='23514';
    END IF;
    expected:=public.publication_pick_fields(translation,fields);
    IF (text_row->'fields')-ARRAY['variantLabels','slotLabels'] IS DISTINCT FROM expected THEN RAISE EXCEPTION 'manifest translation fields must equal real raw content' USING ERRCODE='23514'; END IF;
    IF kind='GIFT' THEN
      SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['giftVariantId','label'])),'[]') INTO expected FROM public.gift_variant_labels r WHERE gift_translation_id=(translation->>'id')::uuid;
      IF NOT public.publication_same_set(text_row#>'{fields,variantLabels}',expected) THEN RAISE EXCEPTION 'manifest variant labels require real content' USING ERRCODE='23514'; END IF;
    ELSIF kind='HOMEPAGE' THEN
      SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['slotKey','label'])),'[]') INTO expected FROM public.homepage_slot_translations r WHERE homepage_translation_id=(translation->>'id')::uuid;
      IF NOT public.publication_same_set(text_row#>'{fields,slotLabels}',expected) THEN RAISE EXCEPTION 'manifest slot labels require real content' USING ERRCODE='23514'; END IF;
    END IF;
    IF evidence IS NULL THEN
      IF audit_row ? 'inheritedFrom' OR (review->>'reviewer_id')::uuid=(parent->>'created_by')::uuid THEN RAISE EXCEPTION 'direct approval cannot inherit structure independence' USING ERRCODE='23514'; END IF;
    ELSE
      EXECUTE format('SELECT %I FROM public.%I WHERE id=$1',parent_column,prefix||'_revision_translations') INTO source_parent USING (evidence->>'source_translation_id')::uuid;
      IF (audit_row#>>'{inheritedFrom,revisionId}')::uuid IS DISTINCT FROM source_parent
        OR (audit_row#>>'{inheritedFrom,translationId}')::uuid IS DISTINCT FROM (evidence->>'source_translation_id')::uuid
        OR (audit_row#>>'{inheritedFrom,reviewId}')::uuid IS DISTINCT FROM (evidence->>'source_approval_review_id')::uuid THEN
        RAISE EXCEPTION 'inherited approval requires exact typed source edge' USING ERRCODE='23514';
      END IF;
    END IF;
  END LOOP;
  IF kind='IDOL' THEN
    expected:=public.publication_pick_fields(parent,ARRAY['themeAccent','heroTextTone','displayOrder']);
  ELSIF kind='GIFT' THEN
    SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['componentCode','quantity','unit'])),'[]') INTO expected FROM public.gift_revision_contents r WHERE gift_revision_id=revision_id;
    IF NOT public.publication_same_set(value#>'{content,structure,contents}',expected) THEN RAISE EXCEPTION 'manifest gift contents require exact rows' USING ERRCODE='23514'; END IF;
    expected:=public.publication_pick_fields(parent,ARRAY['category','requiresSafetyNotice','shippingMode'])||jsonb_build_object('deliveryEstimate',jsonb_build_object('minimum',parent->'delivery_minimum','maximum',parent->'delivery_maximum','unit',parent->'delivery_unit'));
    IF (value#>'{content,structure}')-'contents' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'manifest gift structure requires exact parent' USING ERRCODE='23514'; END IF;
  ELSIF kind='HOMEPAGE' THEN
    SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['slotKey','kind','idolId','giftId','policyKey','desktopMediaAssetId','desktopMediaMetadataRevisionId','mobileMediaAssetId','mobileMediaMetadataRevisionId','sortOrder'])),'[]') INTO expected FROM public.homepage_slots r WHERE homepage_revision_id=revision_id;
    IF NOT public.publication_same_set(value#>'{content,structure,slots}',expected) THEN RAISE EXCEPTION 'manifest homepage slots require exact rows' USING ERRCODE='23514'; END IF;
  ELSIF kind='POLICY' THEN
    IF value#>>'{content,structure,kind}' IS DISTINCT FROM parent->>'kind' OR (value#>>'{content,structure,effectiveAt}')::timestamptz IS DISTINCT FROM (parent->>'effective_at')::timestamptz THEN RAISE EXCEPTION 'manifest policy structure requires exact parent' USING ERRCODE='23514'; END IF;
  ELSE expected:=jsonb_build_object('presentationKind',parent->'presentation_kind','focalPoint',jsonb_build_object('x',parent->'focal_x','y',parent->'focal_y'));
  END IF;
  IF kind IN ('IDOL','MEDIA_METADATA') AND value#>'{content,structure}' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'manifest structure requires exact parent values' USING ERRCODE='23514'; END IF;
  PERFORM public.assert_publication_manifest_extensions(value);
  IF kind IN ('IDOL','GIFT') THEN
    EXECUTE format('SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY[''role'',''mediaAssetId'',''mediaMetadataRevisionId'',''sortOrder''])),''[]'') FROM public.%I r WHERE %I=$1',prefix||'_revision_media',parent_column) INTO expected USING revision_id;
    IF NOT public.publication_same_set(value#>'{content,media}',expected) THEN RAISE EXCEPTION 'manifest media references require exact typed rows' USING ERRCODE='23514'; END IF;
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_publication_receipt_snapshot_hash()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE proof public.content_publication_manifests%ROWTYPE; parent jsonb; before_state jsonb; after_state jsonb; kind text;
BEGIN
  IF NEW.action='RETRY_PURGE' THEN RETURN NULL; END IF;
  SELECT * INTO proof FROM public.content_publication_manifests WHERE id=NEW.manifest_id;
  kind:=proof.manifest#>>'{target,owner,kind}';
  IF proof.id IS NULL OR kind IS NULL THEN RAISE EXCEPTION 'snapshot hash requires its real manifest revision' USING ERRCODE='23514'; END IF;
  EXECUTE format('SELECT to_jsonb(r.*) FROM public.%I r WHERE id=$1',lower(kind)||'_revisions') INTO parent USING (proof.manifest#>>'{target,revisionId}')::uuid;
  after_state:=jsonb_build_object('status',parent->'lifecycle')||public.publication_pick_fields(parent,ARRAY['validatedAt','publishedAt','supersededAt','archivedAt']);
  before_state:=CASE NEW.action WHEN 'VALIDATE' THEN jsonb_build_object('status','DRAFT')
    WHEN 'PUBLISH' THEN jsonb_build_object('status','VALIDATED','validatedAt',parent->'validated_at') ELSE after_state END;
  IF NEW.expected_content_hash IS DISTINCT FROM public.publication_snapshot_hash(proof.manifest->'revision',before_state)
    OR NEW.result_content_hash IS DISTINCT FROM public.publication_snapshot_hash(proof.manifest->'revision',after_state) THEN
    RAISE EXCEPTION 'publication receipt hashes require exact canonical content and lifecycle states' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_refund_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_refund_id uuid;
  expected_amount minor_amount;
  allocated_amount numeric;
  allocation_count integer;
BEGIN
  target_refund_id := COALESCE(
    (to_jsonb(NEW) ->> 'refund_id')::uuid,
    (to_jsonb(OLD) ->> 'refund_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid,
    (to_jsonb(OLD) ->> 'id')::uuid
  );
  SELECT requested_amount_minor INTO expected_amount FROM refunds WHERE id = target_refund_id;
  IF expected_amount IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT count(*), COALESCE(sum(amount_minor), 0)
    INTO allocation_count, allocated_amount
    FROM refund_items WHERE refund_id = target_refund_id;
  IF allocation_count = 0 OR allocated_amount <> expected_amount THEN
    RAISE EXCEPTION 'refund allocations must be non-empty and sum exactly to requested amount'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_refund_item_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_item_id uuid := (to_jsonb(NEW) ->> 'order_item_id')::uuid;
  target_refund_id uuid := COALESCE(
    (to_jsonb(NEW) ->> 'refund_id')::uuid,
    (to_jsonb(NEW) ->> 'id')::uuid
  );
  item_row record;
  item_total minor_amount;
  occupied_total numeric;
BEGIN
  FOR item_row IN
    SELECT DISTINCT item.order_item_id
    FROM public.refund_items item
    WHERE (target_order_item_id IS NOT NULL AND item.order_item_id = target_order_item_id)
       OR (target_order_item_id IS NULL AND item.refund_id = target_refund_id)
  LOOP
    SELECT line_total_minor INTO item_total
      FROM public.order_items
      WHERE id = item_row.order_item_id;
    SELECT COALESCE(sum(item.amount_minor), 0) INTO occupied_total
      FROM public.refund_items item
      JOIN public.refunds refund ON refund.id = item.refund_id
      WHERE item.order_item_id = item_row.order_item_id
        AND refund.status <> 'FAILED';
    IF item_total IS NULL OR occupied_total > item_total THEN
      RAISE EXCEPTION 'refund allocation exceeds order-item total'
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_resource_management_audit(audit_id uuid, actor uuid, session_id uuid, expected_action text, expected_subject text, subject uuid, event_time timestamp with time zone, causal_lower_bound timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE evidence public.audit_logs%ROWTYPE; session public.admin_sessions%ROWTYPE; identity_status text; required_permission text;
BEGIN
  SELECT * INTO evidence FROM public.audit_logs WHERE id=audit_id;
  SELECT * INTO session FROM public.admin_sessions WHERE id=session_id FOR SHARE;
  SELECT status INTO identity_status FROM public.admin_identities WHERE id=actor FOR SHARE;
  IF evidence.id IS NULL OR evidence.actor_type<>'ADMIN' OR evidence.actor_id IS DISTINCT FROM actor OR evidence.action<>expected_action
    OR evidence.subject_type<>expected_subject OR evidence.subject_id<>subject OR evidence.outcome<>'SUCCEEDED'
    OR evidence.created_at<>event_time OR evidence.reason_code IS NULL OR evidence.request_id IS NULL OR evidence.correlation_id IS NULL
    OR evidence.field_category IS DISTINCT FROM 'RESOURCE_MANAGEMENT' THEN
    RAISE EXCEPTION 'resource operation requires its exact audit' USING ERRCODE='23514';
  END IF;
  IF session.id IS NULL OR session.admin_identity_id<>actor OR identity_status IS DISTINCT FROM 'ACTIVE'
    OR NOT session.authenticated_with_mfa OR session.revoked_at IS NOT NULL OR session.expires_at<=clock_timestamp()
    OR session.created_at>clock_timestamp() OR event_time<session.created_at
    OR event_time>GREATEST(clock_timestamp(),transaction_timestamp(),session.created_at,causal_lower_bound) THEN
    RAISE EXCEPTION 'resource operation requires its active MFA actor session' USING ERRCODE='23514';
  END IF;
  required_permission:=CASE expected_action WHEN 'POLICY_REGISTER' THEN 'content.policy.manage'
    WHEN 'MEDIA_UPLOAD_BEGIN' THEN 'content.media.upload' WHEN 'MEDIA_UPLOAD_REGISTER' THEN 'content.media.upload'
    WHEN 'MEDIA_RIGHTS_SET' THEN 'content.media.rights' WHEN 'MEDIA_PROCESSING_ENQUEUE' THEN 'content.media.process'
    WHEN 'MEDIA_PROCESSING_RETRY' THEN 'content.media.process' END;
  PERFORM ar.role_id FROM public.admin_identity_roles ar JOIN public.roles r ON r.id=ar.role_id
    JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id
    WHERE ar.admin_identity_id=actor AND p.permission_key=required_permission
      AND ar.granted_at<=clock_timestamp() AND rp.granted_at<=clock_timestamp()
      AND ar.granted_at<=event_time AND rp.granted_at<=event_time FOR SHARE OF ar,r,rp,p;
  IF NOT FOUND THEN RAISE EXCEPTION 'resource operation requires its current specific permission' USING ERRCODE='23514'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_translation_export_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE prefix text; parent_column text; owner_column text; source_id uuid; parent jsonb; actual_head bigint; english_hash text; audit public.audit_logs%ROWTYPE; ordered public.supported_locale[];
BEGIN
 prefix:=CASE WHEN NEW.idol_revision_id IS NOT NULL THEN 'idol' WHEN NEW.gift_revision_id IS NOT NULL THEN 'gift' WHEN NEW.homepage_revision_id IS NOT NULL THEN 'homepage' WHEN NEW.policy_revision_id IS NOT NULL THEN 'policy' ELSE 'media_metadata' END;
 parent_column:=prefix||'_revision_id'; owner_column:=CASE prefix WHEN 'homepage' THEN NULL WHEN 'policy' THEN 'policy_key' WHEN 'media_metadata' THEN 'media_asset_id' ELSE prefix||'_id' END;
 source_id:=coalesce(NEW.idol_revision_id,NEW.gift_revision_id,NEW.homepage_revision_id,NEW.policy_revision_id,NEW.media_metadata_revision_id);
 EXECUTE format('SELECT to_jsonb(r.*) FROM public.%I r WHERE id=$1 FOR UPDATE',prefix||'_revisions') INTO parent USING source_id;
 IF parent->>'lifecycle'='DRAFT' AND NOT public.content_authoring_revision_sealed(parent_column,source_id) THEN RAISE EXCEPTION 'mutable legacy draft must be copied before translation export' USING ERRCODE='23514'; END IF;
 IF owner_column IS NULL THEN EXECUTE 'SELECT max(revision) FROM public.homepage_revisions' INTO actual_head;
 ELSE EXECUTE format('SELECT max(revision) FROM public.%I r WHERE to_jsonb(r.*)->>%L=$1',prefix||'_revisions',owner_column) INTO actual_head USING parent->>owner_column; END IF;
 EXECUTE format('SELECT source_hash FROM public.%I WHERE %I=$1 AND locale=''en''',prefix||'_revision_translations',parent_column) INTO english_hash USING source_id;
 SELECT array_agg(locale ORDER BY locale) INTO ordered FROM(SELECT DISTINCT unnest(NEW.locales) locale) q;
 IF parent IS NULL OR actual_head IS DISTINCT FROM NEW.expected_authoring_version OR english_hash IS DISTINCT FROM NEW.english_source_hash OR NEW.locales IS DISTINCT FROM ordered OR NEW.created_at<(parent->>'created_at')::timestamptz THEN RAISE EXCEPTION 'translation export requires exact source revision head English hash and locale set' USING ERRCODE='23514'; END IF;
 SELECT * INTO audit FROM public.audit_logs WHERE id=NEW.audit_log_id;
 IF audit.id IS NULL OR audit.actor_type IS DISTINCT FROM 'ADMIN' OR audit.actor_id IS DISTINCT FROM NEW.actor_id OR audit.action IS DISTINCT FROM 'TRANSLATION_EXPORT' OR audit.subject_type IS DISTINCT FROM 'TRANSLATION_EXPORT_PACKAGE' OR audit.subject_id IS DISTINCT FROM NEW.id OR audit.created_at IS DISTINCT FROM NEW.created_at OR audit.outcome IS DISTINCT FROM 'SUCCEEDED' OR audit.reason_code IS NULL OR audit.request_id IS NULL OR audit.correlation_id IS DISTINCT FROM audit.request_id THEN RAISE EXCEPTION 'translation export requires exact audit evidence' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_admin_catalog_authority(NEW.actor_id,NEW.session_id,NEW.created_at,(parent->>'created_at')::timestamptz,'content.read',NEW.locales);
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_translation_import_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE exported public.translation_export_receipts%ROWTYPE; authored public.content_authoring_receipts%ROWTYPE; audit public.audit_logs%ROWTYPE; prefix text; parent_column text; translation_column text; source_id uuid; target_id uuid; imported integer;
BEGIN
 SELECT * INTO exported FROM public.translation_export_receipts WHERE id=NEW.export_receipt_id;
 SELECT * INTO authored FROM public.content_authoring_receipts WHERE id=NEW.authoring_receipt_id;
 SELECT * INTO audit FROM public.audit_logs WHERE id=NEW.audit_log_id;
 prefix:=CASE WHEN exported.idol_revision_id IS NOT NULL THEN 'idol' WHEN exported.gift_revision_id IS NOT NULL THEN 'gift' WHEN exported.homepage_revision_id IS NOT NULL THEN 'homepage' WHEN exported.policy_revision_id IS NOT NULL THEN 'policy' ELSE 'media_metadata' END;
 parent_column:=prefix||'_revision_id'; translation_column:=prefix||'_translation_id'; source_id:=(to_jsonb(exported)->>parent_column)::uuid; target_id:=(to_jsonb(authored)->>parent_column)::uuid;
 IF exported.id IS NULL OR authored.id IS NULL OR authored.action IS DISTINCT FROM 'COPY' OR (to_jsonb(authored)->>('source_'||parent_column))::uuid IS DISTINCT FROM source_id OR target_id IS NULL OR target_id=source_id
 OR authored.expected_version IS DISTINCT FROM exported.expected_authoring_version OR authored.source_snapshot_hash IS DISTINCT FROM exported.source_snapshot_hash OR authored.actor_id IS DISTINCT FROM NEW.actor_id OR authored.audit_log_id IS DISTINCT FROM NEW.audit_log_id OR authored.created_at IS DISTINCT FROM NEW.created_at OR NEW.imported_locales IS DISTINCT FROM exported.locales
 OR audit.action IS DISTINCT FROM 'CONTENT_REVISION_COPY' OR audit.actor_id IS DISTINCT FROM NEW.actor_id OR audit.subject_id IS DISTINCT FROM target_id OR audit.created_at IS DISTINCT FROM NEW.created_at OR audit.outcome IS DISTINCT FROM 'SUCCEEDED' THEN RAISE EXCEPTION 'translation import requires exact exported source and new COPY audit' USING ERRCODE='23514'; END IF;
 EXECUTE format('SELECT count(*) FROM public.%I t JOIN public.%I r ON r.%I=t.id AND r.sequence=1 WHERE t.%I=$1 AND t.locale=ANY($2) AND t.origin=''IMPORT'' AND t.import_batch_id=$3 AND t.editor_id=$4 AND r.status=''DRAFT'' AND NOT EXISTS(SELECT 1 FROM public.%I later WHERE later.%I=t.id AND later.sequence>1)',prefix||'_revision_translations',prefix||'_translation_reviews',translation_column,parent_column,prefix||'_translation_reviews',translation_column) INTO imported USING target_id,NEW.imported_locales,NEW.id,NEW.actor_id;
 IF imported<>cardinality(NEW.imported_locales) THEN RAISE EXCEPTION 'imported translations must remain new actor IMPORT drafts with exact batch' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_admin_catalog_authority(NEW.actor_id,NEW.session_id,NEW.created_at,authored.created_at,'content.edit',NEW.imported_locales);
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.assert_translation_initial_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  review_count integer;
BEGIN
  EXECUTE format(
    'SELECT count(*) FROM %s WHERE %I = $1 AND sequence = 1 AND status = ''DRAFT''',
    TG_ARGV[0]::regclass,
    TG_ARGV[1]
  ) INTO review_count USING NEW.id;
  IF review_count <> 1 THEN
    RAISE EXCEPTION 'translation creation requires one initial DRAFT review event'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_translation_package(translation_table regclass, parent_column text, parent_id uuid, review_table regclass, review_translation_column text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  english_hash sha256_hex;
  translation_count integer;
  approved_count integer;
  lineage_count integer;
BEGIN
  EXECUTE format(
    'SELECT source_hash FROM %s WHERE %I = $1 AND locale = ''en''',
    translation_table,
    parent_column
  ) INTO english_hash USING parent_id;

  IF english_hash IS NULL THEN
    RAISE EXCEPTION 'publication requires an English translation row'
      USING ERRCODE = '23514';
  END IF;

  EXECUTE format(
    'SELECT count(*), '
    'count(*) FILTER (WHERE latest.status = ''APPROVED''), '
    'count(*) FILTER (WHERE t.translated_from_source_hash = $2) '
    'FROM %s t '
    'LEFT JOIN LATERAL ('
    '  SELECT r.status FROM %s r '
    '  WHERE r.%I = t.id ORDER BY r.sequence DESC LIMIT 1'
    ') latest ON true '
    'WHERE t.%I = $1',
    translation_table,
    review_table,
    review_translation_column,
    parent_column
  ) INTO translation_count, approved_count, lineage_count
    USING parent_id, english_hash;

  IF translation_count <> 7 OR approved_count <> 7 OR lineage_count <> 7 THEN
    RAISE EXCEPTION 'publication requires seven approved translations with current English lineage'
      USING ERRCODE = '23514';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.block_content_extension_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE idol_revision uuid; gift_revision uuid;
BEGIN
  IF TG_TABLE_NAME='idol_revisions' THEN IF NEW.lifecycle='DRAFT' THEN RETURN NEW; END IF; idol_revision:=NEW.id;
  ELSIF TG_TABLE_NAME='gift_revisions' THEN IF NEW.lifecycle='DRAFT' THEN RETURN NEW; END IF; gift_revision:=NEW.id;
  ELSE idol_revision:=NEW.idol_revision_id; gift_revision:=NEW.gift_revision_id; END IF;
  IF (EXISTS(SELECT 1 FROM public.idol_revision_alias_sets WHERE idol_revision_id=idol_revision) OR EXISTS(SELECT 1 FROM public.gift_detail_documents WHERE gift_revision_id=gift_revision))
    AND NOT EXISTS(SELECT 1 FROM public.content_publication_manifests WHERE idol_revision_id=idol_revision OR gift_revision_id=gift_revision) THEN
    RAISE EXCEPTION 'content extension publication requires complete immutable proof' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.canonical_publication_json(value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE result text;
BEGIN
  IF jsonb_typeof(value)='object' THEN
    SELECT '{'||coalesce(string_agg(to_json(key)::text||':'||public.canonical_publication_json(child),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(value) AS entry(key,child);
  ELSIF jsonb_typeof(value)='array' THEN
    SELECT '['||coalesce(string_agg(public.canonical_publication_json(child),',' ORDER BY position),'')||']' INTO result FROM jsonb_array_elements(value) WITH ORDINALITY AS entry(child,position);
  ELSE result:=value::text;
  END IF;
  RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.checkout_source_document(ref jsonb, kind text, owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE p public.content_publications%ROWTYPE; manifest jsonb; digest text; revision jsonb; audit jsonb; fields jsonb; owner_key text;
BEGIN
  SELECT * INTO p FROM public.content_publications WHERE id=(ref->>'publicationId')::uuid;
  owner_key:=CASE kind WHEN 'IDOL' THEN 'idolId' WHEN 'GIFT' THEN 'giftId' WHEN 'MEDIA_METADATA' THEN 'mediaAssetId' END;
  IF owner_key IS NULL OR p.id IS NULL OR ref->>'schemaVersion' IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'checkout source requires a typed immutable publication' USING ERRCODE='23514';
  END IF;
  IF ref->>'mode'='APPROVED' AND p.proof_version=2 THEN
    SELECT m.manifest,m.manifest_hash INTO manifest,digest FROM public.content_publication_manifests m WHERE m.publication_id=p.id;
    IF kind='MEDIA_METADATA' THEN
      SELECT value INTO revision FROM jsonb_array_elements(manifest->'mediaRevisions') WHERE value->>'revisionId'=ref->>'revisionId';
    ELSE revision:=manifest->'revision'; END IF;
    SELECT value INTO audit FROM jsonb_array_elements(revision->'translationAudits') WHERE value->>'id'=ref->>'translationRevisionId';
    SELECT value->'fields' INTO fields FROM jsonb_array_elements(revision#>'{content,translations}') WHERE value->>'locale'=ref->>'resolvedLocale';
    IF (digest=ref->>'manifestHash'
      AND digest=encode(sha256(convert_to('fan-support.publication-manifest.v1'||chr(10)||public.canonical_publication_json(manifest),'UTF8')),'hex')
      AND revision->>'revisionId'=ref->>'revisionId' AND revision#>>'{target,kind}'=kind
      AND (revision->'target'->>owner_key)::uuid=owner
      AND audit->>'locale'=ref->>'resolvedLocale' AND audit->>'sourceHash'=ref->>'sourceHash'
      AND audit#>>'{review,status}'='APPROVED' AND fields IS NOT NULL
      AND (((ref->>'fallbackUsed')::boolean=false AND ref->>'requestedLocale'=ref->>'resolvedLocale')
        OR ((ref->>'fallbackUsed')::boolean=true AND ref->>'requestedLocale'<>'en' AND ref->>'resolvedLocale'='en'))
    ) IS NOT TRUE THEN RAISE EXCEPTION 'checkout approved source proof does not match' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('fields',fields,'media',coalesce(revision#>'{content,media}','[]'::jsonb));
  ELSIF ref->>'mode'='DAILY' AND p.proof_version=3 THEN
    SELECT m.manifest,m.manifest_hash INTO manifest,digest FROM public.daily_publication_manifests m WHERE m.publication_id=p.id;
    IF kind='MEDIA_METADATA' THEN
      SELECT value->'metadata' INTO revision FROM jsonb_array_elements(manifest->'media') WHERE value#>>'{metadata,revisionId}'=ref->>'revisionId';
    ELSE revision:=manifest->'document'; END IF;
    IF (digest=ref->>'manifestHash'
      AND digest=encode(sha256(convert_to('fan-support.daily-publication.v1'||chr(10)||public.canonical_publication_json(manifest),'UTF8')),'hex')
      AND ref->>'publicationMode'='DIRECT_OPERATOR_V1' AND revision->>'kind'=kind
      AND revision->>'revisionId'=ref->>'revisionId' AND (revision->>'ownerId')::uuid=owner
      AND revision#>>'{source,id}'=ref->>'translationRevisionId' AND revision#>>'{source,sourceHash}'=ref->>'sourceHash'
      AND revision#>>'{source,locale}'=ref->>'sourceLocale' AND ref->>'resolvedLocale'=ref->>'sourceLocale'
      AND (ref->>'fallbackUsed')::boolean=(ref->>'requestedLocale'<>ref->>'sourceLocale')
      AND EXISTS(SELECT 1 FROM public.daily_publication_revisions d WHERE d.revision_id=(ref->>'revisionId')::uuid AND d.source_translation_id=(ref->>'translationRevisionId')::uuid AND d.document=revision)
    ) IS NOT TRUE THEN RAISE EXCEPTION 'checkout daily source proof does not match' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('fields',revision#>'{source,fields}','media',coalesce(revision->'media','[]'::jsonb));
  END IF;
  RAISE EXCEPTION 'checkout publication mode and actual proof disagree' USING ERRCODE='23514';
END; $function$

CREATE OR REPLACE FUNCTION public.content_authoring_revision_sealed(parent_column text, revision_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE sealed boolean;
BEGIN
  IF parent_column NOT IN ('idol_revision_id','gift_revision_id','homepage_revision_id','policy_revision_id','media_metadata_revision_id') THEN
    RAISE EXCEPTION 'unsupported authoring parent' USING ERRCODE='55000';
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.content_authoring_receipts WHERE %I=$1 OR %I=$1)',parent_column,'source_'||parent_column) INTO sealed USING revision_id;
  RETURN sealed;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_admin_content_locale_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$ BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.revoked_at IS NOT NULL OR NEW.revoked_audit_log_id IS NOT NULL OR NEW.granted_at > clock_timestamp() THEN
      RAISE EXCEPTION 'new locale grant must be current and unrevoked' USING ERRCODE = '23514';
    END IF;
  ELSIF to_jsonb(NEW) - ARRAY['revoked_at','revoked_audit_log_id'] IS DISTINCT FROM to_jsonb(OLD) - ARRAY['revoked_at','revoked_audit_log_id']
    OR (OLD.revoked_at IS NOT NULL AND (NEW.revoked_at IS DISTINCT FROM OLD.revoked_at OR NEW.revoked_audit_log_id IS DISTINCT FROM OLD.revoked_audit_log_id))
    OR NEW.revoked_at IS NULL OR NEW.revoked_at > clock_timestamp() THEN
    RAISE EXCEPTION 'locale grant only permits one-way audited revocation' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_admin_finance_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
 IF NEW.generation<>0 OR NEW.dispatch_count<>0 OR NEW.lease_token_digest IS NOT NULL OR NEW.claim IS NOT NULL OR (NEW.phase='COMPLETE' AND NEW.action<>'CANCEL') THEN RAISE EXCEPTION 'financial operation must start unclaimed' USING ERRCODE='23514';END IF;
 IF NEW.attempt_id IS NULL AND (NEW.action<>'CANCEL' OR NEW.phase<>'COMPLETE' OR NEW.provider_account_id IS NOT NULL OR NEW.environment IS NOT NULL OR NEW.adapter_key IS NOT NULL OR EXISTS(SELECT 1 FROM payment_attempts WHERE order_id=NEW.order_id)) THEN RAISE EXCEPTION 'only an unattempted checkout may complete without provider binding' USING ERRCODE='23514';END IF;
 IF NEW.attempt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM payment_attempts a JOIN payment_provider_accounts p ON p.id=a.provider_account_id WHERE a.id=NEW.attempt_id AND a.order_id=NEW.order_id AND a.provider_account_id=NEW.provider_account_id AND a.environment=NEW.environment AND p.adapter_key=NEW.adapter_key) THEN RAISE EXCEPTION 'financial operation must pin original payment identity' USING ERRCODE='23514';END IF;
 ELSE
 IF to_jsonb(NEW)-ARRAY['phase','generation','dispatch_count','lease_token_digest','lease_expires_at','claim','next_attempt_at','last_error_code','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['phase','generation','dispatch_count','lease_token_digest','lease_expires_at','claim','next_attempt_at','last_error_code','updated_at'] OR NEW.generation<OLD.generation OR NEW.generation>OLD.generation+1 OR NEW.dispatch_count<OLD.dispatch_count OR OLD.phase='COMPLETE' THEN RAISE EXCEPTION 'financial operation immutable binding or fence invalid' USING ERRCODE='55000';END IF;
 END IF;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.guard_admin_idol_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE handle_value text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'idol identity history is retained by archival' USING ERRCODE='55000'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.schema_version IS DISTINCT FROM OLD.schema_version
   OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN RAISE EXCEPTION 'idol identity and optimistic version must be preserved' USING ERRCODE='23514'; END IF;
  IF OLD.status='archived' AND (NEW.handle IS DISTINCT FROM OLD.handle OR NEW.status IS DISTINCT FROM OLD.status OR NEW.accepting_gifts IS DISTINCT FROM OLD.accepting_gifts) THEN RAISE EXCEPTION 'archived idol identity cannot be reactivated or renamed' USING ERRCODE='23514'; END IF;
 END IF;
 IF TG_OP='INSERT' OR NEW.handle IS DISTINCT FROM OLD.handle THEN
  -- Both current names and every historical source name remain reserved. Locks serialize competing changes to the same namespace.
  FOR handle_value IN SELECT DISTINCT v FROM unnest(CASE WHEN TG_OP='INSERT' THEN ARRAY[NEW.handle] ELSE ARRAY[OLD.handle,NEW.handle] END) v ORDER BY v LOOP
   PERFORM pg_advisory_xact_lock(hashtextextended('fan-support:idol-handle:'||handle_value,0));
  END LOOP;
  IF EXISTS(SELECT 1 FROM public.slug_redirects WHERE entity_type='IDOL' AND old_handle=NEW.handle)
    OR EXISTS(SELECT 1 FROM public.idols WHERE handle=NEW.handle AND id<>NEW.id) THEN RAISE EXCEPTION 'idol handle is reserved by a current or historical identity' USING ERRCODE='23505'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_admin_login_challenge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.state<>'READY' OR NEW.created_at<transaction_timestamp() OR NEW.created_at>clock_timestamp() THEN
      RAISE EXCEPTION 'login challenge must start ready at database time' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-'state'-'claim_digest'-'claimed_at'-'completed_at'-'session_id'-'audit_log_id') IS DISTINCT FROM
     (to_jsonb(OLD)-'state'-'claim_digest'-'claimed_at'-'completed_at'-'session_id'-'audit_log_id') THEN
    RAISE EXCEPTION 'login challenge binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.state='READY' AND NEW.state='CLAIMED' THEN
    IF NEW.claimed_at<transaction_timestamp() OR NEW.claimed_at>clock_timestamp() OR NEW.claimed_at>=NEW.expires_at OR clock_timestamp()>=NEW.expires_at THEN
      RAISE EXCEPTION 'login claim requires fresh database time' USING ERRCODE='23514';
    END IF;
  ELSIF OLD.state='CLAIMED' AND NEW.state='CONSUMED' THEN
    IF NEW.claim_digest IS DISTINCT FROM OLD.claim_digest OR NEW.claimed_at<>OLD.claimed_at
      OR NEW.completed_at<transaction_timestamp() OR NEW.completed_at>clock_timestamp() THEN
      RAISE EXCEPTION 'login completion must preserve claim and database time' USING ERRCODE='23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'login challenge is single use' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_admin_order_message_locale()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE a public.audit_logs%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.revoked_at IS NOT NULL OR NEW.granted_at>clock_timestamp() THEN RAISE EXCEPTION 'invalid initial order language grant' USING ERRCODE='23514'; END IF;
  SELECT * INTO a FROM public.audit_logs WHERE id=NEW.audit_log_id;
  IF a.action IS DISTINCT FROM 'ORDER_MESSAGE_LOCALE_GRANT' OR a.actor_id IS DISTINCT FROM NEW.granted_by OR a.created_at IS DISTINCT FROM NEW.granted_at THEN RAISE EXCEPTION 'order language grant requires exact audit' USING ERRCODE='23514'; END IF;
 ELSE
  IF to_jsonb(NEW)-ARRAY['revoked_at','revoked_audit_log_id'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['revoked_at','revoked_audit_log_id'] OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR NEW.revoked_at>clock_timestamp() THEN RAISE EXCEPTION 'order language grant only permits one-way revocation' USING ERRCODE='55000'; END IF;
  SELECT * INTO a FROM public.audit_logs WHERE id=NEW.revoked_audit_log_id;
  IF a.action IS DISTINCT FROM 'ORDER_MESSAGE_LOCALE_REVOKE' OR a.created_at IS DISTINCT FROM NEW.revoked_at THEN RAISE EXCEPTION 'order language revocation requires exact audit' USING ERRCODE='23514'; END IF;
 END IF;
 IF a.actor_type IS DISTINCT FROM 'ADMIN' OR a.subject_type IS DISTINCT FROM 'ADMIN_ORDER_MESSAGE_LOCALE_GRANT' OR a.subject_id IS DISTINCT FROM NEW.admin_identity_id OR a.outcome IS DISTINCT FROM 'SUCCEEDED' OR a.reason_code IS NULL OR a.request_id IS NULL OR a.correlation_id IS NULL OR a.field_category IS DISTINCT FROM 'SUPPORT_INTENT_PRIVATE' OR NOT EXISTS(SELECT 1 FROM public.admin_identities WHERE id=a.actor_id AND status='ACTIVE') THEN RAISE EXCEPTION 'order language audit authority invalid' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_authored_content_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE old_parent uuid; new_parent uuid; item jsonb;
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF EXISTS(SELECT 1 FROM public.content_authoring_receipts) THEN
      RAISE EXCEPTION 'authored content history cannot be truncated' USING ERRCODE='55000';
    END IF;
    RETURN NULL;
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW))) WHERE value IS NOT NULL AND value <> 'null'::jsonb LOOP
    IF TG_NARGS = 2 THEN
      new_parent := (item ->> TG_ARGV[1])::uuid;
    ELSE
      EXECUTE format('SELECT %I FROM %s WHERE id=$1',TG_ARGV[0],TG_ARGV[2]::regclass)
        INTO new_parent USING (item ->> TG_ARGV[1])::uuid;
    END IF;
    EXECUTE format('SELECT id FROM public.%I WHERE id=$1 FOR UPDATE',left(TG_ARGV[0],length(TG_ARGV[0])-3)||'s') USING new_parent;
    IF public.content_authoring_revision_sealed(TG_ARGV[0],new_parent) THEN
      RAISE EXCEPTION 'authored revision payload is sealed; create another revision' USING ERRCODE='55000';
    END IF;
  END LOOP;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_base_content_preview_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE session public.admin_sessions%ROWTYPE; identity_status text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF to_jsonb(NEW) - ARRAY['revoked_at','revoked_audit_log_id'] IS DISTINCT FROM to_jsonb(OLD) - ARRAY['revoked_at','revoked_audit_log_id']
      OR (OLD.revoked_at IS NOT NULL AND (NEW.revoked_at IS DISTINCT FROM OLD.revoked_at OR NEW.revoked_audit_log_id IS DISTINCT FROM OLD.revoked_audit_log_id))
      OR NEW.revoked_at IS NULL OR NEW.revoked_at > GREATEST(clock_timestamp(),transaction_timestamp(),OLD.created_at) THEN
      RAISE EXCEPTION 'preview grant only permits one-way revocation' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO session FROM public.admin_sessions WHERE id = NEW.session_id FOR SHARE;
  SELECT status INTO identity_status FROM public.admin_identities WHERE id = NEW.actor_id FOR SHARE;
  IF session.id IS NULL OR session.admin_identity_id <> NEW.actor_id OR identity_status IS DISTINCT FROM 'ACTIVE'
    OR NOT session.authenticated_with_mfa OR session.revoked_at IS NOT NULL OR session.expires_at <= clock_timestamp()
    OR NEW.created_at < session.created_at OR NEW.created_at > GREATEST(clock_timestamp(),transaction_timestamp(),session.created_at)
    OR NEW.expires_at > session.expires_at OR NEW.revoked_at IS NOT NULL OR NEW.revoked_audit_log_id IS NOT NULL THEN
    RAISE EXCEPTION 'preview grant requires its active MFA session and actor' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_cart_item_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  parent_status text;
BEGIN
  SELECT status INTO parent_status FROM carts WHERE id = OLD.cart_id FOR SHARE;
  IF parent_status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'cart items are immutable after the cart leaves ACTIVE'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.id <> OLD.id OR NEW.cart_id <> OLD.cart_id OR NEW.created_at <> OLD.created_at
     OR NEW.request_id <> OLD.request_id
     OR NEW.correlation_id <> OLD.correlation_id THEN
    RAISE EXCEPTION 'cart item ownership is immutable' USING ERRCODE = '55000';
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'cart item version must increment exactly once' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_cart_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'cart version must increment exactly once' USING ERRCODE = '23514';
  END IF;
  IF NEW.id <> OLD.id OR NEW.token_digest <> OLD.token_digest
     OR NEW.token_pepper_version <> OLD.token_pepper_version
     OR NEW.market <> OLD.market OR NEW.currency <> OLD.currency THEN
    RAISE EXCEPTION 'cart identity and commerce context are immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'ACTIVE' AND NEW.status IN ('LOCKED', 'EXPIRED'))
    OR (OLD.status = 'LOCKED' AND NEW.status IN ('CONVERTED', 'EXPIRED'))
  ) THEN
    RAISE EXCEPTION 'invalid cart status transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_checkout_session_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF (to_jsonb(NEW) - 'status' - 'updated_at') IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'updated_at') THEN
    RAISE EXCEPTION 'checkout quote and commerce context are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'CREATED' AND NEW.status IN ('READY', 'EXPIRED'))
    OR (OLD.status = 'READY' AND NEW.status IN ('PAYMENT_PENDING', 'EXPIRED'))
    OR (OLD.status = 'PAYMENT_PENDING' AND NEW.status IN ('COMPLETED', 'EXPIRED'))
  ) THEN
    RAISE EXCEPTION 'invalid checkout session status transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_config_version_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.lifecycle <> 'DRAFT' THEN
      RAISE EXCEPTION 'new configuration revisions must start in DRAFT'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'configuration revisions cannot be deleted' USING ERRCODE = '55000';
  END IF;
  IF (to_jsonb(NEW) - 'lifecycle' - 'published_at') IS DISTINCT FROM
     (to_jsonb(OLD) - 'lifecycle' - 'published_at') THEN
    RAISE EXCEPTION 'configuration revision payload is immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.lifecycle = OLD.lifecycle
    OR (OLD.lifecycle = 'DRAFT' AND NEW.lifecycle = 'VALIDATED')
    OR (OLD.lifecycle = 'VALIDATED' AND NEW.lifecycle = 'PUBLISHED')
    OR (OLD.lifecycle = 'PUBLISHED' AND NEW.lifecycle = 'SUPERSEDED')
    OR (OLD.lifecycle = 'SUPERSEDED' AND NEW.lifecycle = 'ARCHIVED')
  ) THEN
    RAISE EXCEPTION 'invalid configuration lifecycle transition' USING ERRCODE = '23514';
  END IF;
  IF NEW.lifecycle = OLD.lifecycle AND NEW.published_at IS DISTINCT FROM OLD.published_at THEN
    RAISE EXCEPTION 'configuration publication time is immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_content_draft_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE owner_id uuid; parent_state text; document uuid; alias_set uuid; editor uuid; capacity integer; occupied integer;
BEGIN
  IF TG_TABLE_NAME = 'idol_revision_alias_sets' THEN
    owner_id := NEW.idol_revision_id; editor := NEW.editor_id;
  ELSIF TG_TABLE_NAME IN ('idol_revision_aliases','idol_revision_alias_reviews') THEN
    alias_set := NEW.alias_set_id;
    SELECT idol_revision_id INTO owner_id FROM public.idol_revision_alias_sets WHERE id = alias_set FOR UPDATE;
  ELSIF TG_TABLE_NAME = 'gift_detail_documents' THEN
    owner_id := NEW.gift_revision_id; editor := NEW.editor_id;
  ELSE
    IF TG_TABLE_NAME = 'gift_detail_translation_reviews' THEN
      SELECT document_id INTO document FROM public.gift_detail_translations WHERE id = NEW.gift_detail_translation_id FOR UPDATE;
    ELSE document := NEW.document_id;
    END IF;
    SELECT gift_revision_id INTO owner_id FROM public.gift_detail_documents WHERE id = document FOR UPDATE;
  END IF;
  IF TG_TABLE_NAME LIKE 'idol_%' THEN
    SELECT lifecycle INTO parent_state FROM public.idol_revisions WHERE id = owner_id FOR UPDATE;
  ELSE
    SELECT lifecycle INTO parent_state FROM public.gift_revisions WHERE id = owner_id FOR UPDATE;
  END IF;
  IF parent_state IS DISTINCT FROM 'DRAFT' THEN
    RAISE EXCEPTION 'content extensions require a draft parent revision' USING ERRCODE = '55000';
  END IF;
  IF editor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.admin_identities WHERE id = editor AND status = 'ACTIVE') THEN
    RAISE EXCEPTION 'content draft editor must be active' USING ERRCODE = '23514';
  END IF;
  -- Header commit proves that every immutable capacity is filled. Since child
  -- updates/deletes are forbidden, these locked limits also seal later inserts.
  IF TG_TABLE_NAME = 'idol_revision_aliases' THEN
    SELECT alias_count INTO capacity FROM public.idol_revision_alias_sets WHERE id = alias_set;
    SELECT count(*) INTO occupied FROM public.idol_revision_aliases WHERE alias_set_id = alias_set;
  ELSIF TG_TABLE_NAME = 'gift_detail_blocks' THEN
    SELECT block_count INTO capacity FROM public.gift_detail_documents WHERE id = document;
    SELECT count(*) INTO occupied FROM public.gift_detail_blocks WHERE document_id = document;
  ELSIF TG_TABLE_NAME = 'gift_detail_block_items' THEN
    SELECT item_count INTO capacity FROM public.gift_detail_blocks WHERE document_id = document AND block_id = NEW.block_id;
    SELECT count(*) INTO occupied FROM public.gift_detail_block_items WHERE document_id = document AND block_id = NEW.block_id;
  ELSIF TG_TABLE_NAME = 'gift_detail_translations' THEN
    SELECT translation_count INTO capacity FROM public.gift_detail_documents WHERE id = document;
    SELECT count(*) INTO occupied FROM public.gift_detail_translations WHERE document_id = document;
  ELSIF TG_TABLE_NAME = 'gift_detail_translation_blocks' THEN
    SELECT block_count INTO capacity FROM public.gift_detail_documents WHERE id = document;
    SELECT count(*) INTO occupied FROM public.gift_detail_translation_blocks WHERE translation_id = NEW.translation_id;
  ELSIF TG_TABLE_NAME = 'gift_detail_translation_items' THEN
    SELECT item_count INTO capacity FROM public.gift_detail_blocks WHERE document_id = document AND block_id = NEW.block_id;
    SELECT count(*) INTO occupied FROM public.gift_detail_translation_items WHERE translation_id = NEW.translation_id AND block_id = NEW.block_id;
  ELSE RETURN NEW;
  END IF;
  IF capacity IS NULL OR occupied >= capacity THEN
    RAISE EXCEPTION 'content draft child capacity is sealed' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_content_preview_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE session public.admin_sessions%ROWTYPE; identity_status text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF to_jsonb(NEW) - ARRAY['revoked_at','revoked_audit_log_id'] IS DISTINCT FROM to_jsonb(OLD) - ARRAY['revoked_at','revoked_audit_log_id']
      OR (OLD.revoked_at IS NOT NULL AND (NEW.revoked_at IS DISTINCT FROM OLD.revoked_at OR NEW.revoked_audit_log_id IS DISTINCT FROM OLD.revoked_audit_log_id))
      OR NEW.revoked_at IS NULL OR NEW.revoked_at > GREATEST(clock_timestamp(),transaction_timestamp(),OLD.created_at) THEN
      RAISE EXCEPTION 'preview grant only permits one-way revocation' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO session FROM public.admin_sessions WHERE id = NEW.session_id FOR SHARE;
  SELECT status INTO identity_status FROM public.admin_identities WHERE id = NEW.actor_id FOR SHARE;
  IF session.id IS NULL OR session.admin_identity_id <> NEW.actor_id OR identity_status IS DISTINCT FROM 'ACTIVE'
    OR NOT session.authenticated_with_mfa OR session.revoked_at IS NOT NULL OR session.expires_at <= clock_timestamp()
    OR NEW.created_at < session.created_at OR NEW.created_at > GREATEST(clock_timestamp(),transaction_timestamp(),session.created_at)
    OR NEW.expires_at > session.expires_at OR NEW.revoked_at IS NOT NULL OR NEW.revoked_audit_log_id IS NOT NULL THEN
    RAISE EXCEPTION 'preview grant requires its active MFA session and actor' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_content_purge_job()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE publication public.content_publications%ROWTYPE; event public.outbox_events%ROWTYPE;
  parent public.content_purge_jobs%ROWTYPE; root text; expected_paths text[]; expanded_paths text[]; actual_now timestamptz:=clock_timestamp();
BEGIN
  IF TG_OP='INSERT' THEN
    SELECT * INTO publication FROM public.content_publications WHERE id=NEW.publication_id;
    SELECT * INTO event FROM public.outbox_events WHERE id=NEW.outbox_event_id;
    root:='/'||NEW.locale::text;
    expected_paths:=CASE publication.content_type
      WHEN 'HOMEPAGE' THEN ARRAY[root,root||'/sitemap.xml']
      WHEN 'POLICY' THEN ARRAY[root||'/policies/'||publication.policy_key||'*',root||'/sitemap.xml']
      WHEN 'MEDIA_METADATA' THEN ARRAY[root,root||'/gifts*',root||'/idols*',root||'/media/'||publication.media_asset_id::text||'*',root||'/sitemap.xml']
      ELSE ARRAY[root,root||'/gifts*',root||'/idols*',root||'/sitemap.xml'] END;
    SELECT array_agg(path ORDER BY path COLLATE "C") INTO expanded_paths
      FROM unnest(expected_paths||ARRAY['/sitemap.xml*',root||'/sitemap.xml*','/api/v1/storefront-seo/*']) AS paths(path);
    IF publication.id IS NULL OR publication.proof_version NOT IN(2,3) OR event.id IS NULL
      OR event.event_type IS DISTINCT FROM 'CONTENT_PUBLICATION_CHANGED'
      OR event.aggregate_type IS DISTINCT FROM 'CONTENT_PUBLICATION'
      OR event.aggregate_id IS DISTINCT FROM NEW.publication_id
      OR event.primary_subject_id IS DISTINCT FROM NEW.publication_id OR event.locale IS DISTINCT FROM NEW.locale
      OR (NEW.paths IS DISTINCT FROM expected_paths AND NEW.paths IS DISTINCT FROM expanded_paths) OR NEW.status<>'PENDING' OR NEW.version<>1 OR NEW.attempt_count<>0 OR NEW.failure_count<>0
      OR NEW.lease_token IS NOT NULL OR NEW.purge_reference IS NOT NULL OR NEW.error_code IS NOT NULL
      OR NEW.completed_at IS NOT NULL OR NEW.updated_at<>NEW.created_at OR NEW.next_attempt_at IS DISTINCT FROM NEW.created_at THEN
      RAISE EXCEPTION 'purge jobs require exact publication locale paths and initial state' USING ERRCODE='23514';
    END IF;
    IF NEW.generation=1 THEN
      IF NEW.created_at<>publication.published_at THEN RAISE EXCEPTION 'root purge job must share publication time' USING ERRCODE='23514'; END IF;
    ELSE
      SELECT * INTO parent FROM public.content_purge_jobs WHERE id=NEW.retry_of FOR UPDATE;
      IF parent.id IS NULL OR parent.status<>'FAILED' OR NEW.generation<>parent.generation+1
        OR NEW.publication_id<>parent.publication_id OR NEW.outbox_event_id<>parent.outbox_event_id
        OR NEW.locale<>parent.locale OR NEW.paths IS DISTINCT FROM parent.paths OR NEW.created_at<parent.updated_at THEN
        RAISE EXCEPTION 'purge retries require an exact failed predecessor' USING ERRCODE='23514';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-ARRAY['status','version','attempt_count','failure_count','lease_token','lease_expires_at','purge_reference','error_code','updated_at','next_attempt_at','completed_at'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','attempt_count','failure_count','lease_token','lease_expires_at','purge_reference','error_code','updated_at','next_attempt_at','completed_at'])
    OR OLD.status IN ('COMPLETED','FAILED') OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at
    OR NEW.updated_at>GREATEST(actual_now,transaction_timestamp(),OLD.updated_at) THEN
    RAISE EXCEPTION 'purge identity is immutable and transitions require one causal version' USING ERRCODE='23514';
  END IF;
  IF NEW.lease_token IS NOT NULL THEN
    IF (OLD.lease_expires_at IS NOT NULL AND OLD.lease_expires_at>actual_now) OR OLD.next_attempt_at>actual_now
      OR NEW.lease_token IS NOT DISTINCT FROM OLD.lease_token OR NEW.lease_expires_at<=actual_now
      OR NEW.lease_expires_at>actual_now+interval '300 seconds' OR NEW.lease_expires_at>OLD.created_at+interval '10 minutes'
      OR NEW.attempt_count<>OLD.attempt_count+1 OR NEW.failure_count<>OLD.failure_count OR NEW.status<>OLD.status
      OR NEW.next_attempt_at IS DISTINCT FROM OLD.next_attempt_at OR NEW.purge_reference IS DISTINCT FROM OLD.purge_reference
      OR NEW.error_code IS DISTINCT FROM OLD.error_code OR NEW.completed_at IS DISTINCT FROM OLD.completed_at THEN
      RAISE EXCEPTION 'purge claims require a due job and bounded fresh lease' USING ERRCODE='23514';
    END IF;
  ELSE
    IF NEW.attempt_count<>OLD.attempt_count OR NEW.lease_expires_at IS NOT NULL THEN
      RAISE EXCEPTION 'purge results cannot change claim count' USING ERRCODE='23514';
    END IF;
    IF NEW.status='FAILED' AND NEW.error_code IS NULL THEN
      RAISE EXCEPTION 'failed purge jobs require a safe failure code' USING ERRCODE='23514';
    END IF;
    IF NEW.error_code='PURGE_TIMEOUT' AND NEW.status<>'FAILED' THEN
      RAISE EXCEPTION 'absolute purge timeout must be terminal' USING ERRCODE='23514';
    END IF;
    IF NEW.status='FAILED' AND NEW.error_code='PURGE_TIMEOUT' THEN
      IF actual_now<OLD.created_at+interval '10 minutes' OR NEW.failure_count<>OLD.failure_count
        OR NEW.purge_reference IS DISTINCT FROM OLD.purge_reference THEN
        RAISE EXCEPTION 'purge timeout requires the absolute deadline' USING ERRCODE='23514';
      END IF;
    ELSIF OLD.lease_token IS NULL OR OLD.lease_expires_at<=actual_now THEN
      RAISE EXCEPTION 'purge results require a current unexpired claim' USING ERRCODE='23514';
    END IF;
    IF NEW.status='COMPLETED' THEN
      IF NEW.completed_at IS DISTINCT FROM NEW.updated_at OR NEW.purge_reference IS NULL OR NEW.error_code IS NOT NULL
        OR NEW.failure_count<>OLD.failure_count OR (OLD.purge_reference IS NOT NULL AND NEW.purge_reference<>OLD.purge_reference) THEN
        RAISE EXCEPTION 'purge completion requires the same provider reference' USING ERRCODE='23514';
      END IF;
    ELSIF NEW.error_code IS NOT NULL AND NEW.error_code<>'PURGE_TIMEOUT' THEN
      IF NEW.failure_count<>OLD.failure_count+1 OR NEW.purge_reference IS DISTINCT FROM OLD.purge_reference
        OR NEW.status NOT IN (OLD.status,'FAILED') OR (NEW.failure_count>=6 AND NEW.status<>'FAILED') THEN
        RAISE EXCEPTION 'purge failure must preserve provider identity and bounded retries' USING ERRCODE='23514';
      END IF;
    ELSIF NEW.status<>'FAILED' THEN
      IF NEW.status<>'SUBMITTED' OR NEW.purge_reference IS NULL OR NEW.failure_count<>OLD.failure_count
        OR (OLD.purge_reference IS NOT NULL AND NEW.purge_reference<>OLD.purge_reference) THEN
        RAISE EXCEPTION 'pending provider work must remain submitted' USING ERRCODE='23514';
      END IF;
    END IF;
    IF NEW.next_attempt_at IS NOT NULL AND NEW.next_attempt_at>OLD.created_at+interval '10 minutes' THEN
      RAISE EXCEPTION 'purge retry schedule cannot extend the absolute deadline' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_customer_contact_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.id <> OLD.id OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'customer contact identity is immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.retention_status = OLD.retention_status
    OR (OLD.retention_status = 'ACTIVE' AND NEW.retention_status = 'PURGE_PENDING')
    OR (OLD.retention_status = 'PURGE_PENDING' AND NEW.retention_status = 'PURGED')
  ) THEN
    RAISE EXCEPTION 'invalid customer contact retention transition' USING ERRCODE = '23514';
  END IF;
  IF OLD.retention_status = 'ACTIVE' AND NEW.retention_status = 'ACTIVE'
     AND (to_jsonb(NEW) - 'email_ciphertext' - 'encrypted_data_key' - 'encryption_key_version'
          - 'email_lookup_hmac' - 'lookup_key_version') IS DISTINCT FROM
         (to_jsonb(OLD) - 'email_ciphertext' - 'encrypted_data_key' - 'encryption_key_version'
          - 'email_lookup_hmac' - 'lookup_key_version') THEN
    RAISE EXCEPTION 'only encrypted contact material may rotate while active'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_finance_fulfillment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$BEGIN
 IF NEW.status IN('PENDING','PREPARING','DELIVERED') AND NEW.status IS DISTINCT FROM OLD.status THEN
 PERFORM 1 FROM orders WHERE id=NEW.order_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM disputes WHERE order_id=NEW.order_id AND status IN('OPEN','LOST')) THEN RAISE EXCEPTION 'open or lost dispute prevents fulfillment advancement' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM refunds WHERE order_id=NEW.order_id AND status IN('REQUESTED','SUBMITTING','PROCESSING','UNKNOWN')) THEN RAISE EXCEPTION 'pending refund prevents preparation or delivery' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;END;$function$

CREATE OR REPLACE FUNCTION public.guard_fulfillment_profile_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.id <> OLD.id OR NEW.idol_id <> OLD.idol_id
     OR NEW.profile_version <> OLD.profile_version OR NEW.created_by <> OLD.created_by
     OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'fulfillment profile identity is immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'ACTIVE' AND NEW.status = 'SUPERSEDED')
    OR (OLD.status = 'SUPERSEDED' AND NEW.status = 'PURGED')
  ) THEN
    RAISE EXCEPTION 'invalid fulfillment profile transition' USING ERRCODE = '23514';
  END IF;
  IF NEW.status <> 'PURGED' AND (
    NEW.profile_ciphertext IS DISTINCT FROM OLD.profile_ciphertext
    OR NEW.encrypted_data_key IS DISTINCT FROM OLD.encrypted_data_key
    OR NEW.encryption_key_version IS DISTINCT FROM OLD.encryption_key_version
  ) THEN
    RAISE EXCEPTION 'fulfillment profile material is immutable; create a new version'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_fulfillment_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.status <> 'PENDING'
       OR NEW.hold_reason_code IS NOT NULL OR NEW.prepared_at IS NOT NULL
       OR NEW.delivered_at IS NOT NULL THEN
      RAISE EXCEPTION 'fulfillment must start PENDING at version one'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'fulfillment version must increment exactly once' USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW)
        - 'status' - 'version' - 'hold_reason_code' - 'prepared_at' - 'delivered_at' - 'updated_at')
     IS DISTINCT FROM
     (to_jsonb(OLD)
        - 'status' - 'version' - 'hold_reason_code' - 'prepared_at' - 'delivered_at' - 'updated_at') THEN
    RAISE EXCEPTION 'fulfillment ownership and profile snapshot are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NOT (
    (OLD.status = 'PENDING' AND NEW.status IN ('PREPARING', 'ON_HOLD', 'CANCELED'))
    OR (OLD.status = 'PREPARING' AND NEW.status IN ('DELIVERED', 'ON_HOLD', 'CANCELED'))
    OR (OLD.status = 'ON_HOLD' AND NEW.status IN ('PENDING', 'PREPARING', 'CANCELED'))
  ) THEN
    RAISE EXCEPTION 'invalid fulfillment transition' USING ERRCODE = '23514';
  END IF;
  IF OLD.prepared_at IS NOT NULL AND NEW.prepared_at IS DISTINCT FROM OLD.prepared_at THEN
    RAISE EXCEPTION 'fulfillment prepared timestamp is immutable once set'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.status IN ('PREPARING', 'DELIVERED') AND NEW.prepared_at IS NULL THEN
    RAISE EXCEPTION 'prepared and delivered fulfillment requires prepared_at'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status IN ('PREPARING', 'DELIVERED') AND NOT EXISTS (
    SELECT 1
    FROM public.order_items item
    JOIN public.support_intents intent ON intent.id = item.support_intent_id
    JOIN public.cart_items cart_item ON cart_item.id = item.cart_item_id
    WHERE item.id = NEW.order_item_id
      AND item.order_id = NEW.order_id
      AND (
        ((cart_item.has_fan_message OR intent.fan_message_ciphertext IS NOT NULL)
          AND intent.moderation_status = 'APPROVED'
          AND intent.privacy_state <> 'PURGED')
        OR (NOT cart_item.has_fan_message
          AND intent.fan_message_ciphertext IS NULL
          AND intent.moderation_status NOT IN ('REJECTED', 'REDACTED'))
      )
  ) THEN
    RAISE EXCEPTION 'fulfillment cannot prepare or deliver an unsafe support intent'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.delivered_at IS NOT NULL AND NEW.delivered_at IS DISTINCT FROM OLD.delivered_at THEN
    RAISE EXCEPTION 'fulfillment delivered timestamp is immutable once set'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_gift_commerce_price_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE b public.price_books%ROWTYPE; book_id uuid; book_revision bigint;
BEGIN
 IF TG_TABLE_NAME='price_books' THEN
   IF TG_OP='INSERT' THEN
     IF NEW.commerce_proof_version<>2 OR NEW.lifecycle<>'DRAFT' THEN RAISE EXCEPTION 'new price book requires managed draft' USING ERRCODE='23514'; END IF;
     RETURN NEW;
   END IF;
   IF NEW.commerce_proof_version IS DISTINCT FROM OLD.commerce_proof_version THEN RAISE EXCEPTION 'price proof version is immutable' USING ERRCODE='55000'; END IF;
   IF EXISTS(SELECT 1 FROM public.gift_price_revision_receipts WHERE (price_book_id=OLD.id AND revision=OLD.revision) OR (source_price_book_id=OLD.id AND source_revision=OLD.revision))
     AND to_jsonb(NEW)-ARRAY['lifecycle','validated_at','published_at','superseded_at','archived_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['lifecycle','validated_at','published_at','superseded_at','archived_at'] THEN
     RAISE EXCEPTION 'authored price payload is sealed' USING ERRCODE='55000';
   END IF;
   RETURN NEW;
 END IF;
 book_id:=COALESCE(NEW.price_book_id,OLD.price_book_id);book_revision:=COALESCE(NEW.price_book_revision,OLD.price_book_revision);
 SELECT * INTO b FROM public.price_books WHERE id=book_id AND revision=book_revision FOR UPDATE;
 IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM public.gift_price_revision_receipts WHERE (price_book_id=book_id AND revision=book_revision) OR (source_price_book_id=book_id AND source_revision=book_revision)) THEN
   RAISE EXCEPTION 'sealed price book membership cannot shrink' USING ERRCODE='55000',CONSTRAINT='gift_price_membership_sealed';
 END IF;
 IF TG_OP='INSERT' AND (b.lifecycle<>'DRAFT' OR EXISTS(SELECT 1 FROM public.gift_price_revision_receipts WHERE (price_book_id=book_id AND revision=book_revision) OR (source_price_book_id=book_id AND source_revision=book_revision))) THEN
   RAISE EXCEPTION 'price book membership is sealed' USING ERRCODE='55000',CONSTRAINT='gift_price_membership_sealed';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_gift_detail_structure_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE structure_editor uuid;
BEGIN
  IF NEW.status = 'APPROVED' THEN
    SELECT d.editor_id INTO structure_editor FROM public.gift_detail_translations t
      JOIN public.gift_detail_documents d ON d.id = t.document_id WHERE t.id = NEW.gift_detail_translation_id;
    IF structure_editor IS NULL OR NEW.reviewer_id = structure_editor THEN
      RAISE EXCEPTION 'gift detail structure requires independent approval' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_gift_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'gift identity is retained by archival' USING ERRCODE='55000'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.schema_version IS DISTINCT FROM OLD.schema_version OR NEW.handle IS DISTINCT FROM OLD.handle OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
   RAISE EXCEPTION 'gift identity and optimistic version must be preserved' USING ERRCODE='23514'; END IF;
  IF OLD.status='archived' AND NEW.status IS DISTINCT FROM OLD.status THEN RAISE EXCEPTION 'archived gift cannot be reactivated' USING ERRCODE='23514'; END IF;
 ELSE
  PERFORM pg_advisory_xact_lock(hashtextextended('fan-support:gift-handle:'||NEW.handle,0));
  IF EXISTS(SELECT 1 FROM public.slug_redirects WHERE entity_type='GIFT' AND old_handle=NEW.handle) THEN RAISE EXCEPTION 'gift handle is reserved' USING ERRCODE='23505'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_gift_inventory_adjustment_prior()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v public.gift_variants%ROWTYPE; i public.inventory_items%ROWTYPE; b public.inventory_balances%ROWTYPE; location_status text;
BEGIN
 SELECT * INTO v FROM public.gift_variants WHERE id=NEW.gift_variant_id FOR UPDATE;
 SELECT * INTO i FROM public.inventory_items WHERE id=NEW.inventory_item_id FOR UPDATE;
 SELECT status INTO location_status FROM public.inventory_locations WHERE id=NEW.inventory_location_id FOR SHARE;
 SELECT * INTO b FROM public.inventory_balances WHERE inventory_item_id=i.id AND location_id=NEW.inventory_location_id FOR UPDATE;
 IF v.id IS NULL OR v.version IS DISTINCT FROM NEW.expected_variant_version OR v.inventory_policy<>'TRACKED'
   OR i.id IS NULL OR i.gift_variant_id IS DISTINCT FROM v.id OR i.policy<>'TRACKED' OR i.status<>'ACTIVE' OR location_status IS DISTINCT FROM 'ACTIVE'
   OR b.updated_at IS DISTINCT FROM NEW.previous_balance_updated_at
   OR COALESCE(b.version,0)<>NEW.expected_balance_version OR COALESCE(b.on_hand,0)<>NEW.previous_on_hand OR COALESCE(b.reserved,0)<>NEW.previous_reserved THEN
   RAISE EXCEPTION 'inventory receipt requires locked exact previous balance' USING ERRCODE='23514',CONSTRAINT='gift_inventory_prior';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_gift_profile_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  -- Explicit ADR-012 dispatch; all following strict behavior is retained.
  IF TG_OP='INSERT' AND NEW.profile_version=3 AND EXISTS(SELECT 1 FROM public.daily_publication_revisions WHERE gift_revision_id=NEW.id) THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' AND NEW.profile_version<>2 THEN RAISE EXCEPTION 'new gift revisions require current classification evidence' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND NEW.profile_version IS DISTINCT FROM OLD.profile_version THEN RAISE EXCEPTION 'gift profile provenance is immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_gift_variant_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'variant history is retained by archival' USING ERRCODE='55000'; END IF;
 PERFORM id FROM public.gifts WHERE id=NEW.gift_id FOR UPDATE;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.gift_id IS DISTINCT FROM OLD.gift_id OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.schema_version IS DISTINCT FROM OLD.schema_version OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at OR OLD.status='archived') THEN RAISE EXCEPTION 'variant identity and version are immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_idempotency_record_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF (to_jsonb(NEW) - 'status' - 'safe_result_reference' - 'updated_at') IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'safe_result_reference' - 'updated_at') THEN
    RAISE EXCEPTION 'idempotency request identity is immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'IN_PROGRESS' AND NEW.status IN ('SUCCEEDED', 'FAILED'))
  ) THEN
    RAISE EXCEPTION 'invalid idempotency status transition' USING ERRCODE = '23514';
  END IF;
  IF OLD.status <> 'IN_PROGRESS' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
    RAISE EXCEPTION 'terminal idempotency evidence is immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_idol_daily_search_projection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE source public.daily_publication_revisions%ROWTYPE;
BEGIN
 SELECT * INTO source FROM public.daily_publication_revisions WHERE revision_id=NEW.revision_id;
 IF source.revision_id IS NULL OR source.object_kind<>'IDOL' OR NEW.source_translation_id<>source.source_translation_id
 OR NEW.source_hash IS DISTINCT FROM source.document#>>'{source,sourceHash}' OR NEW.document_hash<>source.document_hash THEN
  RAISE EXCEPTION 'daily search projection requires its exact real original' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_immutable_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  column_name text;
BEGIN
  FOREACH column_name IN ARRAY TG_ARGV
  LOOP
    IF (to_jsonb(NEW) -> column_name) IS DISTINCT FROM
       (to_jsonb(OLD) -> column_name) THEN
      RAISE EXCEPTION '% column %.% is immutable', TG_TABLE_NAME, TG_TABLE_NAME, column_name
        USING ERRCODE = '55000';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_inventory_reservation_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'ACTIVE' OR NEW.version <> 1 THEN
      RAISE EXCEPTION 'new reservation must start ACTIVE at version 1'
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.inventory_items item
      JOIN public.gift_variants variant ON variant.id = item.gift_variant_id
      WHERE item.id = NEW.inventory_item_id
        AND item.gift_variant_id = NEW.gift_variant_id
        AND item.policy = 'TRACKED'
        AND variant.inventory_policy = 'TRACKED'
    ) THEN
      RAISE EXCEPTION 'only TRACKED inventory may be reserved'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'reservation version must increment exactly once' USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - 'status' - 'version' - 'updated_at' - 'committed_at' - 'released_at' - 'expired_at' - 'locked_order_id')
     IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'version' - 'updated_at' - 'committed_at' - 'released_at' - 'expired_at' - 'locked_order_id') THEN
    RAISE EXCEPTION 'reservation identity and quantity are immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'ACTIVE' AND NEW.status IN ('COMMITTED', 'RELEASED', 'EXPIRED'))
  ) THEN
    RAISE EXCEPTION 'invalid reservation status transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_linked_admin_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP='TRUNCATE' THEN
    IF EXISTS(SELECT 1 FROM public.admin_login_challenges WHERE session_id IS NOT NULL) THEN
      RAISE EXCEPTION 'issued admin sessions cannot be truncated' USING ERRCODE='55000';
    END IF;
    RETURN NULL;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.admin_login_challenges WHERE session_id=OLD.id) THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'issued admin sessions cannot be deleted' USING ERRCODE='55000';
  END IF;
  IF (to_jsonb(NEW)-'last_seen_at'-'revoked_at') IS DISTINCT FROM (to_jsonb(OLD)-'last_seen_at'-'revoked_at')
    OR NOT isfinite(NEW.last_seen_at) OR NEW.last_seen_at<OLD.last_seen_at THEN
    RAISE EXCEPTION 'issued admin session binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at
    OR NEW.revoked_at IS NOT NULL AND NOT isfinite(NEW.revoked_at)
    OR OLD.revoked_at IS NULL AND NEW.revoked_at>clock_timestamp() THEN
    RAISE EXCEPTION 'admin session revocation is final' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_managed_payment_configuration_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE revision uuid; data jsonb:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
BEGIN
 revision:=(data->>'config_version_id')::uuid;
 IF revision IS NULL THEN SELECT config_version_id INTO revision FROM public.payment_route_rules WHERE id=(data->>'payment_route_rule_id')::uuid;END IF;
 IF EXISTS(SELECT 1 FROM public.admin_payment_configuration_revisions WHERE config_version_id=revision) THEN RAISE EXCEPTION 'managed configuration payload is immutable; save a new revision' USING ERRCODE='55000';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;$function$

CREATE OR REPLACE FUNCTION public.guard_management_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE session public.admin_sessions%ROWTYPE;
BEGIN
 IF NEW.intent_hash<>sha256(convert_to(public.canonical_publication_json(NEW.intent),'UTF8')) THEN RAISE EXCEPTION 'operation intent digest must match canonical payload' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.id<>OLD.id OR NEW.actor_id<>OLD.actor_id OR NEW.intent IS DISTINCT FROM OLD.intent OR NEW.intent_hash<>OLD.intent_hash OR NEW.idempotency_key<>OLD.idempotency_key OR NEW.capability<>OLD.capability OR NEW.created_at<>OLD.created_at
  OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at OR OLD.status='SUCCEEDED' THEN RAISE EXCEPTION 'operation identity, intent and completed history are immutable' USING ERRCODE='23514'; END IF;
  IF NEW.session_id<>OLD.session_id OR NEW.authorized_until<>OLD.authorized_until OR NEW.retry_key IS DISTINCT FROM OLD.retry_key THEN
   IF OLD.status<>'FAILED' OR NOT OLD.failure_retryable OR NEW.status<>'QUEUED' OR NEW.retry_key IS NULL OR NEW.retry_key IS NOT DISTINCT FROM OLD.retry_key THEN RAISE EXCEPTION 'operation reauthorization requires exact failed retry' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.lease_token_digest IS DISTINCT FROM OLD.lease_token_digest AND NEW.lease_token_digest IS NOT NULL THEN
   IF (OLD.status='RUNNING' AND OLD.lease_expires_at>clock_timestamp()) OR OLD.status NOT IN('QUEUED','RUNNING') OR NEW.attempt_count<>OLD.attempt_count+1
   OR NEW.lease_expires_at>clock_timestamp()+interval '900 seconds' OR NEW.lease_expires_at>NEW.authorized_until THEN RAISE EXCEPTION 'operation claim requires a due bounded fresh lease' USING ERRCODE='23514'; END IF;
  ELSIF NEW.attempt_count<>OLD.attempt_count THEN RAISE EXCEPTION 'only claiming increments attempts' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.status<>'QUEUED' OR NEW.version<>1 OR NEW.attempt_count<>0 OR NEW.phase<>'PREPARE_MEDIA' OR NEW.retry_key IS NOT NULL OR NEW.checkpoint<>'{"sourceAssetId":null,"jobs":[],"preparedMedia":null,"retryRequested":false}'::jsonb THEN RAISE EXCEPTION 'operation starts with an exact empty durable checkpoint' USING ERRCODE='23514'; END IF;
 END IF;
 -- Expired work may become an honest retryable authorization failure, never a publication.
 IF NEW.status='FAILED' AND NEW.failure_code='NEEDS_AUTHORIZATION' THEN RETURN NEW; END IF;
 SELECT * INTO session FROM public.admin_sessions WHERE id=NEW.session_id FOR SHARE;
 IF session.id IS NULL OR session.admin_identity_id<>NEW.actor_id OR NEW.authorized_until>session.expires_at OR NEW.authorized_until<=clock_timestamp() THEN RAISE EXCEPTION 'operation expiry must be bounded by its actual session' USING ERRCODE='23514'; END IF;
 PERFORM public.assert_admin_catalog_authority(NEW.actor_id,NEW.session_id,clock_timestamp(),NULL,'management.direct',ARRAY[(NEW.intent->>'sourceLocale')::public.supported_locale]);
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_media_processing_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'media attempts cannot be deleted' USING ERRCODE = '55000'; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.status <> 'PROCESSING' OR NEW.status = 'PROCESSING'
      OR (to_jsonb(NEW) - ARRAY['status','finished_at','error_code','error_retryable']) IS DISTINCT FROM
        (to_jsonb(OLD) - ARRAY['status','finished_at','error_code','error_retryable']) THEN
      RAISE EXCEPTION 'media attempt evidence is immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status = 'EXPIRED' AND (OLD.lease_expires_at > statement_timestamp()
      OR NEW.error_code <> 'PROCESSING_TIMEOUT' OR NEW.error_retryable IS DISTINCT FROM true) THEN
      RAISE EXCEPTION 'only expired claims can expire' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.status <> 'PROCESSING' OR NOT EXISTS (
    SELECT 1 FROM public.media_processing_jobs job WHERE job.id = NEW.job_id AND job.status = 'PROCESSING'
      AND job.attempt_count = NEW.attempt_number AND job.lease_token = NEW.lease_token
      AND job.lease_expires_at = NEW.lease_expires_at
  ) THEN RAISE EXCEPTION 'attempt must match claimed job' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_media_processing_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE previous public.media_processing_jobs%ROWTYPE;
BEGIN
  IF NEW.generation=1 THEN RETURN NEW; END IF;
  SELECT * INTO previous FROM public.media_processing_jobs WHERE id=NEW.retry_of_job_id FOR UPDATE;
  IF previous.id IS NULL OR previous.status<>'FAILED' OR NEW.generation<>previous.generation+1
    OR ROW(NEW.source_asset_id,NEW.source_metadata_revision_id,NEW.source_checksum_sha256,NEW.profile_version,NEW.role,NEW.fit,NEW.focal_x,NEW.focal_y,NEW.command_hash)
      IS DISTINCT FROM ROW(previous.source_asset_id,previous.source_metadata_revision_id,previous.source_checksum_sha256,previous.profile_version,previous.role,previous.fit,previous.focal_x,previous.focal_y,previous.command_hash)
    OR NEW.created_at<GREATEST(previous.created_at,previous.updated_at,previous.completed_at)
    OR NEW.created_at>GREATEST(clock_timestamp(),transaction_timestamp(),previous.created_at,previous.updated_at,previous.completed_at) THEN
    RAISE EXCEPTION 'manual retry requires the next generation of its failed immutable recipe' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_media_processing_job()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'PENDING' OR NEW.attempt_count <> 0 OR NEW.error_code IS NOT NULL THEN
      RAISE EXCEPTION 'media processing must begin pending' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.media_assets asset JOIN public.media_metadata_revisions metadata
        ON metadata.media_asset_id = asset.id
      WHERE asset.id = NEW.source_asset_id AND metadata.id = NEW.source_metadata_revision_id
        AND asset.checksum_sha256 = NEW.source_checksum_sha256
        AND asset.identity_kind = 'SOURCE' AND asset.processing_status <> 'ARCHIVED' AND asset.rights_status IN ('PENDING','APPROVED')
        AND asset.byte_size <= 26214400 AND asset.width <= 20000 AND asset.height <= 20000
        AND asset.width::bigint * asset.height <= 40000000 AND metadata.lifecycle <> 'ARCHIVED'
        AND metadata.focal_x = NEW.focal_x AND metadata.focal_y = NEW.focal_y
    ) THEN RAISE EXCEPTION 'media processing source is not eligible' USING ERRCODE = '23514'; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'media processing history cannot be deleted' USING ERRCODE = '55000'; END IF;
  IF (to_jsonb(NEW) - ARRAY['status','attempt_count','lease_token','lease_expires_at','next_attempt_at','error_code','error_retryable','output_asset_id','result_hash','orientation','updated_at','completed_at'])
    IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','attempt_count','lease_token','lease_expires_at','next_attempt_at','error_code','error_retryable','output_asset_id','result_hash','orientation','updated_at','completed_at']) THEN
    RAISE EXCEPTION 'media processing recipe is immutable' USING ERRCODE = '55000';
  END IF;
  IF OLD.status IN ('SUCCEEDED','FAILED') THEN
    IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal media processing is immutable' USING ERRCODE = '55000'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.status = 'PROCESSING' THEN
    IF NOT ((OLD.status = 'PENDING' AND OLD.next_attempt_at <= statement_timestamp())
      OR (OLD.status = 'PROCESSING' AND OLD.lease_expires_at <= statement_timestamp()))
      OR NEW.attempt_count <> OLD.attempt_count + 1 OR NEW.lease_token IS NOT DISTINCT FROM OLD.lease_token
      OR NEW.lease_expires_at < statement_timestamp() + interval '60 seconds'
      OR NEW.lease_expires_at > statement_timestamp() + interval '3600 seconds' THEN
      RAISE EXCEPTION 'media claim must advance an available lease' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.status = 'PENDING' THEN
    IF OLD.status <> 'PROCESSING' OR NEW.attempt_count <> OLD.attempt_count
      OR NEW.error_retryable IS DISTINCT FROM true
      OR NEW.next_attempt_at < statement_timestamp() + make_interval(secs => least(300, power(2,NEW.attempt_count)::integer)) THEN
      RAISE EXCEPTION 'media retry requires bounded backoff' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.status IN ('SUCCEEDED','FAILED') THEN
    IF NEW.attempt_count <> OLD.attempt_count OR (NEW.status = 'SUCCEEDED' AND
      (OLD.status <> 'PROCESSING' OR OLD.lease_expires_at <= statement_timestamp())) THEN
      RAISE EXCEPTION 'media completion requires a current claim' USING ERRCODE = '23514';
    END IF;
    IF NEW.lease_token IS DISTINCT FROM OLD.lease_token OR NEW.lease_expires_at IS DISTINCT FROM OLD.lease_expires_at THEN
      RAISE EXCEPTION 'media completion must preserve claim evidence' USING ERRCODE = '23514';
    END IF;
  ELSE RAISE EXCEPTION 'invalid media transition' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_media_rights_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE asset public.media_assets%ROWTYPE; previous public.media_rights_events%ROWTYPE;
BEGIN
  SELECT * INTO asset FROM public.media_assets WHERE id=NEW.asset_id FOR UPDATE;
  SELECT * INTO previous FROM public.media_rights_events WHERE asset_id=NEW.asset_id ORDER BY version DESC LIMIT 1;
  IF asset.id IS NULL OR NEW.version<>COALESCE(previous.version,0)+1 OR NEW.previous_status<>COALESCE(previous.new_status,asset.rights_status)
    OR asset.rights_status<>NEW.previous_status OR NEW.created_at<GREATEST(asset.created_at,previous.created_at) THEN
    RAISE EXCEPTION 'rights event must advance its locked canonical status and version' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_media_upload_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE session public.admin_sessions%ROWTYPE;
BEGIN
  IF TG_OP='INSERT' THEN
    SELECT * INTO session FROM public.admin_sessions WHERE id=NEW.session_id FOR SHARE;
    IF NEW.status<>'PENDING' OR NEW.version<>1 OR session.id IS NULL OR NEW.expires_at>session.expires_at
      OR NEW.expires_at>clock_timestamp()+interval '900 seconds' OR NEW.created_at>GREATEST(clock_timestamp(),transaction_timestamp(),session.created_at) THEN
      RAISE EXCEPTION 'upload reservation requires a bounded initial ticket' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status<>'PENDING' OR NEW.status<>'REGISTERED' OR NEW.version<>2
    OR to_jsonb(NEW)-ARRAY['status','version','registered_asset_id','registered_at','registration_audit_log_id','verified_width','verified_height','verified_orientation','registration_field_paths']
      IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','version','registered_asset_id','registered_at','registration_audit_log_id','verified_width','verified_height','verified_orientation','registration_field_paths'] THEN
    RAISE EXCEPTION 'upload reservation permits only one immutable registration' USING ERRCODE='55000';
  END IF;
  IF OLD.expires_at<=clock_timestamp() OR NEW.registered_at>GREATEST(clock_timestamp(),transaction_timestamp(),OLD.created_at) THEN
    RAISE EXCEPTION 'upload registration requires an unexpired ticket' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_nonterminal_payment_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_order_id uuid;
  releasing_lock boolean;
BEGIN
  IF TG_TABLE_NAME = 'orders' THEN
    target_order_id := OLD.id;
    releasing_lock := OLD.order_status = 'PENDING_PAYMENT' AND NEW.order_status = 'CANCELED';
  ELSIF TG_TABLE_NAME = 'carts' THEN
    target_order_id := OLD.locked_order_id;
    releasing_lock := OLD.status = 'LOCKED' AND NEW.status = 'EXPIRED';
  ELSE
    target_order_id := OLD.locked_order_id;
    releasing_lock := OLD.status = 'ACTIVE' AND NEW.status IN ('RELEASED', 'EXPIRED');
  END IF;

  IF NOT releasing_lock OR target_order_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM 1 FROM orders WHERE id = target_order_id FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM payment_attempts attempt
    WHERE attempt.order_id = target_order_id
      AND attempt.status IN ('CREATED', 'REQUIRES_ACTION', 'PROCESSING')
  ) THEN
    RAISE EXCEPTION 'nonterminal payment keeps cart and reservation locked'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1 FROM payment_attempts attempt
    WHERE attempt.order_id = target_order_id
      AND attempt.status = 'UNKNOWN'
  ) THEN
    IF TG_TABLE_NAME = 'inventory_reservations' THEN
      IF NEW.status = 'EXPIRED' THEN
        IF statement_timestamp() < OLD.expires_at THEN
          RAISE EXCEPTION 'UNKNOWN reservation expiry requires its elapsed hold window'
            USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
      END IF;
    END IF;

    RAISE EXCEPTION 'nonterminal payment keeps cart and reservation locked'
      USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'inventory_reservations' AND EXISTS (
    SELECT 1 FROM payment_attempts attempt
    WHERE attempt.order_id = target_order_id
      AND attempt.status = 'SUCCEEDED'
  ) THEN
    RAISE EXCEPTION 'succeeded payment cannot release or expire reservations'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_notification_delivery_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.status <> 'REQUESTED' OR NEW.attempt_count <> 0 THEN
      RAISE EXCEPTION 'notification delivery must start REQUESTED with zero attempts'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'notification delivery version must increment exactly once'
      USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW)
        - 'status' - 'attempt_count' - 'next_attempt_at' - 'sent_at'
        - 'last_error_code' - 'version' - 'updated_at')
     IS DISTINCT FROM
     (to_jsonb(OLD)
        - 'status' - 'attempt_count' - 'next_attempt_at' - 'sent_at'
        - 'last_error_code' - 'version' - 'updated_at') THEN
    RAISE EXCEPTION 'notification order, locale, template, and idempotency identity are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NOT (
    (OLD.status = 'REQUESTED' AND NEW.status IN ('PROCESSING', 'CANCELED'))
    OR (OLD.status = 'PROCESSING' AND NEW.status IN ('SENT', 'RETRY_SCHEDULED', 'FAILED'))
    OR (OLD.status = 'RETRY_SCHEDULED' AND NEW.status IN ('PROCESSING', 'CANCELED', 'FAILED'))
  ) THEN
    RAISE EXCEPTION 'invalid notification delivery transition' USING ERRCODE = '23514';
  END IF;
  IF OLD.status = 'PROCESSING' AND NEW.status IN ('SENT', 'RETRY_SCHEDULED', 'FAILED') THEN
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'completed notification attempt must increment attempt count once'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.attempt_count <> OLD.attempt_count THEN
    RAISE EXCEPTION 'notification attempt count may change only after processing'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_order_access_session_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.status <> 'ACTIVE' THEN
      RAISE EXCEPTION 'order access session must start ACTIVE at version one'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'order access session version must increment exactly once'
      USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - 'status' - 'version' - 'last_seen_at' - 'revoked_at' - 'expired_at')
     IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'version' - 'last_seen_at' - 'revoked_at' - 'expired_at') THEN
    RAISE EXCEPTION 'order access session scope and digest are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'ACTIVE' AND NEW.status IN ('REVOKED', 'EXPIRED'))
  ) THEN
    RAISE EXCEPTION 'invalid order access session transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_order_access_token_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.status <> 'ACTIVE' THEN
      RAISE EXCEPTION 'order access token must start ACTIVE at version one'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'order access token version must increment exactly once'
      USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - 'status' - 'version' - 'exchanged_at' - 'revoked_at' - 'expired_at')
     IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'version' - 'exchanged_at' - 'revoked_at' - 'expired_at') THEN
    RAISE EXCEPTION 'order access token identity and digest are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF OLD.status <> 'ACTIVE' OR NEW.status NOT IN ('EXCHANGED', 'REVOKED', 'EXPIRED') THEN
    RAISE EXCEPTION 'invalid order access token transition' USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'EXCHANGED' AND statement_timestamp() >= NEW.expires_at THEN
    RAISE EXCEPTION 'expired order access token cannot be exchanged' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_order_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'order version must increment exactly once' USING ERRCODE = '23514';
  END IF;

  IF (to_jsonb(NEW)
        - 'order_status' - 'payment_status' - 'dispute_status' - 'fulfillment_status'
        - 'current_payment_attempt_id' - 'version' - 'updated_at')
     IS DISTINCT FROM
     (to_jsonb(OLD)
        - 'order_status' - 'payment_status' - 'dispute_status' - 'fulfillment_status'
        - 'current_payment_attempt_id' - 'version' - 'updated_at') THEN
    RAISE EXCEPTION 'order identity and amount snapshot are immutable' USING ERRCODE = '55000';
  END IF;

  IF NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'order updated_at cannot move backwards' USING ERRCODE = '23514';
  END IF;

  IF NOT (
    NEW.order_status = OLD.order_status
    OR (OLD.order_status = 'DRAFT' AND NEW.order_status = 'PENDING_PAYMENT')
    OR (OLD.order_status = 'PENDING_PAYMENT' AND NEW.order_status IN ('OPEN', 'CANCELED'))
    OR (OLD.order_status = 'OPEN' AND NEW.order_status = 'CLOSED')
    OR (OLD.order_status = 'CANCELED' AND NEW.order_status = 'OPEN')
  ) THEN
    RAISE EXCEPTION 'invalid order lifecycle transition' USING ERRCODE = '23514';
  END IF;

  IF NOT (
    NEW.payment_status = OLD.payment_status
    OR (OLD.payment_status = 'UNPAID' AND NEW.payment_status = 'PENDING')
    OR (OLD.payment_status = 'PENDING' AND NEW.payment_status = 'PAID')
    OR (OLD.payment_status = 'PAID' AND NEW.payment_status IN ('PARTIALLY_REFUNDED', 'REFUNDED'))
    OR (OLD.payment_status = 'PARTIALLY_REFUNDED' AND NEW.payment_status = 'REFUNDED')
  ) THEN
    RAISE EXCEPTION 'invalid order payment transition' USING ERRCODE = '23514';
  END IF;

  IF NOT (
    NEW.dispute_status = OLD.dispute_status
    OR (NEW.dispute_status IN ('OPEN','WON','LOST'))
  ) THEN
    RAISE EXCEPTION 'invalid order dispute transition' USING ERRCODE = '23514';
  END IF;

  IF OLD.payment_status IN ('PAID', 'PARTIALLY_REFUNDED', 'REFUNDED')
     AND NEW.current_payment_attempt_id IS DISTINCT FROM OLD.current_payment_attempt_id THEN
    RAISE EXCEPTION 'captured order payment attempt binding is immutable' USING ERRCODE = '55000';
  END IF;

  IF NEW.order_status = OLD.order_status
     AND NEW.payment_status = OLD.payment_status
     AND NEW.dispute_status = OLD.dispute_status
     AND NEW.fulfillment_status = OLD.fulfillment_status
     AND NEW.current_payment_attempt_id IS NOT DISTINCT FROM OLD.current_payment_attempt_id THEN
    RAISE EXCEPTION 'order update must change a versioned aggregate field' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_payment_config_version_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.config_kind <> 'PAYMENT_ROUTING' AND NEW.config_kind <> 'PAYMENT_ROUTING' THEN
    RETURN NEW;
  END IF;
