CREATE OR REPLACE FUNCTION public.guard_payment_route_child_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  route_id uuid;
  parent_lifecycle text;
BEGIN
  route_id := COALESCE(
    (to_jsonb(NEW) ->> 'payment_route_rule_id')::uuid,
    (to_jsonb(OLD) ->> 'payment_route_rule_id')::uuid
  );
  SELECT config.lifecycle INTO parent_lifecycle
    FROM payment_route_rules rule
    JOIN config_versions config ON config.id = rule.config_version_id
    WHERE rule.id = route_id;
  IF parent_lifecycle IN ('PUBLISHED', 'SUPERSEDED', 'ARCHIVED') THEN
    RAISE EXCEPTION 'published payment route payload is immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_payment_runtime_dispatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status_evidence_kind IN('SAFE_EXPIRY','AUDITED_BUSINESS_CANCEL') AND EXISTS(
    SELECT 1 FROM public.payment_runtime_operations operation WHERE operation.attempt_id=NEW.id AND operation.dispatch_authorized
  ) THEN
    RAISE EXCEPTION 'a dispatched payment cannot use pre-provider cancellation or expiry' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_payment_runtime_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.version<>1 OR NEW.generation<>1 OR NEW.phase<>'CREATE' OR NEW.lease_token_digest IS NULL OR NEW.audit_log_id IS NOT NULL OR NEW.lease_expires_at<=clock_timestamp()
      OR NOT EXISTS(SELECT 1 FROM public.payment_attempts a WHERE a.id=NEW.attempt_id AND a.status='CREATED' AND NOT a.provider_call_started) THEN
      RAISE EXCEPTION 'payment runtime must begin with one leased CREATED attempt' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.id<>OLD.id OR NEW.attempt_id<>OLD.attempt_id OR NEW.schema_version<>OLD.schema_version OR NEW.created_at<>OLD.created_at
    OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at OR OLD.phase IN('EVIDENCE_PENDING','COMPLETE')
    OR NEW.generation NOT IN(OLD.generation,OLD.generation+1)
    OR (NEW.phase='CREATE' AND OLD.phase<>'CREATE') THEN
    RAISE EXCEPTION 'payment runtime identity, generation and phase are fenced' USING ERRCODE='23514';
  END IF;
  IF NEW.generation=OLD.generation+1 THEN
    IF OLD.lease_expires_at>clock_timestamp() OR NEW.lease_token_digest IS NULL OR NEW.lease_expires_at<=clock_timestamp() THEN
      RAISE EXCEPTION 'payment runtime cannot replace a live lease' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.lease_token_digest IS NOT NULL AND NEW.lease_token_digest IS DISTINCT FROM OLD.lease_token_digest THEN
    RAISE EXCEPTION 'a replacement payment lease requires a new generation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_publication_head_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_TABLE_SCHEMA <> 'public' THEN
    RAISE EXCEPTION 'publication head guard is restricted to public schema'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'publication heads cannot be deleted' USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 THEN
      RAISE EXCEPTION 'publication head must start at version one' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'publication head update requires one version increment and a later timestamp'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.id <> OLD.id OR NEW.schema_version <> OLD.schema_version
     OR NEW.created_at <> OLD.created_at OR NEW.publication_id = OLD.publication_id THEN
    RAISE EXCEPTION 'publication head identity is immutable and its publication must advance'
      USING ERRCODE = '55000';
  END IF;

  IF TG_TABLE_NAME = 'idol_publication_heads' THEN
    IF NEW.idol_id <> OLD.idol_id OR NEW.idol_revision_id = OLD.idol_revision_id THEN
      RAISE EXCEPTION 'idol publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'gift_publication_heads' THEN
    IF NEW.gift_id <> OLD.gift_id OR NEW.gift_revision_id = OLD.gift_revision_id THEN
      RAISE EXCEPTION 'gift publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'homepage_publication_heads' THEN
    IF NEW.singleton_key <> OLD.singleton_key
       OR NEW.homepage_revision_id = OLD.homepage_revision_id THEN
      RAISE EXCEPTION 'homepage publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'policy_publication_heads' THEN
    IF NEW.policy_key <> OLD.policy_key OR NEW.policy_revision_id = OLD.policy_revision_id THEN
      RAISE EXCEPTION 'policy publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'media_metadata_publication_heads' THEN
    IF NEW.media_asset_id <> OLD.media_asset_id
       OR NEW.media_metadata_revision_id = OLD.media_metadata_revision_id THEN
      RAISE EXCEPTION 'media publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'site_locale_config_publication_heads' THEN
    IF NEW.singleton_key <> OLD.singleton_key
       OR NEW.site_locale_config_revision_id = OLD.site_locale_config_revision_id THEN
      RAISE EXCEPTION 'locale-config publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'price_book_publication_heads' THEN
    IF NEW.market_id <> OLD.market_id OR NEW.market <> OLD.market
       OR NEW.currency <> OLD.currency
       OR (NEW.price_book_id = OLD.price_book_id
           AND NEW.price_book_revision = OLD.price_book_revision) THEN
      RAISE EXCEPTION 'price-book publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSIF TG_TABLE_NAME = 'payment_config_publication_heads' THEN
    IF NEW.singleton_key <> OLD.singleton_key OR NEW.config_kind <> OLD.config_kind
       OR (NEW.config_version_id = OLD.config_version_id
           AND NEW.config_version = OLD.config_version) THEN
      RAISE EXCEPTION 'payment-config publication head owner is immutable and revision must change'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    RAISE EXCEPTION 'unsupported publication head table: %', TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_publication_runtime_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE receipt_id uuid;
BEGIN
  -- Explicit ADR-012 dispatch; all following strict behavior is retained.
  IF EXISTS(SELECT 1 FROM public.daily_publication_revisions WHERE revision_id=NEW.id) THEN
    IF NEW.lifecycle IN('VALIDATED','PUBLISHED') AND NOT EXISTS(SELECT 1 FROM public.daily_publication_manifests WHERE revision_id=NEW.id AND published_at=CASE NEW.lifecycle WHEN 'PUBLISHED' THEN NEW.published_at ELSE NEW.validated_at END) THEN RAISE EXCEPTION 'daily lifecycle requires its exact publication receipt' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.lifecycle=OLD.lifecycle OR NEW.lifecycle NOT IN ('VALIDATED','PUBLISHED') THEN RETURN NEW; END IF;
  SELECT r.id INTO receipt_id FROM public.content_publication_receipts r JOIN public.content_publication_manifests m ON m.id=r.manifest_id
    WHERE coalesce(m.idol_revision_id,m.gift_revision_id,m.homepage_revision_id,m.policy_revision_id,m.media_metadata_revision_id)=NEW.id
      AND r.action=CASE NEW.lifecycle WHEN 'VALIDATED' THEN 'VALIDATE' ELSE 'PUBLISH' END
      AND r.created_at=CASE NEW.lifecycle WHEN 'VALIDATED' THEN NEW.validated_at ELSE NEW.published_at END;
  IF receipt_id IS NULL THEN RAISE EXCEPTION 'new lifecycle transition requires its exact runtime receipt' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_published_price_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
