$function$

CREATE OR REPLACE FUNCTION public.guard_revision_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.lifecycle IN ('PUBLISHED', 'SUPERSEDED', 'ARCHIVED') THEN
      RAISE EXCEPTION 'published revision rows cannot be deleted'
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;

  IF (to_jsonb(NEW) - 'lifecycle' - 'validated_at' - 'published_at' - 'superseded_at' - 'archived_at')
     IS DISTINCT FROM
     (to_jsonb(OLD) - 'lifecycle' - 'validated_at' - 'published_at' - 'superseded_at' - 'archived_at') THEN
    RAISE EXCEPTION 'revision content is immutable; create a new revision'
      USING ERRCODE = '55000';
  END IF;

  IF NOT (
    NEW.lifecycle = OLD.lifecycle
    OR (OLD.lifecycle = 'DRAFT' AND NEW.lifecycle = 'VALIDATED')
    OR (OLD.lifecycle = 'VALIDATED' AND NEW.lifecycle = 'PUBLISHED')
    OR (OLD.lifecycle = 'PUBLISHED' AND NEW.lifecycle = 'SUPERSEDED')
    OR (OLD.lifecycle = 'SUPERSEDED' AND NEW.lifecycle = 'ARCHIVED')
  ) THEN
    RAISE EXCEPTION 'invalid revision lifecycle transition: % -> %', OLD.lifecycle, NEW.lifecycle
      USING ERRCODE = '23514';
  END IF;

  IF NEW.lifecycle = OLD.lifecycle AND (
    NEW.validated_at IS DISTINCT FROM OLD.validated_at
    OR NEW.published_at IS DISTINCT FROM OLD.published_at
    OR NEW.superseded_at IS DISTINCT FROM OLD.superseded_at
    OR NEW.archived_at IS DISTINCT FROM OLD.archived_at
  ) THEN
    RAISE EXCEPTION 'lifecycle timestamps are immutable without a state transition'
      USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_revision_payload_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  parent_id uuid;
  parent_lifecycle text;
BEGIN
  parent_id := COALESCE(
    (to_jsonb(NEW) ->> TG_ARGV[1])::uuid,
    (to_jsonb(OLD) ->> TG_ARGV[1])::uuid
  );
  EXECUTE format('SELECT lifecycle FROM %s WHERE id = $1', TG_ARGV[0]::regclass)
    INTO parent_lifecycle USING parent_id;
  IF parent_lifecycle IN ('PUBLISHED', 'SUPERSEDED', 'ARCHIVED') THEN
    RAISE EXCEPTION 'published revision payload is immutable' USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_revision_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  -- Explicit ADR-012 dispatch; all following strict behavior is retained.
  IF EXISTS(SELECT 1 FROM public.daily_publication_revisions WHERE revision_id=NEW.id) THEN
    IF NEW.lifecycle='PUBLISHED' AND NOT EXISTS(SELECT 1 FROM public.daily_publication_manifests WHERE revision_id=NEW.id AND published_at=NEW.published_at) THEN RAISE EXCEPTION 'daily lifecycle requires its exact publication receipt' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.lifecycle = 'PUBLISHED'
     AND (TG_OP = 'INSERT' OR OLD.lifecycle IS DISTINCT FROM NEW.lifecycle) THEN
    PERFORM assert_translation_package(
      TG_ARGV[0]::regclass,
      TG_ARGV[1],
      NEW.id,
      TG_ARGV[2]::regclass,
      TG_ARGV[3]
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_site_locale_config_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  locale_count integer;
  enabled_count integer;
BEGIN
  IF NEW.lifecycle = 'PUBLISHED'
     AND (TG_OP = 'INSERT' OR OLD.lifecycle IS DISTINCT FROM NEW.lifecycle) THEN
    SELECT count(*), count(*) FILTER (WHERE enabled)
      INTO locale_count, enabled_count
      FROM site_locale_config_entries
      WHERE site_locale_config_revision_id = NEW.id;
    IF locale_count <> 7 OR enabled_count <> 7 THEN
      RAISE EXCEPTION 'published locale config must enable all seven supported locales'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_support_intent_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  private_content_changed boolean;
BEGIN
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'support intent version must increment exactly once' USING ERRCODE = '23514';
  END IF;
  IF NEW.id <> OLD.id OR NEW.cart_item_id <> OLD.cart_item_id OR NEW.idol_id <> OLD.idol_id
     OR NEW.created_presentation_locale <> OLD.created_presentation_locale
     OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'support intent ownership is immutable' USING ERRCODE = '55000';
  END IF;
  IF NOT (
    NEW.privacy_state = OLD.privacy_state
    OR (OLD.privacy_state = 'ACTIVE' AND NEW.privacy_state = 'PURGE_PENDING')
    OR (OLD.privacy_state = 'PURGE_PENDING' AND NEW.privacy_state = 'PURGED')
  ) THEN
    RAISE EXCEPTION 'invalid support intent privacy transition' USING ERRCODE = '23514';
  END IF;
  private_content_changed := (
    NEW.fan_message_ciphertext IS DISTINCT FROM OLD.fan_message_ciphertext
    OR NEW.display_mode <> OLD.display_mode
    OR NEW.display_name_ciphertext IS DISTINCT FROM OLD.display_name_ciphertext
    OR NEW.encrypted_data_key IS DISTINCT FROM OLD.encrypted_data_key
    OR NEW.encryption_key_version IS DISTINCT FROM OLD.encryption_key_version
    OR NEW.fan_message_locale <> OLD.fan_message_locale
  );
  IF OLD.status <> 'ACTIVE' AND private_content_changed
     AND NOT (OLD.privacy_state = 'PURGE_PENDING' AND NEW.privacy_state = 'PURGED') THEN
    RAISE EXCEPTION 'locked support intent private content is immutable' USING ERRCODE = '55000';
  END IF;
  IF OLD.status = 'ACTIVE' AND private_content_changed AND NEW.moderation_status <> 'PENDING' THEN
    RAISE EXCEPTION 'edited private content must return to pending moderation'
      USING ERRCODE = '23514';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'ACTIVE' AND NEW.status IN ('CHECKOUT_LOCKED', 'EXPIRED', 'CANCELED'))
    OR (OLD.status = 'CHECKOUT_LOCKED' AND NEW.status IN ('CONVERTED', 'CANCELED'))
  ) THEN
    RAISE EXCEPTION 'invalid support intent status transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_translation_payload_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  translation_id uuid;
  parent_lifecycle text;
BEGIN
  translation_id := COALESCE(
    (to_jsonb(NEW) ->> TG_ARGV[1])::uuid,
    (to_jsonb(OLD) ->> TG_ARGV[1])::uuid
  );
  EXECUTE format(
    'SELECT p.lifecycle FROM %s t JOIN %s p ON p.id = t.%I WHERE t.id = $1',
    TG_ARGV[0]::regclass,
    TG_ARGV[2]::regclass,
    TG_ARGV[3]
  ) INTO parent_lifecycle USING translation_id;
  IF parent_lifecycle IN ('PUBLISHED', 'SUPERSEDED', 'ARCHIVED') THEN
    RAISE EXCEPTION 'published translation payload is immutable' USING ERRCODE = '55000';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_webhook_payload_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'webhook payload retention rows cannot be deleted'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.created_at <> transaction_timestamp() THEN
      RAISE EXCEPTION 'webhook payload creation time must be server anchored'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - 'status' - 'payload_ciphertext' - 'encrypted_data_key'
      - 'encryption_key_version' - 'purged_at') IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'payload_ciphertext' - 'encrypted_data_key'
      - 'encryption_key_version' - 'purged_at') THEN
    RAISE EXCEPTION 'webhook payload identity and retention evidence are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NOT (OLD.status = 'RETAINED' AND NEW.status = 'PURGED') THEN
    RAISE EXCEPTION 'webhook payloads only support RETAINED to PURGED'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.purged_at <> transaction_timestamp() THEN
    RAISE EXCEPTION 'webhook payload purge time must be server anchored'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.lock_base_content_review_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE parent_id uuid; translation_id uuid;
BEGIN
  translation_id := (to_jsonb(NEW)->>TG_ARGV[1])::uuid;
  EXECUTE format('SELECT %I FROM %s WHERE id=$1',TG_ARGV[3],TG_ARGV[0]::regclass) INTO parent_id USING translation_id;
  EXECUTE format('SELECT id FROM %s WHERE id=$1 FOR UPDATE',TG_ARGV[2]::regclass) USING parent_id;
  EXECUTE format('SELECT id FROM %s WHERE id=$1 FOR UPDATE',TG_ARGV[0]::regclass) USING translation_id;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.managed_payment_document_is_safe(doc jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE c jsonb;t jsonb;r jsonb;h jsonb;value text; field text;
BEGIN
 IF NOT coalesce(jsonb_typeof(doc)='object' AND doc->'schemaVersion'='1'::jsonb AND jsonb_typeof(doc->'channels')='array' AND jsonb_typeof(doc->'routes')='array' AND doc-ARRAY['schemaVersion','channels','routes']='{}'::jsonb,false) THEN RETURN false;END IF;
 IF jsonb_array_length(doc->'channels')>100 OR jsonb_array_length(doc->'routes')>200 THEN RETURN false;END IF;
 FOR c IN SELECT x FROM jsonb_array_elements(doc->'channels') x LOOP
  h:=c->'healthPolicy';
  IF EXISTS(SELECT 1 FROM jsonb_each(h) e WHERE jsonb_typeof(e.value)<>'number' OR (e.value::text)::numeric<>trunc((e.value::text)::numeric)) THEN RETURN false;END IF;
  IF NOT coalesce(c-ARRAY['providerAccountId','enabled','displayOrder','rolloutBasisPoints','healthPolicy','translations']='{}'::jsonb AND (c->>'providerAccountId')::uuid IS NOT NULL AND jsonb_typeof(c->'enabled')='boolean' AND jsonb_typeof(c->'displayOrder')='number' AND (c->>'displayOrder')::numeric BETWEEN 0 AND 2147483647 AND (c->>'displayOrder')::numeric=trunc((c->>'displayOrder')::numeric) AND jsonb_typeof(c->'rolloutBasisPoints')='number' AND (c->>'rolloutBasisPoints')::numeric BETWEEN 0 AND 10000 AND (c->>'rolloutBasisPoints')::numeric=trunc((c->>'rolloutBasisPoints')::numeric) AND jsonb_typeof(c->'translations')='array' AND jsonb_array_length(c->'translations')<=7 AND jsonb_typeof(h)='object' AND h-ARRAY['failureThreshold','failureWindowMs','openDurationMs','probeLeaseMs','probeRetryMs']='{}'::jsonb AND (h->>'failureThreshold')::integer BETWEEN 1 AND 100 AND (h->>'failureWindowMs')::integer BETWEEN 1000 AND 3600000 AND (h->>'openDurationMs')::integer BETWEEN 1000 AND 86400000 AND (h->>'probeLeaseMs')::integer BETWEEN 1000 AND 120000 AND (h->>'probeRetryMs')::integer BETWEEN 1000 AND 86400000,false) THEN RETURN false;END IF;
  FOR t IN SELECT x FROM jsonb_array_elements(c->'translations') x LOOP
   IF jsonb_typeof(t->'locale') IS DISTINCT FROM 'string' OR NOT coalesce(t->'translatedFromSourceHash'='null'::jsonb OR jsonb_typeof(t->'translatedFromSourceHash')='string',false) THEN RETURN false;END IF;
   IF NOT coalesce(t-ARRAY['locale','displayName','customerHint','translatedFromSourceHash']='{}'::jsonb AND (t->>'locale')::public.supported_locale IS NOT NULL AND jsonb_typeof(t->'displayName')='string' AND length(t->>'displayName') BETWEEN 1 AND 80 AND jsonb_typeof(t->'customerHint')='string' AND length(t->>'customerHint') BETWEEN 1 AND 280 AND (t->'translatedFromSourceHash'='null'::jsonb OR t->>'translatedFromSourceHash' ~ '^[a-f0-9]{64}$'),false) THEN RETURN false;END IF;
  END LOOP;
  IF (SELECT count(DISTINCT x->>'locale') FROM jsonb_array_elements(c->'translations') x)<>jsonb_array_length(c->'translations') THEN RETURN false;END IF;
 END LOOP;
 IF (SELECT count(DISTINCT (x->>'providerAccountId')::uuid) FROM jsonb_array_elements(doc->'channels') x)<>jsonb_array_length(doc->'channels') THEN RETURN false;END IF;
 FOR r IN SELECT x FROM jsonb_array_elements(doc->'routes') x LOOP
  IF jsonb_typeof(r->'ruleKey') IS DISTINCT FROM 'string' OR jsonb_typeof(r->'paymentMethod') IS DISTINCT FROM 'string' THEN RETURN false;END IF;
  FOREACH field IN ARRAY ARRAY['minimumAmountMinor','maximumAmountMinor','priority','rolloutBasisPoints'] LOOP
   IF jsonb_typeof(r->field) IS DISTINCT FROM 'number' OR (r->>field)::numeric<>trunc((r->>field)::numeric) THEN RETURN false;END IF;
  END LOOP;
  IF NOT coalesce(r-ARRAY['ruleKey','providerAccountId','paymentMethod','enabled','countries','markets','currencies','minimumAmountMinor','maximumAmountMinor','requiredDeviceCapabilities','priority','rolloutBasisPoints']='{}'::jsonb AND r->>'ruleKey' ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' AND (r->>'providerAccountId')::uuid IS NOT NULL AND r->>'paymentMethod' ~ '^[a-z0-9][a-z0-9_-]{0,63}$' AND jsonb_typeof(r->'enabled')='boolean' AND (r->>'minimumAmountMinor')::public.minor_amount IS NOT NULL AND (r->>'maximumAmountMinor')::public.minor_amount IS NOT NULL AND (r->>'priority')::integer IS NOT NULL AND (r->>'rolloutBasisPoints')::integer BETWEEN 0 AND 10000 AND jsonb_typeof(r->'countries')='array' AND jsonb_typeof(r->'markets')='array' AND jsonb_typeof(r->'currencies')='array' AND jsonb_typeof(r->'requiredDeviceCapabilities')='array',false) THEN RETURN false;END IF;
  FOR value IN SELECT jsonb_array_elements_text(r->'countries') LOOP PERFORM value::public.country_code;END LOOP;
  FOR value IN SELECT jsonb_array_elements_text(r->'markets') LOOP PERFORM value::public.market_code;END LOOP;
  FOR value IN SELECT jsonb_array_elements_text(r->'currencies') LOOP PERFORM value::public.currency_code;END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(r->'requiredDeviceCapabilities') capability(element) WHERE capability.element NOT IN('REDIRECT','QR_CODE','PROVIDER_HOSTED_IFRAME','PROVIDER_COMPONENT')) THEN RETURN false;END IF;
  FOREACH field IN ARRAY ARRAY['countries','markets','currencies','requiredDeviceCapabilities'] LOOP
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(r->field) e WHERE jsonb_typeof(e)<>'string') OR (SELECT count(DISTINCT e) FROM jsonb_array_elements(r->field) e)<>jsonb_array_length(r->field) OR jsonb_array_length(r->field)>(CASE field WHEN 'countries' THEN 250 WHEN 'requiredDeviceCapabilities' THEN 4 ELSE 100 END) THEN RETURN false;END IF;
  END LOOP;
 END LOOP;
 RETURN (SELECT count(DISTINCT x->>'ruleKey') FROM jsonb_array_elements(doc->'routes') x)=jsonb_array_length(doc->'routes');
EXCEPTION WHEN OTHERS THEN RETURN false;
END;$function$

CREATE OR REPLACE FUNCTION public.payment_rollout_bucket_v1(scope text, checkout uuid, target uuid)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  bytes bytea;
  hash bigint := 2166136261;
  byte_index integer;
  mix_round integer;
BEGIN
  IF scope NOT IN ('provider','rule') THEN
    RAISE EXCEPTION 'Invalid payment rollout scope' USING ERRCODE='22023';
  END IF;
  bytes := convert_to('payment-rollout:v1:'||scope||':'||checkout::text||':'||target::text,'UTF8');
  FOR byte_index IN 0..octet_length(bytes)-1 LOOP
    hash := mod((hash # get_byte(bytes,byte_index))::numeric * 16777619,4294967296)::bigint;
  END LOOP;
  FOR mix_round IN 1..2 LOOP
    hash := mod((hash # (hash >> 16))::numeric * 73244475,4294967296)::bigint;
  END LOOP;
  RETURN ((hash # (hash >> 16)) % 10000)::integer;
END;
$function$

CREATE OR REPLACE FUNCTION public.publication_legacy_snapshot_json(value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE result text;
BEGIN
  CASE jsonb_typeof(value)
    WHEN 'object' THEN
      SELECT '{'||coalesce(string_agg(to_json(key)::text||':'||public.publication_legacy_snapshot_json(child),',' ORDER BY key COLLATE "C"),'')||'}'
      INTO result FROM jsonb_each(value) AS entry(key,child);
    WHEN 'array' THEN
      SELECT '['||coalesce(string_agg(public.publication_legacy_snapshot_json(child),',' ORDER BY position),'')||']'
      INTO result FROM jsonb_array_elements(value) WITH ORDINALITY AS entry(child,position);
    WHEN 'string' THEN result:=to_json(normalize(value#>>'{}',NFC))::text;
    WHEN 'number' THEN result:=public.publication_legacy_json_number(value);
    ELSE result:=value::text;
  END CASE;
  RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.publication_media_references(value jsonb)
 RETURNS TABLE(asset_id uuid, metadata_id uuid)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE kind text:=value#>>'{target,kind}'; target_revision uuid:=(value->>'revisionId')::uuid;
BEGIN
 IF kind='IDOL' THEN RETURN QUERY SELECT media_asset_id,media_metadata_revision_id FROM public.idol_revision_media WHERE idol_revision_id=target_revision;
 ELSIF kind='GIFT' THEN
  RETURN QUERY SELECT media_asset_id,media_metadata_revision_id FROM public.gift_revision_media WHERE gift_revision_id=target_revision UNION SELECT b.media_asset_id,b.media_metadata_revision_id FROM public.gift_detail_documents d JOIN public.gift_detail_blocks b ON b.document_id=d.id WHERE d.gift_revision_id=target_revision AND b.kind='MEDIA';
 ELSIF kind='HOMEPAGE' THEN
  RETURN QUERY SELECT desktop_media_asset_id,desktop_media_metadata_revision_id FROM public.homepage_slots h WHERE homepage_revision_id=target_revision AND h.kind='HERO_IDOL' UNION SELECT mobile_media_asset_id,mobile_media_metadata_revision_id FROM public.homepage_slots h WHERE homepage_revision_id=target_revision AND h.kind='HERO_IDOL';
 ELSIF kind='MEDIA_METADATA' THEN RETURN QUERY SELECT media_asset_id,id FROM public.media_metadata_revisions WHERE id=target_revision;
 END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.publication_pick_fields(row_value jsonb, field_names text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE result jsonb:='{}'; field text; source text; value jsonb;
BEGIN
  FOREACH field IN ARRAY field_names LOOP
    source:=lower(regexp_replace(field,'([A-Z])','_\1','g'));
    value:=row_value->source;
    IF value IS NOT NULL AND value<>'null'::jsonb THEN result:=result||jsonb_build_object(field,value); END IF;
  END LOOP;
  RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.publication_snapshot_payload(value jsonb, lifecycle jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE kind text:=value#>>'{target,kind}'; revision_id uuid:=(value->>'revisionId')::uuid; prefix text; parent_column text; translation_column text;
  parent jsonb; translation jsonb; review jsonb; source jsonb; audit jsonb; fields jsonb; item jsonb; content jsonb:=value->'content'; extensions jsonb:=value->'extensions';
  translations jsonb:='[]'; audits jsonb:='[]'; rows jsonb; detail_translations jsonb:='[]'; text_details jsonb:='[]'; blocks jsonb; block jsonb; items jsonb;
BEGIN
  PERFORM public.assert_publication_manifest_revision(value);
  prefix:=lower(kind); parent_column:=prefix||'_revision_id'; translation_column:=prefix||'_translation_id';
  EXECUTE format('SELECT to_jsonb(p.*) FROM public.%I p WHERE id=$1',prefix||'_revisions') INTO parent USING revision_id;
  FOR translation,review IN EXECUTE format('SELECT to_jsonb(t.*),to_jsonb(r.*) FROM public.%I t JOIN LATERAL(SELECT * FROM public.%I WHERE %I=t.id ORDER BY sequence DESC LIMIT 1) r ON true WHERE t.%I=$1 ORDER BY t.locale',prefix||'_revision_translations',prefix||'_translation_reviews',translation_column,parent_column) USING revision_id LOOP
    SELECT entry INTO source FROM jsonb_array_elements(content->'translations') entry WHERE entry->>'locale'=translation->>'locale';
    fields:=source->'fields';
    IF kind='GIFT' THEN
      SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['giftVariantId','label']) ORDER BY gift_variant_id),'[]') INTO rows FROM public.gift_variant_labels r WHERE gift_translation_id=(translation->>'id')::uuid;
      fields:=jsonb_set(fields,'{variantLabels}',rows);
    ELSIF kind='HOMEPAGE' THEN
      SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['slotKey','label']) ORDER BY slot_key),'[]') INTO rows FROM public.homepage_slot_translations r WHERE homepage_translation_id=(translation->>'id')::uuid;
      fields:=jsonb_set(fields,'{slotLabels}',rows);
    END IF;
    translations:=translations||jsonb_build_array(jsonb_set(source,'{fields}',fields));
    SELECT entry INTO audit FROM jsonb_array_elements(value->'translationAudits') entry WHERE entry->>'locale'=translation->>'locale';
    audit:=jsonb_set(audit,'{editedAt}',translation->'edited_at');
    audit:=jsonb_set(audit,'{review}',jsonb_build_object('status',review->'status')||public.publication_pick_fields(review,ARRAY['submittedAt','reviewerId','reviewedAt','reviewedSourceHash','reviewedContentHash']));
    audits:=audits||jsonb_build_array(audit);
  END LOOP;
  content:=jsonb_set(content,'{translations}',translations);
  IF kind IN ('IDOL','GIFT') THEN
    EXECUTE format('SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY[''role'',''mediaAssetId'',''mediaMetadataRevisionId'',''sortOrder'']) ORDER BY role,sort_order),''[]'') FROM public.%I r WHERE %I=$1',prefix||'_revision_media',parent_column) INTO rows USING revision_id;
    content:=jsonb_set(content,'{media}',rows);
  END IF;
  IF kind='IDOL' AND extensions ? 'aliases' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.alias_id,'locale',a.locale,'text',a.text) ORDER BY a.position),'[]') INTO rows
      FROM public.idol_revision_aliases a JOIN public.idol_revision_alias_sets s ON s.id=a.alias_set_id WHERE s.idol_revision_id=revision_id;
    content:=jsonb_set(content,'{aliases}',rows); extensions:=jsonb_set(extensions,'{aliases,aliases}',rows);
  ELSIF kind='GIFT' THEN
    SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['componentCode','quantity','unit']) ORDER BY component_code),'[]') INTO rows FROM public.gift_revision_contents r WHERE gift_revision_id=revision_id;
    content:=jsonb_set(content,'{structure,contents}',rows);
    IF extensions ? 'details' THEN
      FOR item IN SELECT entry FROM jsonb_array_elements(extensions#>'{details,translations}') entry ORDER BY (entry->>'locale')::public.supported_locale LOOP
        blocks:='[]';
        FOR block IN SELECT entry FROM jsonb_array_elements(item->'blocks') entry ORDER BY entry->>'blockId' LOOP
          IF block->>'kind' IN ('LIST','SPECIFICATIONS') THEN
            SELECT jsonb_agg(entry ORDER BY entry->>'itemId') INTO items FROM jsonb_array_elements(block->'items') entry;
            block:=jsonb_set(block,'{items}',items);
          END IF;
          blocks:=blocks||jsonb_build_array(block);
        END LOOP;
        item:=jsonb_set(item,'{blocks}',blocks);
        detail_translations:=detail_translations||jsonb_build_array(item);
        text_details:=text_details||jsonb_build_array((item-ARRAY['schemaVersion','id','documentId','giftRevisionId','sourceHash','translatedFromSourceHash','editorId','editedAt','review']));
      END LOOP;
      extensions:=jsonb_set(extensions,'{details,translations}',detail_translations);
      content:=jsonb_set(content,'{details,translations}',text_details);
    END IF;
  ELSIF kind='HOMEPAGE' THEN
    SELECT coalesce(jsonb_agg(public.publication_pick_fields(to_jsonb(r.*),ARRAY['slotKey','kind','idolId','giftId','policyKey','desktopMediaAssetId','desktopMediaMetadataRevisionId','mobileMediaAssetId','mobileMediaMetadataRevisionId','sortOrder']) ORDER BY sort_order),'[]') INTO rows FROM public.homepage_slots r WHERE homepage_revision_id=revision_id;
    content:=jsonb_set(content,'{structure,slots}',rows);
  ELSIF kind='POLICY' THEN
    content:=jsonb_set(content,'{structure,effectiveAt}',parent->'effective_at');
  END IF;
  RETURN jsonb_set(jsonb_set(jsonb_set(jsonb_set(value,'{createdAt}',parent->'created_at'),'{content}',content),'{translationAudits}',audits),'{extensions}',extensions)
    ||jsonb_build_object('lifecycle',lifecycle);
END; $function$

CREATE OR REPLACE FUNCTION public.validate_content_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_lifecycle text;
  previous_type text;
  previous_owner text;
  current_owner text;
  media_revision record;
  required_media_count integer;
  required_row_count integer;
  present_row_count integer;
BEGIN
  -- Explicit ADR-012 dispatch; all following strict behavior is retained.
  IF NEW.proof_version=3 THEN
    IF NEW.content_type NOT IN('IDOL','GIFT','HOMEPAGE','MEDIA_METADATA') OR NOT EXISTS(SELECT 1 FROM public.daily_publication_manifests WHERE publication_id=NEW.id AND revision_id=coalesce(NEW.idol_revision_id,NEW.gift_revision_id,NEW.homepage_revision_id,NEW.media_metadata_revision_id) AND actor_id=NEW.published_by AND published_at=NEW.published_at) THEN RAISE EXCEPTION 'daily event requires exact supported receipt' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.id = NEW.replaces_publication_id THEN
    RAISE EXCEPTION 'publication cannot replace itself' USING ERRCODE = '23514';
  END IF;

  IF NEW.content_type = 'IDOL' THEN
    SELECT lifecycle INTO target_lifecycle FROM idol_revisions WHERE id = NEW.idol_revision_id;
    current_owner := NEW.idol_id::text;
    PERFORM assert_translation_package(
      'idol_revision_translations', 'idol_revision_id', NEW.idol_revision_id,
      'idol_translation_reviews', 'idol_translation_id'
    );
    SELECT count(*) INTO required_media_count
      FROM (
        SELECT role FROM idol_revision_media
        WHERE idol_revision_id = NEW.idol_revision_id
          AND role IN ('PORTRAIT', 'HERO_DESKTOP', 'HERO_MOBILE')
        GROUP BY role
      ) required_roles;
    IF required_media_count <> 3 THEN
      RAISE EXCEPTION 'idol publication requires portrait, desktop hero, and mobile hero media'
        USING ERRCODE = '23514';
    END IF;
    FOR media_revision IN
      SELECT DISTINCT m.id, m.lifecycle, asset.processing_status, asset.rights_status,
        EXISTS (
          SELECT 1 FROM media_variants variant
          WHERE variant.media_asset_id = asset.id AND variant.status = 'READY'
        ) AS has_ready_variant
      FROM idol_revision_media irm
      JOIN media_metadata_revisions m ON m.id = irm.media_metadata_revision_id
      JOIN media_assets asset ON asset.id = irm.media_asset_id
      WHERE idol_revision_id = NEW.idol_revision_id
    LOOP
      IF media_revision.lifecycle NOT IN ('PUBLISHED', 'SUPERSEDED')
         OR media_revision.processing_status <> 'READY'
         OR media_revision.rights_status <> 'APPROVED'
         OR NOT media_revision.has_ready_variant THEN
        RAISE EXCEPTION 'publication media metadata must be immutable published evidence'
          USING ERRCODE = '23514';
      END IF;
      PERFORM assert_translation_package(
        'media_metadata_revision_translations', 'media_metadata_revision_id', media_revision.id,
        'media_metadata_translation_reviews', 'media_metadata_translation_id'
      );
    END LOOP;
  ELSIF NEW.content_type = 'GIFT' THEN
    SELECT lifecycle INTO target_lifecycle FROM gift_revisions WHERE id = NEW.gift_revision_id;
    current_owner := NEW.gift_id::text;
    PERFORM assert_translation_package(
      'gift_revision_translations', 'gift_revision_id', NEW.gift_revision_id,
      'gift_translation_reviews', 'gift_translation_id'
    );
    SELECT count(*), count(*) FILTER (WHERE EXISTS (
      SELECT 1 FROM gift_variant_idol_eligibility eligibility
      JOIN idols idol ON idol.id = eligibility.idol_id
      WHERE eligibility.gift_variant_id = variant.id
        AND idol.status = 'active' AND idol.accepting_gifts
        AND idol.published_revision_id IS NOT NULL
    ))
      INTO required_row_count, present_row_count
      FROM gift_variants variant
      WHERE variant.gift_id = NEW.gift_id AND variant.status <> 'archived';
    IF required_row_count = 0 OR present_row_count <> required_row_count THEN
      RAISE EXCEPTION 'gift publication requires a published eligible idol for every non-archived variant'
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM gift_variants
      WHERE gift_id = NEW.gift_id AND status IN ('active', 'paused')
    ) OR (
      (SELECT status FROM gifts WHERE id = NEW.gift_id) = 'active'
      AND NOT EXISTS (
        SELECT 1 FROM gift_variants
        WHERE gift_id = NEW.gift_id AND status = 'active'
      )
    ) THEN
      RAISE EXCEPTION 'gift publication requires a usable variant'
        USING ERRCODE = '23514';
    END IF;
    SELECT count(*) * 7 INTO required_row_count
      FROM gift_variants WHERE gift_id = NEW.gift_id;
    SELECT count(*) INTO present_row_count
      FROM gift_variant_labels label
      JOIN gift_revision_translations translation ON translation.id = label.gift_translation_id
      JOIN gift_variants variant ON variant.id = label.gift_variant_id
      WHERE translation.gift_revision_id = NEW.gift_revision_id
        AND variant.gift_id = NEW.gift_id;
    IF present_row_count <> required_row_count THEN
      RAISE EXCEPTION 'gift publication requires every variant label in all seven locales'
        USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
      SELECT 1 FROM gift_revisions revision
      JOIN gift_revision_translations translation
        ON translation.gift_revision_id = revision.id
      WHERE revision.id = NEW.gift_revision_id
        AND revision.requires_safety_notice
        AND translation.safety_notice IS NULL
    ) THEN
      RAISE EXCEPTION 'gift publication requires localized safety notices'
        USING ERRCODE = '23514';
    END IF;
    SELECT count(*) INTO required_media_count FROM gift_revision_media
      WHERE gift_revision_id = NEW.gift_revision_id AND role = 'PRIMARY';
    IF required_media_count < 1 THEN
      RAISE EXCEPTION 'gift publication requires primary media' USING ERRCODE = '23514';
    END IF;
    FOR media_revision IN
      SELECT DISTINCT m.id, m.lifecycle, asset.processing_status, asset.rights_status,
        EXISTS (
          SELECT 1 FROM media_variants variant
          WHERE variant.media_asset_id = asset.id AND variant.status = 'READY'
        ) AS has_ready_variant
      FROM gift_revision_media grm
      JOIN media_metadata_revisions m ON m.id = grm.media_metadata_revision_id
      JOIN media_assets asset ON asset.id = grm.media_asset_id
      WHERE gift_revision_id = NEW.gift_revision_id
    LOOP
      IF media_revision.lifecycle NOT IN ('PUBLISHED', 'SUPERSEDED')
         OR media_revision.processing_status <> 'READY'
         OR media_revision.rights_status <> 'APPROVED'
         OR NOT media_revision.has_ready_variant THEN
        RAISE EXCEPTION 'publication media metadata must be immutable published evidence'
          USING ERRCODE = '23514';
      END IF;
      PERFORM assert_translation_package(
        'media_metadata_revision_translations', 'media_metadata_revision_id', media_revision.id,
        'media_metadata_translation_reviews', 'media_metadata_translation_id'
      );
    END LOOP;
  ELSIF NEW.content_type = 'HOMEPAGE' THEN
    SELECT lifecycle INTO target_lifecycle FROM homepage_revisions WHERE id = NEW.homepage_revision_id;
    current_owner := 'homepage';
    PERFORM assert_translation_package(
      'homepage_revision_translations', 'homepage_revision_id', NEW.homepage_revision_id,
      'homepage_translation_reviews', 'homepage_translation_id'
    );
    SELECT count(*) INTO required_media_count FROM homepage_slots
      WHERE homepage_revision_id = NEW.homepage_revision_id AND kind = 'HERO_IDOL';
    IF required_media_count <> 1 THEN
      RAISE EXCEPTION 'homepage publication requires exactly one hero idol slot'
        USING ERRCODE = '23514';
    END IF;
    SELECT count(*) * 7 INTO required_row_count
      FROM homepage_slots WHERE homepage_revision_id = NEW.homepage_revision_id;
    SELECT count(*) INTO present_row_count
      FROM homepage_slot_translations label
      JOIN homepage_revision_translations translation
        ON translation.id = label.homepage_translation_id
      WHERE translation.homepage_revision_id = NEW.homepage_revision_id;
    IF present_row_count <> required_row_count THEN
      RAISE EXCEPTION 'homepage publication requires every slot label in all seven locales'
        USING ERRCODE = '23514';
    END IF;
    FOR media_revision IN
      SELECT DISTINCT m.id, m.lifecycle, asset.processing_status, asset.rights_status,
        EXISTS (
          SELECT 1 FROM media_variants variant
          WHERE variant.media_asset_id = asset.id AND variant.status = 'READY'
        ) AS has_ready_variant
      FROM (
        SELECT desktop_media_metadata_revision_id AS id, desktop_media_asset_id AS asset_id
          FROM homepage_slots WHERE homepage_revision_id = NEW.homepage_revision_id
        UNION
        SELECT mobile_media_metadata_revision_id AS id, mobile_media_asset_id AS asset_id
          FROM homepage_slots WHERE homepage_revision_id = NEW.homepage_revision_id
      ) slot_media
      JOIN media_metadata_revisions m ON m.id = slot_media.id
      JOIN media_assets asset ON asset.id = slot_media.asset_id
      WHERE slot_media.id IS NOT NULL
    LOOP
      IF media_revision.lifecycle NOT IN ('PUBLISHED', 'SUPERSEDED')
         OR media_revision.processing_status <> 'READY'
         OR media_revision.rights_status <> 'APPROVED'
         OR NOT media_revision.has_ready_variant THEN
        RAISE EXCEPTION 'publication media metadata must be immutable published evidence'
          USING ERRCODE = '23514';
      END IF;
      PERFORM assert_translation_package(
        'media_metadata_revision_translations', 'media_metadata_revision_id', media_revision.id,
        'media_metadata_translation_reviews', 'media_metadata_translation_id'
      );
    END LOOP;
  ELSIF NEW.content_type = 'POLICY' THEN
    SELECT lifecycle INTO target_lifecycle FROM policy_revisions WHERE id = NEW.policy_revision_id;
    current_owner := NEW.policy_key;
    PERFORM assert_translation_package(
      'policy_revision_translations', 'policy_revision_id', NEW.policy_revision_id,
      'policy_translation_reviews', 'policy_translation_id'
    );
  ELSIF NEW.content_type = 'MEDIA_METADATA' THEN
    SELECT metadata.lifecycle INTO target_lifecycle
      FROM media_metadata_revisions metadata
      JOIN media_assets asset ON asset.id = metadata.media_asset_id
      WHERE metadata.id = NEW.media_metadata_revision_id
        AND asset.processing_status = 'READY'
        AND asset.rights_status = 'APPROVED'
        AND EXISTS (
          SELECT 1 FROM media_variants variant
          WHERE variant.media_asset_id = asset.id AND variant.status = 'READY'
        );
    current_owner := NEW.media_asset_id::text;
    PERFORM assert_translation_package(
      'media_metadata_revision_translations', 'media_metadata_revision_id', NEW.media_metadata_revision_id,
      'media_metadata_translation_reviews', 'media_metadata_translation_id'
    );
  ELSE
    SELECT lifecycle INTO target_lifecycle FROM site_locale_config_revisions
      WHERE id = NEW.site_locale_config_revision_id;
    current_owner := 'site-locale-config';
  END IF;

  IF target_lifecycle NOT IN ('PUBLISHED', 'SUPERSEDED') THEN
    RAISE EXCEPTION 'publication target must be immutable published evidence'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.replaces_publication_id IS NOT NULL THEN
    SELECT content_type,
      CASE content_type
        WHEN 'IDOL' THEN idol_id::text
        WHEN 'GIFT' THEN gift_id::text
        WHEN 'HOMEPAGE' THEN 'homepage'
        WHEN 'POLICY' THEN policy_key
        WHEN 'MEDIA_METADATA' THEN media_asset_id::text
        ELSE 'site-locale-config'
      END
      INTO previous_type, previous_owner
      FROM content_publications WHERE id = NEW.replaces_publication_id;
    IF previous_type IS NULL OR previous_type <> NEW.content_type OR previous_owner <> current_owner THEN
      RAISE EXCEPTION 'publication replacement must stay on the same typed object'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_dispute_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  attempt_status text;
  captured_amount minor_amount;
  captured_currency currency_code;
  transition_allowed boolean;
BEGIN
  SELECT status, amount_minor, currency
    INTO attempt_status, captured_amount, captured_currency FROM payment_attempts
    WHERE id = NEW.payment_attempt_id AND order_id = NEW.order_id;
  IF attempt_status <> 'SUCCEEDED' OR NEW.currency <> captured_currency
     OR NEW.amount_minor > captured_amount THEN
    RAISE EXCEPTION 'dispute requires a captured SUCCEEDED payment attempt'
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 THEN
      RAISE EXCEPTION 'new dispute must start at version 1' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'NONE' THEN
      IF NEW.status_evidence_kind <> 'DISPUTE_PLACEHOLDER'
         OR NEW.provider_event_id IS NOT NULL OR NEW.evidence_audit_log_id IS NOT NULL THEN
        RAISE EXCEPTION 'NONE dispute is only an evidence-free placeholder'
          USING ERRCODE = '23514';
      END IF;
    ELSIF NEW.status_evidence_kind NOT IN ('VERIFIED_WEBHOOK', 'AUTHENTICATED_RECONCILE') THEN
      RAISE EXCEPTION 'opened dispute requires trusted provider evidence'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    IF (to_jsonb(NEW) - 'status' - 'status_evidence_kind' - 'provider_event_id'
        - 'evidence_audit_log_id' - 'version' - 'updated_at' - 'opened_at')
       IS DISTINCT FROM
       (to_jsonb(OLD) - 'status' - 'status_evidence_kind' - 'provider_event_id'
        - 'evidence_audit_log_id' - 'version' - 'updated_at' - 'opened_at') THEN
      RAISE EXCEPTION 'dispute identity, provider reference, amount, and currency are immutable'
        USING ERRCODE = '55000';
    END IF;
    IF OLD.status IN ('WON', 'LOST') THEN
      RAISE EXCEPTION 'terminal disputes are immutable' USING ERRCODE = '55000';
    END IF;
    transition_allowed := CASE OLD.status
      WHEN 'NONE' THEN NEW.status IN ('OPEN', 'WON', 'LOST')
      WHEN 'OPEN' THEN NEW.status IN ('WON', 'LOST')
      ELSE false
    END;
    IF NEW.status = OLD.status OR NOT transition_allowed
       OR NEW.status_evidence_kind NOT IN ('VERIFIED_WEBHOOK', 'AUTHENTICATED_RECONCILE')
       OR NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
      RAISE EXCEPTION 'invalid dispute transition: % -> %', OLD.status, NEW.status
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.status_evidence_kind IN ('VERIFIED_WEBHOOK', 'AUTHENTICATED_RECONCILE')
     AND NEW.provider_event_id IS NULL THEN
    RAISE EXCEPTION 'trusted dispute evidence requires provider_event_id'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind = 'VERIFIED_WEBHOOK'
        AND NEW.evidence_audit_log_id IS NOT NULL THEN
    RAISE EXCEPTION 'verified dispute webhook cannot carry reconcile audit evidence'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind = 'AUTHENTICATED_RECONCILE'
        AND NEW.evidence_audit_log_id IS NULL THEN
    RAISE EXCEPTION 'reconciled dispute requires its audit_log_id'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_fulfillment_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  previous_event fulfillment_events%ROWTYPE;
BEGIN
  IF NEW.authority_kind = 'ADMIN' THEN
    PERFORM 1 FROM audit_logs audit
    WHERE audit.id = NEW.audit_log_id
    FOR UPDATE;

    IF NOT EXISTS (
      SELECT 1 FROM audit_logs audit
      WHERE audit.id = NEW.audit_log_id
        AND audit.actor_type = 'ADMIN'
        AND audit.actor_id = NEW.admin_identity_id
        AND audit.action = 'FULFILLMENT_STATUS_CHANGED'
        AND audit.subject_type = 'FULFILLMENT'
        AND audit.subject_id = NEW.fulfillment_id
        AND audit.reason_code = NEW.reason_code
        AND audit.request_id = NEW.request_id
        AND audit.correlation_id = NEW.correlation_id
        AND audit.outcome = 'SUCCEEDED'
        AND audit.created_at = NEW.occurred_at
        AND NEW.occurred_at = transaction_timestamp()
    ) THEN
      RAISE EXCEPTION 'admin fulfillment event requires exact fresh successful audit evidence'
        USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
      SELECT 1 FROM order_events event WHERE event.audit_log_id = NEW.audit_log_id
      UNION ALL
      SELECT 1 FROM fulfillment_events event WHERE event.audit_log_id = NEW.audit_log_id
    ) THEN
      RAISE EXCEPTION 'admin authority audit evidence was already consumed'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM fulfillments fulfillment
    WHERE fulfillment.id = NEW.fulfillment_id AND fulfillment.order_id = NEW.order_id
  ) THEN
    RAISE EXCEPTION 'fulfillment event order does not own fulfillment'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.sequence = 1 THEN
    IF NEW.from_status IS NOT NULL OR NEW.to_status <> 'PENDING' THEN
      RAISE EXCEPTION 'first fulfillment event must create PENDING state'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT * INTO previous_event
  FROM fulfillment_events
  WHERE fulfillment_id = NEW.fulfillment_id AND sequence = NEW.sequence - 1;

  IF previous_event.id IS NULL OR NEW.from_status <> previous_event.to_status THEN
    RAISE EXCEPTION 'fulfillment event sequence must be contiguous'
      USING ERRCODE = '23514';
  END IF;
  IF NOT (
    (NEW.from_status = 'PENDING' AND NEW.to_status IN ('PREPARING', 'ON_HOLD', 'CANCELED'))
    OR (NEW.from_status = 'PREPARING' AND NEW.to_status IN ('DELIVERED', 'ON_HOLD', 'CANCELED'))
    OR (NEW.from_status = 'ON_HOLD' AND NEW.to_status IN ('PENDING', 'PREPARING', 'CANCELED'))
  ) THEN
    RAISE EXCEPTION 'fulfillment event contains an invalid transition'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_gift_variant_label_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  revision_gift_id uuid;
  variant_gift_id uuid;
BEGIN
  SELECT revision.gift_id INTO revision_gift_id
    FROM gift_revision_translations translation
    JOIN gift_revisions revision ON revision.id = translation.gift_revision_id
    WHERE translation.id = NEW.gift_translation_id;
  SELECT gift_id INTO variant_gift_id FROM gift_variants WHERE id = NEW.gift_variant_id;
  IF revision_gift_id IS NULL OR variant_gift_id IS NULL OR revision_gift_id <> variant_gift_id THEN
    RAISE EXCEPTION 'gift variant label crosses gift ownership' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_homepage_slot_translation_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  translation_revision_id uuid;
  matching_slot_count integer;
BEGIN
  SELECT homepage_revision_id INTO translation_revision_id
    FROM homepage_revision_translations WHERE id = NEW.homepage_translation_id;
  SELECT count(*) INTO matching_slot_count FROM homepage_slots
    WHERE homepage_revision_id = translation_revision_id AND slot_key = NEW.slot_key;
  IF matching_slot_count <> 1 THEN
    RAISE EXCEPTION 'homepage slot label crosses revision ownership' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_idol_alias_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE draft public.idol_revision_alias_sets%ROWTYPE; previous public.idol_revision_alias_reviews%ROWTYPE;
BEGIN
  SELECT * INTO draft FROM public.idol_revision_alias_sets WHERE id = NEW.alias_set_id FOR UPDATE;
  SELECT * INTO previous FROM public.idol_revision_alias_reviews WHERE alias_set_id = NEW.alias_set_id ORDER BY sequence DESC LIMIT 1;
  IF previous.id IS NULL THEN
    IF NEW.sequence <> 1 OR NEW.status <> 'DRAFT' THEN RAISE EXCEPTION 'alias review must begin with draft sequence one' USING ERRCODE = '23514'; END IF;
  ELSIF NEW.sequence <> previous.sequence + 1 OR NOT ((previous.status = 'DRAFT' AND NEW.status = 'IN_REVIEW') OR (previous.status = 'IN_REVIEW' AND NEW.status = 'APPROVED')) THEN
    RAISE EXCEPTION 'invalid alias review transition' USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'DRAFT' THEN
    IF NEW.submitted_at IS NOT NULL OR NEW.reviewer_id IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.reviewed_content_hash IS NOT NULL OR NEW.audit_log_id <> draft.audit_log_id THEN
      RAISE EXCEPTION 'initial alias review cannot carry approval evidence' USING ERRCODE = '23514'; END IF;
  ELSIF NEW.status = 'IN_REVIEW' THEN
    IF NEW.submitted_at IS NULL OR NEW.submitted_at < draft.edited_at OR NEW.reviewer_id IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.reviewed_content_hash IS NOT NULL THEN
      RAISE EXCEPTION 'invalid alias submission evidence' USING ERRCODE = '23514'; END IF;
  ELSE
    IF NEW.submitted_at IS NOT NULL OR NEW.reviewer_id IS NULL OR NEW.reviewer_id = draft.editor_id OR NEW.reviewed_at IS NULL OR NEW.reviewed_at < previous.submitted_at OR NEW.reviewed_content_hash IS DISTINCT FROM draft.content_hash THEN
      RAISE EXCEPTION 'alias approval must independently bind immutable content' USING ERRCODE = '23514'; END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_notification_content_revision_ref()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  revision_lifecycle text;
BEGIN
  CASE NEW.content_type
    WHEN 'IDOL' THEN
      SELECT lifecycle INTO revision_lifecycle FROM idol_revisions WHERE id = NEW.idol_revision_id;
    WHEN 'GIFT' THEN
      SELECT lifecycle INTO revision_lifecycle FROM gift_revisions WHERE id = NEW.gift_revision_id;
    WHEN 'HOMEPAGE' THEN
      SELECT lifecycle INTO revision_lifecycle FROM homepage_revisions WHERE id = NEW.homepage_revision_id;
    WHEN 'POLICY' THEN
      SELECT lifecycle INTO revision_lifecycle FROM policy_revisions WHERE id = NEW.policy_revision_id;
    WHEN 'MEDIA_METADATA' THEN
      SELECT lifecycle INTO revision_lifecycle FROM media_metadata_revisions WHERE id = NEW.media_metadata_revision_id;
  END CASE;

  IF revision_lifecycle IS NULL OR revision_lifecycle NOT IN ('PUBLISHED', 'SUPERSEDED', 'ARCHIVED') THEN
    RAISE EXCEPTION 'notification content reference must point to a published historical revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_notification_delivery_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  expected_sequence bigint;
BEGIN
  SELECT COALESCE(max(sequence), 0) + 1 INTO expected_sequence
  FROM notification_delivery_attempts
  WHERE notification_delivery_id = NEW.notification_delivery_id;

  IF NEW.sequence <> expected_sequence THEN
    RAISE EXCEPTION 'notification delivery attempt sequence must be contiguous'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_access_audit_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.token_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.order_access_tokens token
    WHERE token.id = NEW.token_id AND token.order_id = NEW.order_id
  ) THEN
    RAISE EXCEPTION 'order access audit token must belong to its order' USING ERRCODE = '23514';
  END IF;
  IF NEW.session_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.order_access_sessions session
    WHERE session.id = NEW.session_id AND session.order_id = NEW.order_id
      AND (NEW.token_id IS NULL OR session.exchanged_token_id = NEW.token_id)
  ) THEN
    RAISE EXCEPTION 'order access audit session must belong to its order and token' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_payment_attempt_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  transition_allowed boolean;
  pinned_config_count integer;
  payable_order boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'CREATED' OR NEW.version <> 1
       OR NEW.status_evidence_kind <> 'ATTEMPT_CREATED'
       OR NEW.provider_event_id IS NOT NULL OR NEW.evidence_audit_log_id IS NOT NULL
       OR NEW.provider_call_started OR NEW.external_reference IS NOT NULL
       OR NEW.refund_occupied_minor <> 0 THEN
      RAISE EXCEPTION 'new payment attempt must start as an uncalled CREATED attempt'
        USING ERRCODE = '23514';
    END IF;
    SELECT count(*) INTO pinned_config_count
      FROM config_versions config
      WHERE config.id = NEW.config_version_id
        AND config.config_kind = 'PAYMENT_ROUTING'
        AND config.version = NEW.config_version
        AND config.lifecycle IN ('PUBLISHED', 'SUPERSEDED');
    IF pinned_config_count <> 1 THEN
      RAISE EXCEPTION 'payment attempt must pin an immutable published config version'
        USING ERRCODE = '23514';
    END IF;
    SELECT true INTO payable_order
      FROM orders
      WHERE id = NEW.order_id
        AND order_status = 'PENDING_PAYMENT'
        AND payment_status IN ('UNPAID', 'PENDING')
      FOR UPDATE;
    IF COALESCE(payable_order, false) = false OR EXISTS (
      SELECT 1 FROM payment_attempts predecessor
      WHERE predecessor.order_id = NEW.order_id
        AND predecessor.status NOT IN ('FAILED', 'CANCELED', 'EXPIRED')
    ) THEN
      RAISE EXCEPTION 'payment attempt retry requires a payable order and only terminal failed predecessors'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF (to_jsonb(NEW) - 'refund_occupied_minor') IS NOT DISTINCT FROM
     (to_jsonb(OLD) - 'refund_occupied_minor') THEN
    IF NEW.refund_occupied_minor IS DISTINCT FROM OLD.refund_occupied_minor
       AND pg_trigger_depth() < 2 THEN
      RAISE EXCEPTION 'refund capacity can only change from a refund trigger'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF (to_jsonb(NEW) - 'status' - 'provider_call_started' - 'external_reference'
      - 'action_type' - 'action_ciphertext' - 'action_encrypted_data_key'
      - 'action_key_version' - 'action_expires_at' - 'action_poll_after_ms'
      - 'status_evidence_kind' - 'provider_event_id' - 'evidence_audit_log_id'
      - 'evidence_reason_code' - 'version' - 'updated_at' - 'succeeded_at'
      - 'terminated_at') IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'provider_call_started' - 'external_reference'
      - 'action_type' - 'action_ciphertext' - 'action_encrypted_data_key'
      - 'action_key_version' - 'action_expires_at' - 'action_poll_after_ms'
      - 'status_evidence_kind' - 'provider_event_id' - 'evidence_audit_log_id'
      - 'evidence_reason_code' - 'version' - 'updated_at' - 'succeeded_at'
      - 'terminated_at') THEN
    RAISE EXCEPTION 'payment attempt route, amount, locale, and identity are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.refund_occupied_minor <> OLD.refund_occupied_minor THEN
    RAISE EXCEPTION 'refund capacity can only change through a refund transaction'
      USING ERRCODE = '55000';
  END IF;
  IF OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'EXPIRED') THEN
    RAISE EXCEPTION 'terminal payment attempts are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'payment attempt transition requires one version increment and a later timestamp'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.provider_call_started AND NOT NEW.provider_call_started THEN
    RAISE EXCEPTION 'provider_call_started cannot be cleared'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.external_reference IS NOT NULL
     AND NEW.external_reference IS DISTINCT FROM OLD.external_reference THEN
    RAISE EXCEPTION 'provider external reference is immutable once bound'
      USING ERRCODE = '55000';
  END IF;

  transition_allowed := CASE OLD.status
    WHEN 'CREATED' THEN NEW.status IN (
      'REQUIRES_ACTION', 'PROCESSING', 'SUCCEEDED', 'FAILED', 'CANCELED', 'EXPIRED', 'UNKNOWN'
    )
    WHEN 'REQUIRES_ACTION' THEN NEW.status IN (
      'PROCESSING', 'SUCCEEDED', 'FAILED', 'CANCELED', 'EXPIRED', 'UNKNOWN'
    )
    WHEN 'PROCESSING' THEN NEW.status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'EXPIRED', 'UNKNOWN')
    WHEN 'UNKNOWN' THEN NEW.status IN ('PROCESSING', 'SUCCEEDED', 'FAILED', 'CANCELED', 'EXPIRED') OR (NEW.status='REQUIRES_ACTION' AND NEW.status_evidence_kind='AUTHENTICATED_RECONCILE' AND NEW.action_type IN('REDIRECT','PROVIDER_HOSTED_IFRAME','PROVIDER_COMPONENT','QR_CODE') AND NEW.action_ciphertext IS NOT NULL AND NEW.action_encrypted_data_key IS NOT NULL AND NEW.action_key_version IS NOT NULL)
    ELSE false
  END;
  IF NEW.status = OLD.status OR NOT transition_allowed THEN
    RAISE EXCEPTION 'invalid payment attempt transition: % -> %', OLD.status, NEW.status
      USING ERRCODE = '23514';
  END IF;

  IF NEW.status = 'UNKNOWN' AND NEW.status_evidence_kind <> 'NETWORK_UNCERTAINTY' THEN
    RAISE EXCEPTION 'UNKNOWN payment requires network uncertainty evidence'
      USING ERRCODE = '23514';
  ELSIF OLD.status = 'CREATED' AND NEW.status IN ('REQUIRES_ACTION', 'PROCESSING')
        AND NEW.status_evidence_kind <> 'CREATE_RESULT' THEN
    RAISE EXCEPTION 'initial provider action requires CREATE_RESULT evidence'
      USING ERRCODE = '23514';
  ELSIF NEW.status = 'CANCELED' AND OLD.status = 'CREATED' AND NOT NEW.provider_call_started
        AND NEW.status_evidence_kind <> 'AUDITED_BUSINESS_CANCEL' THEN
    RAISE EXCEPTION 'pre-provider cancellation requires audited evidence'
      USING ERRCODE = '23514';
  ELSIF NEW.status = 'EXPIRED' AND OLD.status = 'CREATED' AND NOT NEW.provider_call_started
        AND NEW.status_evidence_kind <> 'SAFE_EXPIRY' THEN
    RAISE EXCEPTION 'pre-provider expiry requires safe-expiry evidence'
      USING ERRCODE = '23514';
  ELSIF NOT (
    NEW.status = 'UNKNOWN'
    OR (OLD.status = 'CREATED' AND NEW.status IN ('REQUIRES_ACTION', 'PROCESSING'))
    OR (NEW.status = 'CANCELED' AND OLD.status = 'CREATED' AND NOT NEW.provider_call_started)
    OR (NEW.status = 'EXPIRED' AND OLD.status = 'CREATED' AND NOT NEW.provider_call_started)
  ) AND NEW.status_evidence_kind NOT IN ('VERIFIED_WEBHOOK', 'AUTHENTICATED_RECONCILE') THEN
    RAISE EXCEPTION 'payment terminal or reconciled transition requires trusted provider evidence'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.status_evidence_kind IN ('VERIFIED_WEBHOOK', 'AUTHENTICATED_RECONCILE')
     AND NEW.provider_event_id IS NULL THEN
    RAISE EXCEPTION 'trusted payment evidence requires provider_event_id'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind = 'VERIFIED_WEBHOOK'
        AND NEW.evidence_audit_log_id IS NOT NULL THEN
    RAISE EXCEPTION 'verified webhook evidence cannot carry reconcile audit evidence'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind = 'AUTHENTICATED_RECONCILE'
        AND NEW.evidence_audit_log_id IS NULL THEN
    RAISE EXCEPTION 'reconciled payment evidence requires its audit_log_id'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind = 'AUDITED_BUSINESS_CANCEL'
        AND (NEW.evidence_audit_log_id IS NULL OR NEW.provider_event_id IS NOT NULL) THEN
    RAISE EXCEPTION 'audited business cancellation requires only audit_log_id'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind IN ('CREATE_RESULT', 'NETWORK_UNCERTAINTY', 'SAFE_EXPIRY')
        AND (NEW.provider_event_id IS NOT NULL OR NEW.evidence_audit_log_id IS NOT NULL) THEN
    RAISE EXCEPTION 'local payment evidence cannot carry provider or audit evidence IDs'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_payment_config_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  provider_config record;
  enabled_provider_count integer;
  enabled_rule_count integer;
  rule_version_count integer;
  incomplete_rule_count integer;
BEGIN
  IF NEW.config_kind <> 'PAYMENT_ROUTING' OR NEW.lifecycle <> 'PUBLISHED'
     OR (TG_OP = 'UPDATE' AND OLD.lifecycle = NEW.lifecycle) THEN
    RETURN NEW;
  END IF;

  SELECT count(*) FILTER (WHERE config.enabled),
         count(DISTINCT rule.rule_version) FILTER (WHERE rule.enabled),
         count(*) FILTER (WHERE rule.enabled)
    INTO enabled_provider_count, rule_version_count, enabled_rule_count
    FROM payment_provider_configs config
    LEFT JOIN payment_route_rules rule
      ON rule.config_version_id = config.config_version_id
      AND rule.provider_config_id = config.id
    WHERE config.config_version_id = NEW.id;

  IF enabled_provider_count = 0 OR enabled_rule_count = 0 OR rule_version_count <> 1 THEN
    RAISE EXCEPTION 'published payment config requires enabled providers and one non-empty rule-set version'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*) INTO incomplete_rule_count
    FROM payment_route_rules rule
    JOIN payment_provider_configs config ON config.id = rule.provider_config_id
    JOIN payment_provider_accounts account ON account.id = rule.provider_account_id
    JOIN merchant_entities merchant ON merchant.id = account.merchant_entity_id
    WHERE rule.config_version_id = NEW.id
      AND rule.enabled
      AND (
        NOT config.enabled
        OR account.status NOT IN ('INTERNAL', 'ACTIVE')
        OR account.health_status <> 'HEALTHY'
        OR merchant.status <> 'ACTIVE'
        OR NOT EXISTS (
          SELECT 1 FROM payment_route_rule_countries country
          WHERE country.payment_route_rule_id = rule.id
        )
        OR NOT EXISTS (
          SELECT 1 FROM payment_route_rule_markets market
          WHERE market.payment_route_rule_id = rule.id
        )
        OR NOT EXISTS (
          SELECT 1 FROM payment_route_rule_currencies currency
          WHERE currency.payment_route_rule_id = rule.id
        )
      );
  IF incomplete_rule_count <> 0 THEN
    RAISE EXCEPTION 'published payment routes require enabled healthy accounts and explicit country, market, and currency scopes'
      USING ERRCODE = '23514';
  END IF;

  FOR provider_config IN
    SELECT id FROM payment_provider_configs
    WHERE config_version_id = NEW.id AND enabled
  LOOP
    PERFORM assert_payment_provider_translation_package(provider_config.id);
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_payment_config_publication_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  target_lifecycle text;
  replaced_config_version_id uuid;
BEGIN
  SELECT lifecycle INTO target_lifecycle
    FROM config_versions
    WHERE id = NEW.config_version_id AND config_kind = 'PAYMENT_ROUTING';
  IF target_lifecycle NOT IN ('PUBLISHED', 'SUPERSEDED') THEN
    RAISE EXCEPTION 'payment config publication must reference immutable published evidence'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.replaces_publication_id IS NOT NULL THEN
    SELECT config_version_id INTO replaced_config_version_id
      FROM payment_config_publications WHERE id = NEW.replaces_publication_id;
    IF replaced_config_version_id IS NULL OR replaced_config_version_id = NEW.config_version_id THEN
      RAISE EXCEPTION 'payment config replacement must reference a different prior publication'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_payment_provider_health_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  previous_event public.payment_provider_health_events%ROWTYPE;
BEGIN
  IF NEW.sequence > 1 THEN
    SELECT * INTO previous_event
      FROM public.payment_provider_health_events
      WHERE provider_account_id = NEW.provider_account_id
        AND sequence = NEW.sequence - 1;
    IF previous_event.id IS NULL OR NEW.from_status <> previous_event.to_status THEN
      RAISE EXCEPTION 'payment provider health event sequence is not contiguous'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_price_parent_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  book_from timestamptz;
  book_until timestamptz;
  book_lifecycle text;
BEGIN
  SELECT valid_from, valid_until, lifecycle
    INTO book_from, book_until, book_lifecycle
    FROM price_books
    WHERE id = NEW.price_book_id AND revision = NEW.price_book_revision;
  IF book_from IS NULL OR NEW.valid_from < book_from
     OR (book_until IS NOT NULL AND (NEW.valid_to IS NULL OR NEW.valid_to > book_until)) THEN
    RAISE EXCEPTION 'price validity must be contained by its price-book revision'
      USING ERRCODE = '23514';
  END IF;
  IF (NEW.status = 'PUBLISHED') <> (book_lifecycle = 'PUBLISHED') THEN
    RAISE EXCEPTION 'price publication status must match its price-book revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_provider_event_association()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  event_row provider_events%ROWTYPE;
  attempt_row payment_attempts%ROWTYPE;
BEGIN
  SELECT * INTO event_row FROM provider_events WHERE id = NEW.provider_event_id;
  IF event_row.id IS NULL THEN
    RAISE EXCEPTION 'provider event association references missing event'
      USING ERRCODE = '23503';
  END IF;
  IF EXISTS (
    SELECT 1 FROM provider_event_associations
    WHERE provider_event_id = NEW.provider_event_id AND association_status = 'MATCHED'
  ) THEN
    RAISE EXCEPTION 'matched provider event association is terminal'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.association_status = 'MATCHED' THEN
    SELECT * INTO attempt_row FROM payment_attempts WHERE id = NEW.payment_attempt_id;
    IF attempt_row.id IS NULL
       OR attempt_row.provider_account_id <> event_row.provider_account_id
       OR attempt_row.environment <> event_row.environment
       OR attempt_row.currency <> event_row.currency
       OR (attempt_row.external_reference IS NOT NULL
          AND attempt_row.external_reference <> event_row.external_payment_reference)
       OR (event_row.event_type = 'PAYMENT_STATUS'
          AND attempt_row.amount_minor <> event_row.amount_minor) THEN
      RAISE EXCEPTION 'provider event does not match the persisted payment attempt'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_refund_mutation_and_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  old_contribution minor_amount := 0;
  new_contribution minor_amount := 0;
  capacity_delta bigint;
  updated_attempt_id uuid;
  order_current_attempt_id uuid;
  order_payment_status text;
  transition_allowed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'REQUESTED' OR NEW.version <> 1
       OR NEW.status_evidence_kind <> 'REFUND_REQUESTED'
       OR NEW.provider_event_id IS NOT NULL OR NEW.evidence_audit_log_id IS NOT NULL THEN
      RAISE EXCEPTION 'new refund must start as REQUESTED without provider evidence'
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.audit_logs audit
      WHERE audit.id = NEW.requested_audit_log_id
        AND audit.action = 'REFUND_REQUESTED'
        AND audit.subject_type = 'REFUND'
        AND audit.subject_id = NEW.id
        AND audit.outcome = 'SUCCEEDED'
        AND audit.reason_code IS NOT NULL
        AND audit.request_id IS NOT NULL
        AND audit.correlation_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'refund request requires matching audit evidence'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    IF (to_jsonb(NEW) - 'status' - 'processed_amount_minor' - 'status_evidence_kind'
        - 'provider_event_id' - 'evidence_audit_log_id' - 'version'
        - 'updated_at' - 'completed_at') IS DISTINCT FROM
       (to_jsonb(OLD) - 'status' - 'processed_amount_minor' - 'status_evidence_kind'
        - 'provider_event_id' - 'evidence_audit_log_id' - 'version'
        - 'updated_at' - 'completed_at') THEN
      RAISE EXCEPTION 'refund identity, allocation amount, capture, and provider reference are immutable'
        USING ERRCODE = '55000';
    END IF;
    IF OLD.status IN ('SUCCEEDED', 'FAILED') THEN
      RAISE EXCEPTION 'terminal refunds are immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
      RAISE EXCEPTION 'refund transition requires one version increment and a later timestamp'
        USING ERRCODE = '23514';
    END IF;
    transition_allowed := CASE OLD.status
      WHEN 'REQUESTED' THEN NEW.status = 'SUBMITTING'
      WHEN 'SUBMITTING' THEN NEW.status IN ('PROCESSING', 'SUCCEEDED', 'FAILED', 'UNKNOWN')
      WHEN 'PROCESSING' THEN NEW.status IN ('SUCCEEDED', 'FAILED', 'UNKNOWN')
      WHEN 'UNKNOWN' THEN NEW.status IN ('PROCESSING', 'SUCCEEDED', 'FAILED')
      ELSE false
    END;
    IF NEW.status = OLD.status OR NOT transition_allowed THEN
      RAISE EXCEPTION 'invalid refund transition: % -> %', OLD.status, NEW.status
        USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'REQUESTED' AND NEW.status = 'SUBMITTING'
       AND NEW.status_evidence_kind <> 'SUBMIT_COMMAND' THEN
      RAISE EXCEPTION 'refund submission requires SUBMIT_COMMAND evidence'
        USING ERRCODE = '23514';
    ELSIF NEW.status = 'UNKNOWN'
       AND NEW.status_evidence_kind <> 'NETWORK_UNCERTAINTY' THEN
      RAISE EXCEPTION 'UNKNOWN refund requires network uncertainty evidence'
        USING ERRCODE = '23514';
    ELSIF NOT (OLD.status = 'REQUESTED' AND NEW.status = 'SUBMITTING')
       AND NEW.status <> 'UNKNOWN'
       AND NEW.status_evidence_kind NOT IN ('VERIFIED_WEBHOOK', 'AUTHENTICATED_RECONCILE') THEN
      RAISE EXCEPTION 'refund provider result requires trusted provider evidence'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.status_evidence_kind IN ('VERIFIED_WEBHOOK', 'AUTHENTICATED_RECONCILE')
     AND NEW.provider_event_id IS NULL THEN
    RAISE EXCEPTION 'trusted refund evidence requires provider_event_id'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind = 'VERIFIED_WEBHOOK'
        AND NEW.evidence_audit_log_id IS NOT NULL THEN
    RAISE EXCEPTION 'verified refund webhook cannot carry reconcile audit evidence'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind = 'AUTHENTICATED_RECONCILE'
        AND NEW.evidence_audit_log_id IS NULL THEN
    RAISE EXCEPTION 'reconciled refund requires its audit_log_id'
      USING ERRCODE = '23514';
  ELSIF NEW.status_evidence_kind IN ('REFUND_REQUESTED', 'SUBMIT_COMMAND', 'NETWORK_UNCERTAINTY')
        AND (NEW.provider_event_id IS NOT NULL OR NEW.evidence_audit_log_id IS NOT NULL) THEN
    RAISE EXCEPTION 'local refund evidence cannot carry provider or audit evidence IDs'
      USING ERRCODE = '23514';
  END IF;

  SELECT current_payment_attempt_id, payment_status
    INTO order_current_attempt_id, order_payment_status
    FROM orders WHERE id = NEW.order_id;
  IF order_current_attempt_id IS DISTINCT FROM NEW.payment_attempt_id
     OR order_payment_status NOT IN ('PAID', 'PARTIALLY_REFUNDED', 'REFUNDED') THEN
    RAISE EXCEPTION 'refund requires the order current captured payment attempt'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status <> 'FAILED' THEN
    old_contribution := OLD.requested_amount_minor;
  END IF;
  IF NEW.status <> 'FAILED' THEN
    new_contribution := NEW.requested_amount_minor;
  END IF;
  capacity_delta := new_contribution::bigint - old_contribution::bigint;

  IF capacity_delta <> 0 OR TG_OP = 'INSERT' THEN
    UPDATE payment_attempts
      SET refund_occupied_minor = refund_occupied_minor + capacity_delta
      WHERE id = NEW.payment_attempt_id
        AND order_id = NEW.order_id
        AND status = 'SUCCEEDED'
        AND currency = NEW.captured_currency
        AND amount_minor = NEW.captured_amount_minor
        AND refund_occupied_minor + capacity_delta BETWEEN 0 AND amount_minor
      RETURNING id INTO updated_attempt_id;
    IF updated_attempt_id IS NULL THEN
      RAISE EXCEPTION 'refund capacity exceeded or captured payment attempt is not eligible'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_revision_lifecycle_times()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.lifecycle <> 'DRAFT' THEN
    RAISE EXCEPTION 'new revisions must start in DRAFT' USING ERRCODE = '23514';
  END IF;
  IF NEW.lifecycle = 'DRAFT' AND (
    NEW.validated_at IS NOT NULL OR NEW.published_at IS NOT NULL
    OR NEW.superseded_at IS NOT NULL OR NEW.archived_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'draft revisions cannot carry lifecycle timestamps'
      USING ERRCODE = '23514';
  ELSIF NEW.lifecycle = 'VALIDATED' AND (
    NEW.validated_at IS NULL OR NEW.published_at IS NOT NULL
    OR NEW.superseded_at IS NOT NULL OR NEW.archived_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'validated revisions require only validated_at'
      USING ERRCODE = '23514';
  ELSIF NEW.lifecycle = 'PUBLISHED' AND (
    NEW.validated_at IS NULL OR NEW.published_at IS NULL
    OR NEW.superseded_at IS NOT NULL OR NEW.archived_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'published revisions require validation and publication timestamps'
      USING ERRCODE = '23514';
  ELSIF NEW.lifecycle = 'SUPERSEDED' AND (
    NEW.validated_at IS NULL OR NEW.published_at IS NULL
    OR NEW.superseded_at IS NULL OR NEW.archived_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'superseded revisions require validation, publication, and supersession timestamps'
      USING ERRCODE = '23514';
  ELSIF NEW.lifecycle = 'ARCHIVED' AND (
    NEW.validated_at IS NULL OR NEW.published_at IS NULL
    OR NEW.superseded_at IS NULL OR NEW.archived_at IS NULL
  ) THEN
    RAISE EXCEPTION 'archived revisions require the complete lifecycle timeline'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.validated_at IS NOT NULL AND NEW.validated_at < NEW.created_at THEN
    RAISE EXCEPTION 'validated_at cannot precede created_at' USING ERRCODE = '23514';
  END IF;
  IF NEW.published_at IS NOT NULL AND NEW.validated_at IS NULL THEN
    RAISE EXCEPTION 'published_at requires validated_at' USING ERRCODE = '23514';
  END IF;
  IF NEW.published_at IS NOT NULL AND NEW.published_at < NEW.validated_at THEN
    RAISE EXCEPTION 'published_at cannot precede validated_at' USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_at IS NOT NULL AND NEW.published_at IS NULL THEN
    RAISE EXCEPTION 'superseded_at requires published_at' USING ERRCODE = '23514';
  END IF;
  IF NEW.superseded_at IS NOT NULL AND NEW.superseded_at < NEW.published_at THEN
    RAISE EXCEPTION 'superseded_at cannot precede published_at' USING ERRCODE = '23514';
  END IF;
  IF NEW.archived_at IS NOT NULL AND NEW.superseded_at IS NOT NULL
     AND NEW.archived_at < NEW.superseded_at THEN
    RAISE EXCEPTION 'archived_at cannot precede superseded_at' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_support_intent_moderation_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  evidence public.moderation_evidence%ROWTYPE;
  new_decision boolean := TG_OP = 'INSERT';
BEGIN
  IF NEW.moderation_decision_kind IS DISTINCT FROM 'AUTOMATED' THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    new_decision :=
      OLD.moderation_status IS DISTINCT FROM NEW.moderation_status
      OR OLD.moderation_reason_code IS DISTINCT FROM NEW.moderation_reason_code
      OR OLD.moderation_decision_kind IS DISTINCT FROM NEW.moderation_decision_kind
      OR OLD.moderation_rule_version IS DISTINCT FROM NEW.moderation_rule_version
      OR OLD.moderation_evidence_id IS DISTINCT FROM NEW.moderation_evidence_id
      OR OLD.reviewed_at IS DISTINCT FROM NEW.reviewed_at;
  END IF;

  SELECT candidate.* INTO evidence
  FROM public.moderation_evidence candidate
  WHERE candidate.id = NEW.moderation_evidence_id
    AND candidate.support_intent_id = NEW.id;

  IF evidence.id IS NULL
     OR evidence.support_intent_version > NEW.version
     OR evidence.rule_version <> NEW.moderation_rule_version
     OR evidence.decision <> NEW.moderation_status
     OR evidence.reason_code IS DISTINCT FROM NEW.moderation_reason_code
     OR evidence.decided_at <> NEW.reviewed_at THEN
    RAISE EXCEPTION 'automated moderation must bind exact immutable evidence'
      USING ERRCODE = '23514';
  END IF;

  IF new_decision AND evidence.support_intent_version <> NEW.version THEN
    RAISE EXCEPTION 'automated moderation evidence must bind the decided support intent version'
      USING ERRCODE = '23514';
  END IF;

  IF (NEW.privacy_state <> 'PURGED' OR new_decision)
     AND (
       NEW.fan_message_ciphertext IS NULL
       OR evidence.content_ciphertext_sha256 <>
          pg_catalog.encode(pg_catalog.sha256(NEW.fan_message_ciphertext), 'hex')
     ) THEN
    RAISE EXCEPTION 'automated moderation evidence must bind the current encrypted message'
      USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_translation_review_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  translation_table regclass := TG_ARGV[0]::regclass;
  translation_column text := TG_ARGV[1];
  parent_table regclass := TG_ARGV[2]::regclass;
  parent_column text := TG_ARGV[3];
  editor uuid;
  edited timestamptz;
  localized_hash sha256_hex;
  english_hash sha256_hex;
  translation_origin text;
  parent_lifecycle text;
  previous_sequence bigint;
  previous_status text;
  previous_submitted_at timestamptz;
BEGIN
  EXECUTE format(
    'SELECT t.editor_id, t.edited_at, t.source_hash, t.translated_from_source_hash, t.origin, p.lifecycle '
    'FROM %s t JOIN %s p ON p.id = t.%I WHERE t.id = $1',
    translation_table,
    parent_table,
    parent_column
  ) INTO editor, edited, localized_hash, english_hash, translation_origin, parent_lifecycle
    USING (to_jsonb(NEW) ->> translation_column)::uuid;

  IF editor IS NULL THEN
    RAISE EXCEPTION 'translation review references a missing translation'
      USING ERRCODE = '23503';
  END IF;
  IF parent_lifecycle IN ('PUBLISHED', 'SUPERSEDED', 'ARCHIVED') THEN
    RAISE EXCEPTION 'published translation review evidence is immutable'
      USING ERRCODE = '55000';
  END IF;

  EXECUTE format(
    'SELECT sequence, status, submitted_at FROM %s WHERE %I = $1 ORDER BY sequence DESC LIMIT 1',
    TG_RELID::regclass,
    translation_column
  ) INTO previous_sequence, previous_status, previous_submitted_at
    USING (to_jsonb(NEW) ->> translation_column)::uuid;

  IF previous_sequence IS NULL THEN
    IF NEW.sequence <> 1 OR NEW.status <> 'DRAFT' THEN
      RAISE EXCEPTION 'the first translation review event must be DRAFT sequence 1'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.sequence <> previous_sequence + 1 THEN
    RAISE EXCEPTION 'translation review sequence must increment exactly once'
      USING ERRCODE = '23514';
  ELSIF previous_status = 'APPROVED' THEN
    RAISE EXCEPTION 'approved translation evidence is terminal for this revision'
      USING ERRCODE = '55000';
  ELSIF NOT (
    (previous_status = 'DRAFT' AND NEW.status = 'IN_REVIEW')
    OR (previous_status = 'IN_REVIEW' AND NEW.status = 'APPROVED')
  ) THEN
    RAISE EXCEPTION 'invalid translation review transition: % -> %', previous_status, NEW.status
      USING ERRCODE = '23514';
  END IF;

  IF NEW.status = 'DRAFT' THEN
    IF NEW.submitted_at IS NOT NULL OR NEW.reviewer_id IS NOT NULL
       OR NEW.reviewed_at IS NOT NULL OR NEW.reviewed_source_hash IS NOT NULL
       OR NEW.reviewed_content_hash IS NOT NULL THEN
      RAISE EXCEPTION 'draft review events cannot carry review evidence'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.status = 'IN_REVIEW' THEN
    IF NEW.submitted_at IS NULL OR NEW.submitted_at < edited
       OR NEW.reviewer_id IS NOT NULL OR NEW.reviewed_at IS NOT NULL
       OR NEW.reviewed_source_hash IS NOT NULL OR NEW.reviewed_content_hash IS NOT NULL THEN
      RAISE EXCEPTION 'in-review evidence is inconsistent with the translation edit'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.status = 'APPROVED' THEN
    IF NEW.submitted_at IS NOT NULL OR NEW.reviewer_id IS NULL OR NEW.reviewed_at IS NULL
       OR NEW.reviewed_source_hash IS NULL OR NEW.reviewed_content_hash IS NULL
       OR NEW.reviewer_id = editor OR NEW.reviewed_at < edited
       OR NEW.reviewed_at < previous_submitted_at
       OR NEW.reviewed_source_hash <> english_hash
       OR NEW.reviewed_content_hash <> localized_hash THEN
      RAISE EXCEPTION 'approval must be independent and bind current source/content hashes'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_translation_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.locale = 'en' AND NEW.source_hash <> NEW.translated_from_source_hash THEN
    RAISE EXCEPTION 'English source and translated-from hashes must match'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.origin = 'IMPORT' AND NEW.import_batch_id IS NULL THEN
    RAISE EXCEPTION 'imported translations require import_batch_id'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.origin <> 'IMPORT' AND NEW.import_batch_id IS NOT NULL THEN
    RAISE EXCEPTION 'only imported translations may carry import_batch_id'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$
